window.RAFIQ_TEMPLATES = {"base.html": "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover\">\n<title>{% block title %}رفيق{% endblock %} — من دهفة للتقنية<\/title>\n<link rel=\"icon\" href=\"{{ url_for('static', filename='brand/favicon.png') }}\">\n<link rel=\"stylesheet\" href=\"{{ url_for('static', filename='style.css') }}\">\n<\/head>\n<body class=\"{% block bodyclass %}{% endblock %}\">\n<header class=\"topbar no-print\">\n  <div class=\"brand\">\n    <img src=\"{{ url_for('static', filename='brand/logo_header_white.png') }}\" alt=\"رفيق\">\n  <\/div>\n  <div class=\"grow\"><\/div>\n  {% if u %}<div class=\"who\">{{ u.name }}<\/div>\n  <a href=\"{{ url_for('logout') }}\">خروج<\/a>{% endif %}\n<\/header>\n\n<nav class=\"nav no-print\">\n  {% if u %}\n    {% if u.role == 'owner' %}\n      <a href=\"{{ url_for('home') }}\" class=\"{{ 'on' if request.endpoint=='home' }}\">اللوحة<\/a>\n    {% endif %}\n    <a href=\"{{ url_for('pos') }}\" class=\"{{ 'on' if request.endpoint=='pos' }}\">🛒 بيع<\/a>\n    <a href=\"{{ url_for('customers') }}\" class=\"{{ 'on' if request.endpoint in ('customers','customer_detail') }}\">الديون<\/a>\n    <a href=\"{{ url_for('find_item') }}\" class=\"{{ 'on' if request.endpoint=='find_item' }}\">📍 أين الصنف؟<\/a>\n    <a href=\"{{ url_for('cash') }}\" class=\"{{ 'on' if request.endpoint=='cash' }}\">الصندوق<\/a>\n    {% if u.role == 'owner' %}\n      <a href=\"{{ url_for('reports') }}\" class=\"{{ 'on' if request.endpoint=='reports' }}\">التقارير<\/a>\n      <a href=\"{{ url_for('products') }}\" class=\"{{ 'on' if request.endpoint in ('products','product_new','product_edit') }}\">الأصناف<\/a>\n      <a href=\"{{ url_for('imports') }}\" class=\"{{ 'on' if request.endpoint=='imports' }}\">الاستيراد<\/a>\n      <a href=\"{{ url_for('settings') }}\" class=\"{{ 'on' if request.endpoint in ('settings','users_page') }}\">الإعدادات<\/a>\n    {% endif %}\n  {% endif %}\n<\/nav>\n\n{% block wrap %}\n<div class=\"wrap\">\n  {% set msgs = get_flashed_messages(with_categories=true) %}\n    {% for cat, m in msgs %}<div class=\"flash {{ cat }}\">{{ m }}<\/div>{% endfor %}\n  \n  {% block content %}{% endblock %}\n<\/div>\n{% endblock %}\n\n<script>window.COUNTRY_CODE = \"{{ S.country_code or '967' }}\";<\/script>\n<script src=\"{{ url_for('static', filename='app.js') }}\"><\/script>\n<script>window.CURRENCY = \"{{ S.currency }}\";<\/script>\n{% block scripts %}{% endblock %}\n<\/body>\n<\/html>\n", "cash.html": "{% extends \"base.html\" %}\n{% block title %}دفتر النقدية{% endblock %}\n{% block bodyclass %}pad-b{% endblock %}\n{% block content %}\n<div class=\"h1\">💵 دفتر النقدية<\/div>\n\n{% if cloud_shift_only %}\n<style>\n  #serverShift [hidden] { display:none !important; }\n  #serverShift .rfq-pending button { opacity:.55; pointer-events:none; }\n  #serverShift input { direction:ltr; text-align:right; }\n  #serverShift .rfq-device-id { direction:ltr; unicode-bidi:plaintext; overflow-wrap:anywhere; }\n<\/style>\n<section id=\"serverShift\" class=\"card mt\" data-local-uid=\"{{ u.id }}\" data-local-role=\"{{ u.role }}\">\n  <div class=\"h2\">وردية المتجر المتصلة بالخادم — اختبار<\/div>\n  <p class=\"small muted\">المالك يقرّر فتح وردية العامل من هنا. الأرقام المحلية أسفل الصفحة أرشيف مستقل وليست إذناً بالبيع.<\/p>\n  <div id=\"serverShiftMessage\" class=\"flash error\" role=\"status\" aria-live=\"polite\"><\/div>\n  <div id=\"serverShiftLogin\">\n    <label for=\"serverShiftEmail\">بريد حساب المتجر السحابي على هذا الهاتف<\/label>\n    <input id=\"serverShiftEmail\" type=\"email\" inputmode=\"email\" autocomplete=\"username\" placeholder=\"البريد المسجل في مشروع الاختبار\">\n    <label for=\"serverShiftPassword\">كلمة المرور السحابية<\/label>\n    <input id=\"serverShiftPassword\" type=\"password\" autocomplete=\"current-password\" placeholder=\"لا تُرسلها في المحادثة\">\n    <button id=\"serverShiftSignIn\" type=\"button\" class=\"btn p wide mt\">دخول حساب المتجر<\/button>\n  <\/div>\n  <div id=\"serverShiftSession\" hidden>\n    <p id=\"serverShiftIdentity\" class=\"small\"><\/p>\n    <div class=\"row wrap\">\n      <button id=\"serverShiftRefresh\" type=\"button\" class=\"btn sm\">تحديث حالة الخادم<\/button>\n      <button id=\"serverShiftSignOut\" type=\"button\" class=\"btn sm ghost\">خروج من حساب الخادم<\/button>\n    <\/div>\n    <div id=\"serverShiftBody\" class=\"mt\"><\/div>\n  <\/div>\n<\/section>\n\n<section id=\"cloudCashLedger\" class=\"card mt\" data-local-uid=\"{{ u.id }}\" data-local-role=\"{{ u.role }}\">\n  <div class=\"h2\">صندوق المتجر الخادمي — لا يشمل أرشيف هذا الهاتف<\/div>\n  <div id=\"cloudLedgerMessage\" class=\"flash error\" role=\"status\" aria-live=\"polite\">سجّل دخول المتجر من الأعلى، ثم حدّث حالة الوردية.<\/div>\n  <div id=\"cloudOwnerNotification\" class=\"card tight mt\" hidden>\n    <button id=\"cloudOwnerSound\" type=\"button\" class=\"btn sm ghost\">تفعيل نغمة المالك أثناء فتح التطبيق فقط<\/button>\n    <p id=\"cloudOwnerEventNotice\" class=\"small\" role=\"status\" hidden><\/p>\n    <p class=\"small muted\">تحديث دوري عند ظهور الصندوق؛ ليس إشعار Push إذا أغلق الهاتف أو خرجت من التطبيق.<\/p>\n  <\/div>\n  <p class=\"small muted\">الصندوق يحتسب العهدة المعتمدة ومبيعات النقد والتحصيل والسلف والمصروفات من الخادم. لا تخلط العهدة المحلية أدناه.<\/p>\n  <label for=\"cloudCashShift\">وردية الصندوق المراد عرضها<\/label>\n  <select id=\"cloudCashShift\"><option value=\"\">— لا وردية خادمية مفتوحة —<\/option><\/select>\n  <div id=\"cloudCashSummary\" class=\"sum1 mt\">المدرج في الدرج الآن: —<\/div>\n  <div id=\"cloudCashEntries\" class=\"ledger mt\"><\/div>\n  <form id=\"cloudCashAdjustForm\" class=\"card tight mt\" hidden>\n    <div class=\"h2\">حركة صندوق للمالك فقط<\/div>\n    <p class=\"small muted\">السلفة النقدية للزبون تُصرف من شاشة الزبائن، وليست «مصروفاً» عاماً.<\/p>\n    <label for=\"cloudCashKind\">نوع الحركة<\/label>\n    <select id=\"cloudCashKind\"><option value=\"income\">دخل يدوي<\/option><option value=\"expense\">مصروف<\/option><option value=\"withdraw\">سحب مالك<\/option><\/select>\n    <label for=\"cloudCashAmount\">المبلغ بالريال اليمني<\/label><input id=\"cloudCashAmount\" inputmode=\"decimal\" required>\n    <label for=\"cloudCashReason\">سبب موثّق (3 أحرف فأكثر)<\/label><input id=\"cloudCashReason\" maxlength=\"200\" required>\n    <button id=\"cloudCashAdjustSubmit\" type=\"submit\" class=\"btn amber wide mt\">تأكيد حركة الصندوق الخادمي<\/button>\n  <\/form>\n  <p class=\"small muted\"><a href=\"/pos\">شاشة البيع الجديدة<\/a> • <a href=\"/customers\">دفتر الزبائن والسلف<\/a><\/p>\n<\/section>\n\n<section class=\"card mt\" aria-label=\"أرشيف نقدية هذا الهاتف فقط\">\n  <div class=\"h2\">أرشيف هذا الهاتف — للقراءة فقط<\/div>\n  <p class=\"small muted\">لا يُنقل إلى الخادم أو الهاتف الآخر، ولا يُضاف إلى عهدة الوردية المتصلة. البيع والديون والمصروفات المحلية متوقفة حتى ربط الدفاتر بالخادم.<\/p>\n  {% if shift %}\n    <div class=\"row wrap\"><span>وردية محلية سابقة مفتوحة: {{ shift.opening_cents|money }} {{ S.currency }} عهدة<\/span><\/div>\n    <div class=\"row wrap\"><span>دخل الحركات المحلية المعروضة (حتى 200): {{ totals.in_all|money }} {{ S.currency }} • مصروفها: {{ totals.out_all|money }} {{ S.currency }}<\/span><\/div>\n    <p>الرصيد المتوقع محلياً: <b>{{ expected|money }} {{ S.currency }}<\/b> — ليس رصيد الخادم<\/p>\n  {% else %}<p class=\"muted\">لا توجد وردية محلية مفتوحة على هذا الهاتف.<\/p>{% endif %}\n  {% if last %}<p class=\"small\">آخر وردية محلية أُغلقت: {{ last.opened_at }} ← {{ last.closed_at }} • المتوقع {{ last.expected_cents|money }} {{ S.currency }}<\/p>{% endif %}\n  <div class=\"h2\">حركات هذا الهاتف السابقة<\/div>\n  {% for m in movements %}\n  <div class=\"rowline\"><span class=\"who\"><b>{{ m.reason or m.note or K.get(m.kind, m.kind) }}<\/b>\n    <span class=\"sub\">{{ m.created_at | slice(5, 16) }} • {{ K.get(m.kind, m.kind) }} • {{ m.uname or '—' }}<\/span><\/span>\n    <span class=\"amt\">{{ m.amount_cents|money }}<\/span><\/div>\n  {% endfor %}\n  {% if not movements %}<p class=\"small muted\">لا حركات محلية ظاهرة.<\/p>{% endif %}\n<\/section>\n{% else %}\n{% if shift %}\n  <!-- رقمَا كناش: الدخل / المصروف + الرصيد في الدرج -->\n  <div class=\"sum2 mt\">\n    <div class=\"cell\"><div class=\"lbl\">الدخل (هذه الوردية)<\/div><div class=\"val g\">{{ totals.in_all|money }}<\/div><\/div>\n    <div class=\"cell\"><div class=\"lbl\">المصروف (هذه الوردية)<\/div><div class=\"val r\">{{ totals.out_all|money }}<\/div><\/div>\n  <\/div>\n  <div class=\"sum1 mt\">\n    <span class=\"lbl\">المفروض في الدرج الآن (رصيد النقدية):<\/span>\n    <b class=\"h2\"> {{ expected|money }} {{ S.currency }}<\/b>\n  <\/div>\n\n  <div class=\"card tight mt\">\n    <div class=\"row wrap\">\n      <span class=\"pill g\">وردية مفتوحة<\/span>\n      <span class=\"small muted\">منذ {{ shift.opened_at | slice(11, 16) }} • افتتاحي {{ shift.opening_cents|money }}<\/span>\n      <div class=\"grow\"><\/div>\n      <button class=\"btn sm amber\" onclick=\"openModal('closeModal1')\">🔒 جرد وإغلاق<\/button>\n    <\/div>\n    <div class=\"row wrap mt\" style=\"gap:6px\">\n      <span class=\"chipb g\">بيع نقدي {{ totals.sale|money }}<\/span>\n      <span class=\"chipb g\">تحصيل ديون {{ totals.collection|money }}<\/span>\n      <span class=\"chipb g\">دخل يدوي {{ totals.income|money }}<\/span>\n      <span class=\"chipb r\">مصروف {{ totals.expense|abs|money }}<\/span>\n      <span class=\"chipb r\">سحب {{ totals.withdraw|abs|money }}<\/span>\n      <span class=\"chipb\">حوالات {{ totals.m_transfer|money }}<\/span>\n      <span class=\"chipb\">محافظ {{ totals.m_wallet|money }}<\/span>\n      <span class=\"chipb\">إيداع {{ totals.m_deposit|money }}<\/span>\n      <span class=\"chipb amber\">دين على الزبائن {{ totals.m_debt|money }}<\/span>\n    <\/div>\n  <\/div>\n{% else %}\n  <div class=\"flash error mt\">لا توجد وردية مفتوحة — افتح وردية حتى يبدأ تسجيل المبيعات في الصندوق.<\/div>\n  <div class=\"card mt\">\n    <div class=\"h2\">فتح وردية جديدة<\/div>\n    <form method=\"POST\" action=\"{{ url_for('cash_open') }}\">\n      <label>النقد الموجود في الدرج الآن (بداية الوردية)<\/label>\n      <input name=\"amount\" class=\"big\" inputmode=\"decimal\" placeholder=\"0\" required>\n      <button class=\"btn p lg wide mt\">🔓 فتح الوردية<\/button>\n    <\/form>\n  <\/div>\n{% endif %}\n\n{% if last %}\n<div class=\"card\">\n  <div class=\"h2\">آخر وردية أُغلقت<\/div>\n  <div class=\"row wrap small\">\n    <span class=\"pill gray\">{{ last.opened_at }} ← {{ last.closed_at }}<\/span>\n    <span>المتوقع: <b>{{ last.expected_cents|money }}<\/b><\/span>\n    <span>الفعلي: <b>{{ last.counted_cents|money }}<\/b><\/span>\n    <span class=\"pill {{ 'g' if last.difference_cents==0 else 'r' }}\">\n      {{ 'مطابق ✔' if last.difference_cents==0 else ('زيادة ' if last.difference_cents>0 else 'عجز ') + (last.difference_cents|abs|money) }}<\/span>\n    <span class=\"muted\">أغلقه: {{ last.cname }}<\/span>\n  <\/div>\n  {% if last.difference_cents != 0 and last.difference_reason %}\n    <div class=\"small mt\" style=\"color:var(--amber)\">سبب الفارق: <b>{{ last.difference_reason }}<\/b><\/div>\n  {% endif %}\n<\/div>\n{% endif %}\n\n<!-- حركات النقدية بالأسلوب الكناشي -->\n<div class=\"row mt\"><div class=\"h2 grow\">المعاملات {% if movements %}<span class=\"chipb\">{{ movements|length }}<\/span>{% endif %}<\/div><\/div>\n<div class=\"ledger\">\n  {% for m in movements %}\n    <div class=\"rowline\">\n      <span class=\"circ {{ 'dn' if m.amount_cents>=0 else 'up' }}\">{{ '+' if m.amount_cents>=0 else '−' }}<\/span>\n      <span class=\"who\">\n        <span class=\"nm\">{{ m.reason or m.note or K.get(m.kind, m.kind) }}<\/span>\n        <span class=\"sub\">{{ m.created_at | slice(5, 16) }} • {{ K.get(m.kind, m.kind) }}\n          {% if m.note and m.reason %} • {{ m.note }}{% endif %}\n          • {{ m.uname or '—' }}<\/span>\n      <\/span>\n      <span class=\"amt\">\n        <div class=\"a {{ 'g' if m.amount_cents>=0 else 'r' }}\">{{ m.amount_cents|money }}<\/div>\n        <div class=\"t\">{{ 'دخل' if m.amount_cents>=0 else 'مصروف' }}<\/div>\n      <\/span>\n    <\/div>\n  {% endfor %}\n  {% if not movements %}<div class=\"center muted\" style=\"padding:22px\">لا حركات بعد<\/div>{% endif %}\n<\/div>\n\n<!-- شريط كناش السفلي -->\n<div class=\"bottombar no-print\">\n  <div class=\"in\">\n    <button class=\"bbtn take\" onclick=\"{% if shift %}openModal('inModal'){% else %}toast('افتح الوردية أولاً','err'){% endif %}\">＋ دخل<\/button>\n    <button class=\"bbtn give\" onclick=\"{% if shift %}openModal('expModal'){% else %}toast('افتح الوردية أولاً','err'){% endif %}\">− مصروف<\/button>\n  <\/div>\n<\/div>\n\n<!-- نافذة دخل يدوي -->\n<div class=\"modal\" id=\"inModal\"><div class=\"sheet\">\n  <div class=\"h2\">＋ دخل يدوي إلى الدرج<\/div>\n  <div class=\"muted small\">إيداع المالك، دخل متنوع… (بلا فاتورة).<\/div>\n  <form method=\"POST\" action=\"{{ url_for('cash_income') }}\">\n    <label>المبلغ<\/label><input name=\"amount\" class=\"big center\" inputmode=\"decimal\" required placeholder=\"0\">\n    <label>السبب <span class=\"req\">إلزامي<\/span><\/label>\n    <select name=\"reason\" required>\n      <option value=\"\">— اختر السبب —<\/option>\n      {% for r in REASON_IN %}<option value=\"{{ r }}\">{{ r }}<\/option>{% endfor %}\n    <\/select>\n    <label>ملاحظة (اختياري)<\/label><input name=\"note\" placeholder=\"تفصيل إن أردت\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p lg\" style=\"grid-column:span 2\">تسجيل الدخل<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('inModal')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n\n<!-- نافذة مصروف -->\n<div class=\"modal\" id=\"expModal\"><div class=\"sheet\">\n  <div class=\"h2\">− مصروف من الدرج<\/div>\n  <form method=\"POST\" action=\"{{ url_for('cash_expense') }}\">\n    <label>المبلغ<\/label><input name=\"amount\" class=\"big center\" inputmode=\"decimal\" required>\n    <label>السبب <span class=\"req\">إلزامي<\/span><\/label>\n    <select name=\"reason\" required>\n      <option value=\"\">— اختر السبب —<\/option>\n      {% for r in REASON_OUT %}<option value=\"{{ r }}\">{{ r }}<\/option>{% endfor %}\n    <\/select>\n    <label>ملاحظة (اختياري)<\/label><input name=\"note\" placeholder=\"كهرباء، نقل بضاعة، صيانة…\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p lg\" style=\"grid-column:span 2\">حفظ<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('expModal')\">إلغاء<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n\n<!-- سحب المالك -->\n{% if u.role=='owner' and shift %}\n<div class=\"card\">\n  <div class=\"h2\">🏦 سحب نقدية للمالك<\/div>\n  <form method=\"POST\" action=\"{{ url_for('cash_withdraw') }}\" class=\"mt\">\n    <div class=\"row\" style=\"align-items:flex-end\">\n      <div class=\"grow\"><label>المبلغ<\/label><input name=\"amount\" class=\"big\" inputmode=\"decimal\" required><\/div>\n      <div class=\"grow\"><label>السبب <span class=\"req\">إلزامي<\/span><\/label>\n        <select name=\"reason\" required>\n          <option value=\"\">— اختر السبب —<\/option>\n          {% for r in REASON_OUT %}<option value=\"{{ r }}\">{{ r }}<\/option>{% endfor %}\n        <\/select><\/div>\n    <\/div>\n    <label>ملاحظة (اختياري)<\/label><input name=\"note\" placeholder=\"سحب شخصي\">\n    <button class=\"btn amber wide mt\">سحب من الدرج<\/button>\n  <\/form>\n<\/div>\n{% endif %}\n\n<!-- إغلاق الوردية: ورقة عدّ بالفئات -->\n{% if shift %}\n<div class=\"modal\" id=\"closeModal1\"><div class=\"sheet\">\n  <div class=\"h2\">🔒 جرد وإغلاق الوردية<\/div>\n  <div class=\"card tight\">\n    <div class=\"row\"><span class=\"grow muted\">المفروض في الدرج (حسب النظام)<\/span>\n      <b id=\"expView\" data-cents=\"{{ expected }}\">{{ expected|money }} {{ S.currency }}<\/b><\/div>\n  <\/div>\n\n  <form method=\"POST\" action=\"{{ url_for('cash_close') }}\" id=\"closeForm\">\n    <div class=\"h2 mt\">عدّ النقود بالفئات<\/div>\n    <div class=\"hint\">اكتب عدد كل فئة — يجمعها النظام لك تلقائياً.<\/div>\n    <table class=\"count\">\n      {% for d in DENOM %}\n      <tr>\n        <td class=\"f\">{{ d }} {{ S.currency }}<\/td>\n        <td class=\"x\">×<\/td>\n        <td><input class=\"cnt\" type=\"number\" inputmode=\"numeric\" min=\"0\" step=\"1\" value=\"\"\n                   data-val=\"{{ d }}\" placeholder=\"0\"><\/td>\n        <td class=\"ttl\" data-sub=\"{{ d }}\">0<\/td>\n      <\/tr>\n      {% endfor %}\n      <tr class=\"sumrow\">\n        <td colspan=\"3\">المجموع المعدود<\/td>\n        <td class=\"ttl\"><b id=\"countTotal\">0<\/b><\/td>\n      <\/tr>\n    <\/table>\n\n    <label>أو اكتب المبلغ المعدود مباشرةً<\/label>\n    <input name=\"counted\" id=\"countedInput\" class=\"big center\" inputmode=\"decimal\" required placeholder=\"0\">\n\n    <div class=\"card tight mt\" id=\"diffBox\">\n      <div class=\"row\"><span class=\"grow muted\">المفروض<\/span><b id=\"dExp\">0<\/b><\/div>\n      <div class=\"row\"><span class=\"grow muted\">المعدود<\/span><b id=\"dCnt\">0<\/b><\/div>\n      <div class=\"row\"><span class=\"grow\"><b>الفارق<\/b><\/span>\n        <b id=\"dDiff\" class=\"pill gray\">0<\/b><\/div>\n    <\/div>\n\n    <div id=\"reasonBox\" class=\"hide\">\n      <label>سبب الفارق <span class=\"req\">إلزامي<\/span><\/label>\n      <select name=\"difference_reason\" id=\"diffReason\">\n        <option value=\"\">— اختر سبب الفارق —<\/option>\n        {% for r in REASON_DIFF %}<option value=\"{{ r }}\">{{ r }}<\/option>{% endfor %}\n      <\/select>\n      <div class=\"hint\">لا يُغلق الدرج بفارق بلا سبب.<\/div>\n    <\/div>\n\n    <div class=\"btn-grid mt\">\n      <button class=\"btn amber lg\" style=\"grid-column:span 2\">إغلاق ومطابقة<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('closeModal1')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n{% endif %}\n{% endif %}\n{% endblock %}\n{% block scripts %}\n{% if cloud_shift_only %}\n<script src=\"cloud-shift.js\"><\/script>\n<script src=\"cloud-ledger.js\"><\/script>\n<script>window.RafiqCloudShift.mount();window.RafiqCloudLedger.mount('cash');<\/script>\n{% else %}\n<script>\n(function(){\n  var expEl = document.getElementById('expView');\n  var EXP = parseInt(expEl ? (expEl.dataset.cents || '0') : '0', 10);\n  var inputs = Array.prototype.slice.call(document.querySelectorAll('.cnt'));\n  var counted = document.getElementById('countedInput');\n  var totalEl = document.getElementById('countTotal');\n  var dCnt = document.getElementById('dCnt');\n  var reasonBox = document.getElementById('reasonBox');\n  var reasonSel = document.getElementById('diffReason');\n  if(!counted) return;\n\n  function fmt(cents){\n    return (cents/100).toLocaleString('en-US', {minimumFractionDigits:0, maximumFractionDigits:0});\n  }\n  function updateDiff(){\n    var _raw = Math.round(parseFloat(String(counted.value || '0').replace(/,/g, '')) * 100) || 0;\n    var c = Math.round(_raw/100)*100;   // تقريب إلى ريال كامل\n    var diff = c - EXP;\n    if(dCnt) dCnt.textContent = fmt(c);\n    var el = document.getElementById('dDiff');\n    if(el){\n      el.textContent = (diff === 0 ? 'مطابق ✔'\n                        : (diff > 0 ? 'زيادة ' : 'عجز ') + fmt(Math.abs(diff)));\n      el.className = 'pill ' + (diff === 0 ? 'g' : 'r');\n    }\n    // سبب الفارق: يظهر فقط عند وجود فارق\n    if(reasonBox){\n      if(diff !== 0){\n        reasonBox.classList.remove('hide');\n        if(reasonSel) reasonSel.required = true;\n      } else {\n        reasonBox.classList.add('hide');\n        if(reasonSel){ reasonSel.required = false; reasonSel.value = ''; }\n      }\n    }\n  }\n  function refreshFromDenoms(){\n    var sum = 0;\n    inputs.forEach(function(inp){\n      var val = parseInt(inp.dataset.val, 10) * 100;\n      var n = parseInt(inp.value || '0', 10) || 0;\n      var sub = val * n;\n      sum += sub;\n      var cell = document.querySelector('.ttl[data-sub=\"' + inp.dataset.val + '\"]');\n      if(cell) cell.textContent = n ? fmt(sub) : '0';\n    });\n    if(totalEl) totalEl.textContent = fmt(sum);\n    counted.value = fmt(sum);\n    updateDiff();\n  }\n\n  inputs.forEach(function(i){ i.addEventListener('input', refreshFromDenoms); });\n  counted.addEventListener('input', updateDiff);   // الكتابة المباشرة لا تُستبدل\n  updateDiff();\n})();\n<\/script>\n{% endif %}\n{% endblock %}", "cash_report.html": "{% extends \"base.html\" %}\n{% block title %}تقرير درج النقود{% endblock %}\n{% block content %}\n\n<!-- ترويسة ورقية: تظهر عند الطباعة فقط -->\n<div class=\"print-head\">\n  {% if S.store_logo %}<img src=\"{{ S.store_logo }}\" alt=\"\">{% endif %}\n  <div><div class=\"t\">{{ S.store_name or \"المتجر\" }}<\/div>\n       <div class=\"s\">{{ S.store_name }} • تقرير درج النقود • {{ d }}<\/div><\/div>\n<\/div>\n\n<div class=\"row no-print\">\n  <div class=\"h1 grow\">💵 تقرير درج النقود<\/div>\n  <button class=\"btn sm p\" onclick=\"window.print()\">🖨 طباعة<\/button>\n<\/div>\n\n<div class=\"card mt no-print\">\n  <form method=\"get\" class=\"row wrap\">\n    <input type=\"date\" name=\"date\" value=\"{{ d }}\" class=\"grow\" style=\"min-width:150px\">\n    <button class=\"btn p\">عرض<\/button>\n    <a class=\"btn ghost\" href=\"{{ url_for('cash_report') }}\">اليوم<\/a>\n    <a class=\"btn ghost\" href=\"{{ url_for('cash') }}\">الصندوق<\/a>\n  <\/form>\n<\/div>\n\n{% if not blocks %}\n  <div class=\"flash error mt\">لا توجد وردية مسجّلة في هذا اليوم.<\/div>\n{% endif %}\n\n{% for b in blocks %}\n{% set sh = b.shift %}\n<div class=\"card mt\">\n  <div class=\"row wrap\">\n    <div class=\"h2 grow\">الوردية رقم {{ sh.id }}<\/div>\n    {% if sh.status == 'closed' %}\n      <span class=\"pill gray\">مغلقة<\/span>\n    {% else %}\n      <span class=\"pill g\">مفتوحة الآن<\/span>\n    {% endif %}\n  <\/div>\n  <div class=\"small muted\">\n    فتح: {{ sh.opened_at }} • {{ sh.opener or '—' }}\n    {% if sh.status == 'closed' %} • أغلق: {{ sh.closed_at }} • {{ sh.closer or '—' }}{% endif %}\n  <\/div>\n\n  <!-- خلاصة الحساب -->\n  <table class=\"kashf mt\">\n    <tr><td>العهدة (بداية الوردية)<\/td><td class=\"n\">{{ b.tot.open|money }}<\/td><\/tr>\n    <tr><td>+ مبيعات نقدية<\/td><td class=\"n g\">{{ b.tot.sale|money }}<\/td><\/tr>\n    <tr><td>+ تحصيل ديون<\/td><td class=\"n g\">{{ b.tot.collection|money }}<\/td><\/tr>\n    <tr><td>+ إيداعات يدوية<\/td><td class=\"n g\">{{ b.tot.income|money }}<\/td><\/tr>\n    <tr><td>− مصروفات<\/td><td class=\"n r\">{{ b.tot.expense|abs|money }}<\/td><\/tr>\n    <tr><td>− سحب المالك<\/td><td class=\"n r\">{{ b.tot.withdraw|abs|money }}<\/td><\/tr>\n    <tr><td>− سداد موردين<\/td><td class=\"n r\">{{ b.tot.supplier_pay|abs|money }}<\/td><\/tr>\n    <tr><td>− إلغاء فواتير<\/td><td class=\"n r\">{{ b.tot.cancel|abs|money }}<\/td><\/tr>\n    <tr class=\"total\"><td>المفروض في الدرج<\/td><td class=\"n\">{{ b.expected|money }} {{ S.currency }}<\/td><\/tr>\n    {% if sh.status == 'closed' %}\n      <tr><td>المعدود فعلياً<\/td><td class=\"n\">{{ b.counted|money }}<\/td><\/tr>\n      <tr class=\"total {{ 'g' if b.diff == 0 else 'r' }}\">\n        <td>{{ 'مطابق ✔' if b.diff == 0 else ('زيادة' if b.diff > 0 else 'عجز') }}<\/td>\n        <td class=\"n\">{{ b.diff|money }}<\/td><\/tr>\n      {% if b.diff != 0 %}\n        <tr><td>سبب الفارق<\/td><td class=\"n\">{{ b.diff_reason }}<\/td><\/tr>\n      {% endif %}\n    {% else %}\n      <tr><td>المعدود فعلياً<\/td><td class=\"n muted\">لم تُجرد بعد<\/td><\/tr>\n    {% endif %}\n  <\/table>\n\n  <!-- سجل الحركات -->\n  <div class=\"h2 mt2\">سجل الحركات <span class=\"chipb\">{{ b.movs|length }}<\/span><\/div>\n  <div class=\"ledger\">\n    {% for m in b.movs %}\n      <div class=\"rowline\">\n        <span class=\"circ {{ 'dn' if m.amount_cents>=0 else 'up' }}\">{{ '+' if m.amount_cents>=0 else '−' }}<\/span>\n        <span class=\"who\">\n          <span class=\"nm\">{{ m.reason or m.note or K.get(m.kind, m.kind) }}<\/span>\n          <span class=\"sub\">{{ m.created_at | slice(5, 16) }} • {{ K.get(m.kind, m.kind) }}\n            {% if m.note and m.reason %} • {{ m.note }}{% endif %}\n            • {{ m.uname or '—' }}<\/span>\n        <\/span>\n        <span class=\"amt\">\n          <div class=\"a {{ 'g' if m.amount_cents>=0 else 'r' }}\">{{ m.amount_cents|money }}<\/div>\n        <\/span>\n      <\/div>\n    {% endfor %}\n    {% if not b.movs %}<div class=\"center muted\" style=\"padding:18px\">لا حركات<\/div>{% endif %}\n  <\/div>\n<\/div>\n{% endfor %}\n\n{% if blocks|length > 1 %}\n<div class=\"card mt\">\n  <div class=\"h2\">حصيلة اليوم كاملاً<\/div>\n  <table class=\"kashf\">\n    <tr><td>إجمالي الدخل (بلا العهدة)<\/td><td class=\"n g\">{{ day_in|money }}<\/td><\/tr>\n    <tr><td>إجمالي الخروج<\/td><td class=\"n r\">{{ day_out|money }}<\/td><\/tr>\n    <tr class=\"total\"><td>الصافي<\/td><td class=\"n\">{{ (day_in - day_out)|money }} {{ S.currency }}<\/td><\/tr>\n  <\/table>\n<\/div>\n{% endif %}\n\n<div class=\"card mt no-print\">\n  <a class=\"btn ghost wide\" href=\"{{ url_for('reports') }}\">← الرجوع للتقارير<\/a>\n<\/div>\n{% endblock %}\n", "customer_detail.html": "{% extends \"base.html\" %}\n{% block title %}كشف حساب {{ c.name }}{% endblock %}\n{% block bodyclass %}pad-b{% endblock %}\n{% block content %}\n\n<!-- ترويسة كناشية: رجوع › الاسم › واتساب -->\n<div class=\"row mt\">\n  <a class=\"btn sm ghost\" href=\"{% if cloud_shift_only %}/archive/customers{% else %}{{ url_for('customers') }}{% endif %}\">‹ رجوع<\/a>\n  <div class=\"grow center\">\n    <div class=\"h2\" style=\"margin:0\">{{ c.name }}<\/div>\n    <div class=\"muted small\">رمز الآجل <b dir=\"ltr\">{{ c.code }}<\/b><\/div>\n    {% if c.phone %}<div class=\"muted small\" style=\"direction:ltr\">{{ c.phone }}<\/div>{% endif %}\n  <\/div>\n  {% if c.phone %}<a class=\"btn sm\" style=\"background:#d9f2e4;color:#0f5c46\" href=\"#waBox\">💬<\/a>\n  {% else %}<span style=\"width:44px\"><\/span>{% endif %}\n<\/div>\n\n{% if not audit_ok %}<div class=\"hint mt\" style=\"color:#b91c1c;font-weight:800\">⚠ اختلاف بين مجموع الحركات والرصيد. لا تعتمد الكشف حتى تُراجع البيانات؛ لم نغيّر أي رصيد تلقائياً.<\/div>{% endif %}\n<!-- الرصيد الكبير -->\n<div class=\"card center mt\" style=\"padding:16px\">\n  <div class=\"muted small\">الرصيد الحالي<\/div>\n  <div style=\"font-size:2.1rem; font-weight:800; color:{{ '#b91c1c' if c.balance_cents>0 else '#17795e' }}\">\n    {{ c.balance_cents|money }} {{ S.currency }}\n  <\/div>\n  <div class=\"small\">\n    {% if c.balance_cents > 0 %}<span class=\"chipb r\">أعطيت — عليه دين<\/span>\n    {% elif c.balance_cents < 0 %}<span class=\"chipb g\">رصيد لصالح الزبون (قد يكون افتتاحياً)<\/span>\n    {% else %}<span class=\"chipb g\">مسدَّد بالكامل ✔<\/span>{% endif %}\n  <\/div>\n<\/div>\n\n<div class=\"opts mt\">\n  <a class=\"btn ghost\" href=\"#waBox\">📲 إرسال تذكير واتساب<\/a>\n  <a class=\"btn ghost\" href=\"#history\">📄 كشف المعاملات<\/a>\n    <a class=\"btn ghost\" href=\"{% if cloud_shift_only %}/archive/customers/{{ c.id }}/print{% else %}/customers/{{ c.id }}/print{% endif %}\">🖨 طباعة كشف الحساب<\/a>\n<\/div>\n\n<!-- سجل المعاملات بالأسلوب الكناشي -->\n<div class=\"row mt\" id=\"history\" style=\"margin-top:16px\">\n  <div class=\"h2 grow\">المعاملات <span class=\"chipb\">{{ ev|length }}<\/span><\/div>\n<\/div>\n<div class=\"ledger mt\">\n  {% for e in ev %}\n    <div class=\"rowline\">\n      <span class=\"circ {{ 'dn' if e.kind=='taken' or e.kind=='credit_opening' else 'up' }}\">{{ '↓' if e.kind=='taken' or e.kind=='credit_opening' else '↑' }}<\/span>\n      <span class=\"who\">\n        <span class=\"nm\">\n          {% if e.invoice_id %}<a href=\"{{ url_for('invoice', iid=e.invoice_id) }}\">{{ e.note }}<\/a>\n          {% else %}{{ e.note }}{% endif %}\n        <\/span>\n        <span class=\"sub\">{% set stampStart = e.ts | slice(0, 4) %}{% if stampStart == '0001' %}قبل بدء النظام{% else %}{{ e.ts | slice(0, 16) }}{% endif %}\n          {% if e.user %} • {{ e.user }}{% endif %}\n          • <span class=\"chipb {{ 'g' if e.balance_after<=0 else 'r' }}\">الرصيد {{ e.balance_after|money }}<\/span>\n        <\/span>\n      <\/span>\n      <span class=\"amt\">\n        <div class=\"a {{ 'g' if e.kind=='taken' or e.kind=='credit_opening' else 'r' }}\">{{ e.amount|money }}<\/div>\n        <div class=\"t\">{{ 'افتتاحي لصالحه' if e.kind=='credit_opening' else ('أخذت' if e.kind=='taken' else 'أعطيت') }}<\/div>\n      <\/span>\n    <\/div>\n  {% endfor %}\n  {% if not ev %}<div class=\"center muted\" style=\"padding:22px\">لا معاملات بعد<\/div>{% endif %}\n<\/div>\n\n<!-- فواتيره التفصيلية -->\n{% if invoices %}\n<div class=\"card mt\">\n  <div class=\"h2\">آخر 200 فاتورة (الكشف أعلاه يشمل الحركات كلها)<\/div>\n  <div class=\"scroll-x\">\n  <table class=\"tbl\">\n    <tr><th>رقم<\/th><th>التاريخ<\/th><th>الإجمالي<\/th><th>دُفع<\/th><th>متبقٍ<\/th><th>الحالة<\/th><\/tr>\n    {% for i in invoices %}\n      <tr>\n        <td><a href=\"{{ url_for('invoice', iid=i.id) }}\">{{ i.number }}<\/a><\/td>\n        <td class=\"small\">{{ i.created_at | slice(0, 16) }}<\/td>\n        <td>{{ i.total_cents|money }}<\/td>\n        <td>{{ i.paid_cents|money }}<\/td>\n        <td><b style=\"color:{{ '#b91c1c' if i.due_cents>0 else '#17795e' }}\">{{ i.due_cents|money }}<\/b><\/td>\n        <td>{% if i.status=='cancelled' %}<span class=\"pill r\">ملغاة<\/span>\n            {% else %}<span class=\"pill g\">سارية<\/span>{% endif %}<\/td>\n      <\/tr>\n    {% endfor %}\n  <\/table>\n  <\/div>\n<\/div>\n{% endif %}\n\n{% if not cloud_shift_only %}\n<!-- واتساب لبيانات الدفتر المحلي فقط؛ لا يُرسل كشفاً قديماً على أنه خادمي. -->\n<div class=\"card\" id=\"waBox\">\n  <div class=\"h2\">📲 تذكير واتساب<\/div>\n  <div class=\"muted small\">راجع الرقم والرسالة ثم اضغط الإرسال — الإرسال يبقى بيدك دائماً.<\/div>\n  <label>رقم الواتساب<\/label>\n  <input id=\"waPhone\" value=\"{{ c.phone }}\" inputmode=\"tel\">\n  <label>نص الرسالة<\/label>\n  <textarea id=\"waText\" rows=\"4\">تذكير من {{ S.store_name }}\n{% if c.balance_cents>0 %}الرصيد المتبقي عليكم: {{ c.balance_cents|money }} {{ S.currency }}\nنرجو التكرم بالسداد عند الإمكان، شكراً لكم 🌹{% else %}لا يوجد رصيد مستحق — شكراً لتعاملكم معنا 🌹{% endif %}<\/textarea>\n  <button class=\"btn wa-btn wide mt\" id=\"waSend\">فتح واتساب بالرسالة<\/button>\n<\/div>\n{% endif %}\n\n{% if cloud_shift_only %}\n<div class=\"flash error mt\">كشف هذا الزبون محلي على هذا الهاتف فقط. «أعطيت» القديم لا يخصم سلفة نقدية من الصندوق؛ لا تصرف سلفة ولا تقبض دفعة اعتماداً عليه.<\/div>\n{% else %}\n<!-- شريط كناش السفلي: أخذت / أعطيت -->\n<div class=\"bottombar no-print\">\n  <div class=\"in\">\n    <button class=\"bbtn take\" onclick=\"openModal('takeModal')\">✔ أخذت<\/button>\n    <button class=\"bbtn give\" onclick=\"openModal('giveModal')\">✔ أعطيت<\/button>\n  <\/div>\n<\/div>\n\n<!-- نافذة أخذت (قبض دفعة) -->\n<div class=\"modal\" id=\"takeModal\"><div class=\"sheet\">\n  <div class=\"h2\">✔ أخذت من {{ c.name }}<\/div>\n  <div class=\"muted small\">قبض نقدي يُسجَّل في الصندوق المفتوح تلقائياً.<\/div>\n  <form method=\"POST\" action=\"{{ url_for('customer_pay', cid=c.id) }}\">\n    <label>المبلغ المقبوض<\/label>\n    <input name=\"amount\" class=\"big center\" inputmode=\"decimal\" required autofocus placeholder=\"0\">\n    <div class=\"quick-amts mt\" id=\"q1\">\n      {% if c.balance_cents>0 %}<button type=\"button\" class=\"btn\" data-v=\"{{ (c.balance_cents/100) }}\">كامل الدين {{ c.balance_cents|money }}<\/button>{% endif %}\n    <\/div>\n    <label>ملاحظة (اختياري)<\/label><input name=\"note\" placeholder=\"دفعة نقدية\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p lg\" style=\"grid-column:span 2\">تسجيل القبض<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('takeModal')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n\n<!-- نافذة أعطيت (دين يدوي) -->\n<div class=\"modal\" id=\"giveModal\"><div class=\"sheet\">\n  <div class=\"h2\">✔ أعطيت {{ c.name }}<\/div>\n  <div class=\"muted small\">تسجيل دين جديد بلا فاتورة (بضاعة على الحساب، سلفة…). لا يمسّ الصندوق.<\/div>\n  <form method=\"POST\" action=\"{{ url_for('customer_debit', cid=c.id) }}\">\n    <label>المبلغ<\/label>\n    <input name=\"amount\" class=\"big center\" inputmode=\"decimal\" required placeholder=\"0\">\n    <label>البيان<\/label><input name=\"note\" placeholder=\"مثال: بضاعة على الحساب\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn amber lg\" style=\"grid-column:span 2\">تسجيل الدين<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('giveModal')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n{% endif %}\n{% endblock %}\n\n{% block scripts %}\n<script>\ndocument.querySelectorAll('#q1 .btn').forEach(b=>{\n  b.onclick = ()=>{ document.querySelector('#takeModal input[name=amount]').value = b.dataset.v; };\n});\nvar localWaButton = document.getElementById('waSend');\nif (localWaButton) localWaButton.onclick = ()=>{\n  waOpen(document.getElementById('waPhone').value, document.getElementById('waText').value);\n};\n<\/script>\n{% endblock %}\n", "customers.html": "{% extends \"base.html\" %}\n{% block title %}دفتر الديون{% endblock %}\n{% block content %}\n<div class=\"row\">\n  <div class=\"h1 grow\">📒 {{ 'أرشيف ديون هذا الهاتف فقط' if cloud_shift_only else 'دفتر الديون' }}<\/div>\n<\/div>\n{% if cloud_shift_only %}<p class=\"flash error\">الأرصدة التالية محفوظة على هذا الهاتف للقراءة فقط؛ لا تُضاف إلى المتجر الخادمي أو هاتف آخر. <a href=\"/customers\">اذهب إلى زبائن المتجر المتصل<\/a>.<\/p>{% endif %}\n\n<!-- تبويبا العملاء/الموردين كما في كناش -->\n<div class=\"tabs2 mt\">\n  <a href=\"{{ url_for('customers') }}\" class=\"on\">العملاء<\/a>\n  <a href=\"{{ url_for('suppliers') }}\">الموردون<\/a>\n<\/div>\n\n<!-- رقمَا كناش: أخذت / أعطيت -->\n<div class=\"sum2\">\n  <div class=\"cell\">\n    <div class=\"lbl\">أخذت (قبضنا منهم)<\/div>\n    <div class=\"val g\">{{ taken|money }}<\/div>\n  <\/div>\n  <div class=\"cell\">\n    <div class=\"lbl\">أعطيت (ديناً)<\/div>\n    <div class=\"val r\">{{ given|money }}<\/div>\n  <\/div>\n<\/div>\n<div class=\"sum1 mt\">\n  <span class=\"lbl\">المتبقي على العملاء جميعاً:<\/span>\n  <b class=\"h2\" style=\"color:{{ '#b91c1c' if remaining>0 else '#17795e' }}\"> {{ remaining|money }} {{ S.currency }}<\/b>\n<\/div>\n\n<div class=\"row wrap mt\" style=\"gap:8px\">\n  <a class=\"btn sm {{ 'amber' if followup else 'ghost' }}\" href=\"/customers?followup=1\">⏳ ديون تحتاج متابعة ({{ debt_followup_days }} يوماً)<\/a>\n  {% if followup %}<a class=\"btn sm ghost\" href=\"{{ url_for('customers') }}\">جميع العملاء<\/a>{% endif %}\n<\/div>\n{% if followup %}<div class=\"hint mt\">فلتر لآخر دين غير مسددّ بافتراض سداد الأقدم أولاً، وليس حكماً قانونياً أو تاريخ استحقاق تعاقدياً. الأرقام الإجمالية أعلاه لجميع العملاء.<\/div>{% endif %}\n<div class=\"card mt\">\n  <form method=\"get\" {% if cloud_shift_only %}action=\"/archive/customers\"{% endif %} class=\"row\">\n    {% if followup %}<input type=\"hidden\" name=\"followup\" value=\"1\">{% endif %}\n    <input name=\"q\" value=\"{{ q }}\" placeholder=\"🔍 الاسم أو الهاتف أو الرمز #00042\" class=\"grow\">\n    <button class=\"btn p\">بحث<\/button>\n  <\/form>\n<\/div>\n\n{% if not cloud_shift_only %}\n<button class=\"btn blue wide mb\" onclick=\"openModal('addModal')\">➕ إضافة عميل جديد<\/button>\n{% endif %}\n\n<!-- قائمة الزبائن بالأسلوب الكناشي -->\n<div class=\"ledger\">\n  {% for r in rows %}\n    <a href=\"{% if cloud_shift_only %}/archive/customers/{{ r.id }}{% else %}{{ url_for('customer_detail', cid=r.id) }}{% endif %}\" class=\"rowline\" style=\"color:inherit\">\n      <span class=\"avc {{ 'r' if r.balance_cents>0 else ('g' if r.balance_cents<0 else '') }}\">{{ r.name[0] }}<\/span>\n      <span class=\"who\">\n        <span class=\"nm\">{{ r.name }}<\/span>\n        <span class=\"sub\">\n          <span dir=\"ltr\">{{ r.code }}<\/span> •\n          {% if r.last_activity %}{{ r.last_activity | slice(0, 10)|ago }}{% else %}لا حركات بعد{% endif %}\n          {% if r.phone %} • {{ r.phone }}{% endif %}\n        <\/span>\n      <\/span>\n      <span class=\"amt\">\n        {% if r.balance_cents > 0 %}\n          <div class=\"a r\">{{ r.balance_cents|money }}<\/div><div class=\"t\">أعطيت<\/div>\n        {% elif r.balance_cents < 0 %}\n          <div class=\"a g\">{{ (-r.balance_cents)|money }}<\/div><div class=\"t\">أخذت (رصيد زائد)<\/div>\n        {% else %}\n          <div class=\"a\" style=\"color:#94a3b8\">0<\/div><div class=\"t\">مسدَّد ✔<\/div>\n        {% endif %}\n      <\/span>\n    <\/a>\n  {% endfor %}\n  {% if not rows %}<div class=\"center muted\" style=\"padding:22px\">{{ 'لا ديون تستوفي معيار المتابعة' if followup else 'لا عملاء بعد — أضف أول عميل' }}<\/div>{% endif %}\n<\/div>\n{% if rows|length == 300 %}<div class=\"hint\">عُرضت 300 نتيجة — استخدم البحث للتضييق.<\/div>{% endif %}\n\n{% if not cloud_shift_only %}\n<div class=\"modal\" id=\"addModal\"><div class=\"sheet\">\n  <div class=\"h2\">➕ إضافة عميل<\/div>\n  <form method=\"POST\" action=\"{{ url_for('customer_add') }}\">\n    <input type=\"hidden\" name=\"back\" value=\"{{ url_for('customers') }}\">\n    <label>الاسم<\/label><input name=\"name\" required autofocus>\n    <label>الهاتف (اختياري — للواتساب)<\/label><input name=\"phone\" inputmode=\"tel\">\n    <label>دين قديم عليه (اختياري)<\/label><input name=\"opening\" inputmode=\"decimal\" placeholder=\"0\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p\">حفظ<\/button>\n      <button type=\"button\" class=\"btn ghost\" onclick=\"closeModal('addModal')\">إلغاء<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n{% endif %}\n{% endblock %}\n", "dashboard.html": "{% extends \"base.html\" %}\n{% block title %}لوحة المالك{% endblock %}\n\n{% block content %}\n<div class=\"row\">\n  <div class=\"h1 grow\">لوحة صاحب المتجر<\/div>\n  <div class=\"pill b\">{{ today }}<\/div>\n<\/div>\n\n{% if not shift %}\n<div class=\"flash error mt\">الصندوق مغلق — افتح وردية جديدة من صفحة <a href=\"{{ url_for('cash') }}\">الصندوق<\/a> حتى تُسجَّل المبيعات.<\/div>\n{% else %}\n<div class=\"card tight mt row\">\n  <span class=\"pill g\">الوردية مفتوحة<\/span>\n  <span class=\"small muted\">منذ {{ shift.opened_at | slice(11, 16) }}<\/span>\n  <div class=\"grow\"><\/div>\n  <span class=\"small\">صندوق الدرج الآن: <b>{{ expected|money }} {{ S.currency }}<\/b><\/span>\n<\/div>\n{% endif %}\n\n<div class=\"grid g4 mt\">\n  <div class=\"stat green\" data-go=\"/reports\"><div class=\"lbl\">مبيعات اليوم<\/div><div class=\"val\">{{ stats.sales_today.t|money }}<\/div>\n    <div class=\"sub\">{{ stats.sales_today.c }} فاتورة — {{ S.currency }}<\/div><\/div>\n  <div class=\"stat blue\" data-go=\"/cash\"><div class=\"lbl\">نقد البيع والتحصيل والدخل اليوم<\/div>\n    <div class=\"val\">{{ (stats.cash_sales + stats.collections + stats.income_today)|money }}<\/div>\n    <div class=\"sub\">صافي بيع/إلغاء {{ stats.cash_sales|money }} + تحصيل {{ stats.collections|money }} + دخل {{ stats.income_today|money }}<\/div><\/div>\n  <div class=\"stat amber\" data-go=\"/customers\"><div class=\"lbl\">آجل جديد اليوم<\/div><div class=\"val\">{{ stats.new_debt|money }}<\/div>\n    <div class=\"sub\">ديون الزبائن المتبقية كلها: {{ stats.debts_total|money }}<\/div><\/div>\n  <div class=\"stat {{ 'red' if stats.low_stock else '' }}\" data-go=\"/products\"><div class=\"lbl\">أصناف قاربت على النفاد<\/div>\n    <div class=\"val\">{{ stats.low_stock }}<\/div><div class=\"sub\">من أصل {{ stats.products }} صنف<\/div><\/div>\n  <div class=\"stat amber\" data-go=\"/suppliers\"><div class=\"lbl\">علينا للموردين والمناديب<\/div>\n    <div class=\"val\">{{ stats.supplier_debt|money }}<\/div>\n    <div class=\"sub\">متوقعون اليوم: {{ stats.due_delegates }} مندوباً<\/div><\/div>\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"row wrap\" style=\"gap:8px\">\n    <div class=\"h2 grow\">⏳ تنبيه صلاحية الأصناف<\/div>\n    <a class=\"small\" href=\"/products?expiry_alert=1\">عرض القائمة ›<\/a>\n  <\/div>\n  <div class=\"small muted mt\">انتهت صلاحيتها: <b>{{ expiry_expired }}<\/b> • ستنتهي خلال {{ expiry_days }} يوماً (من اليوم): <b>{{ expiry_near }}<\/b>. يُعرض التنبيه عند فتح اللوحة فقط.<\/div>\n  {% if expiry_rows %}\n  <div class=\"ledger mt\">\n    {% for p in expiry_rows %}\n    <div class=\"rowline\">\n      <span class=\"who\"><span class=\"nm\"><a href=\"{{ url_for('product_edit', pid=p.id) }}\">{{ p.name }}<\/a><\/span>\n        <span class=\"sub\">{{ p.expiry }} • رصيد {{ p.stock }}<\/span><\/span>\n      <span class=\"pill {{ 'r' if p.expired else 'a' }}\">{{ 'منتهٍ' if p.expired else 'قريب' }}<\/span>\n    <\/div>\n    {% endfor %}\n  <\/div>\n  {% if expiry_total > (expiry_rows|length) %}<div class=\"muted small mt\">و{{ expiry_total - (expiry_rows|length) }} أصناف أخرى في القائمة.<\/div>{% endif %}\n  {% else %}<div class=\"muted small mt\">لا توجد أصناف منتهية أو قريبة بتاريخ مسجّل ورصيد موجب.<\/div>{% endif %}\n  <div class=\"hint mt\">هذا تنبيه من تاريخ واحد للصنف، وليس تتبّعاً لصلاحية كل دفعة مخزون أو إشعاراً خارج التطبيق.<\/div>\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"row wrap\" style=\"gap:8px\">\n    <div class=\"h2 grow\">📒 ديون تحتاج متابعة: {{ debt_followup_count }}<\/div>\n    <a class=\"small\" href=\"/customers?followup=1\">عرض القائمة ›<\/a>\n  <\/div>\n  <div class=\"muted small mt\">المعيار: مرّ {{ debt_followup_days }} يوماً أو أكثر على أقدم مبلغ لم تُغطِّه الدفعات، مع احتساب السداد للأقدم أولاً.<\/div>\n  {% if debt_followup_rows %}\n  <div class=\"ledger mt\">\n    {% for d in debt_followup_rows %}\n    <div class=\"rowline\">\n      <span class=\"who\"><span class=\"nm\"><a href=\"{{ url_for('customer_detail', cid=d.id) }}\">{{ d.name }}<\/a><\/span>\n        <span class=\"sub\">أقدم مبلغ متبقٍّ: {{ d.oldest }} • منذ {{ d.age_days }} يوماً<\/span><\/span>\n      <span class=\"amt\">{{ d.balance_cents|money }} {{ S.currency }}<\/span>\n    <\/div>\n    {% endfor %}\n  <\/div>\n  {% if debt_followup_count > (debt_followup_rows|length) %}<div class=\"muted small mt\">و{{ debt_followup_count - (debt_followup_rows|length) }} آخرون في القائمة.<\/div>{% endif %}\n  {% else %}<div class=\"muted small mt\">لا ديون تستوفي معيار المتابعة الآن.<\/div>{% endif %}\n  <div class=\"hint mt\">ليس حكماً بالتعثر أو استحقاقاً تعاقدياً: لا يُسجَّل موعد سداد محدد؛ الدين المرحّل يؤرَّخ حالياً بإنشاء حساب الزبون.<\/div>\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"row\">\n    <div class=\"h2 grow\">🚚 الموردون والمناديب اليوم<\/div>\n    <a class=\"small\" href=\"{{ url_for('suppliers') }}\">عرض الكل ›<\/a>\n  <\/div>\n  {% if stats.due_total %}\n  <div class=\"muted small\">متوقع اليوم <b>{{ stats.due_total }}<\/b>{% if stats.late_total %} • منهم متأخر <b style=\"color:#b45309\">{{ stats.late_total }}<\/b>{% endif %} — علّم «مرّ اليوم» عند مجيئهم.<\/div>\n  <div class=\"ledger mt\">\n    {% for s in due_list %}\n    <div class=\"rowline\">\n      <span class=\"avc {{ 'r' if s.overdue else '' }}\">{{ s.name[0] }}<\/span>\n      <span class=\"who\">\n        <span class=\"nm\"><a href=\"{{ url_for('supplier_detail', sid=s.id) }}\" style=\"color:inherit\">{{ s.name }}<\/a><\/span>\n        <span class=\"sub\">{% if s.overdue %}<span class=\"chipb r\">متأخر<\/span> • {% endif %}<span class=\"chipb\">{{ PL.get(s.periodicity, s.periodicity) }}<\/span>\n          • {% if s.days == null %}لم يمر بعد{% else %}<span style=\"white-space:nowrap\">{{ s.days }} يوم<\/span>{% endif %}\n          {% if s.goods %} • {{ s.goods }}{% endif %}<\/span>\n      <\/span>\n      <span class=\"amt\" style=\"display:flex; gap:6px; flex-direction:column\">\n        {% if s.phone %}<button type=\"button\" class=\"btn sm ghost nowrap\" style=\"min-width:92px; color:#128c7e\"\n          data-phone=\"{{ s.phone }}\" data-name=\"{{ s.name }}\" data-goods=\"{{ s.goods }}\"\n          onclick=\"waRemind(this, event)\">📲 تذكير<\/button>{% endif %}\n        <a class=\"btn sm p nowrap\" style=\"min-width:92px\" href=\"{{ url_for('suppliers') }}\">✔ مرّ اليوم<\/a>\n      <\/span>\n    <\/div>\n    {% endfor %}\n  <\/div>\n  {% if due_more %}<div class=\"center muted small mt\">و{{ due_more }} غيرهم — <a href=\"{{ url_for('suppliers') }}\">اعرض القائمة<\/a><\/div>{% endif %}\n  {% else %}\n  <div class=\"center muted\" style=\"padding:10px\">لا أحد متوقع اليوم وفق الدوريات ✔<\/div>\n  {% endif %}\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"h2\">اختصارات سريعة<\/div>\n  <div class=\"btn-grid mt\">\n    <a class=\"btn blue\" href=\"/cloud/pilot\">☁️ واجهة الاختبار السحابي المنفصلة<\/a>\n    <a class=\"btn p\" href=\"{{ url_for('pos') }}\">🛒 شاشة البيع<\/a>\n    <a class=\"btn blue\" href=\"{{ url_for('reports') }}\">📊 تقرير اليوم<\/a>\n    <a class=\"btn blue\" href=\"{{ url_for('reports') }}\">🏆 الأكثر بيعاً اليوم<\/a>\n    <a class=\"btn amber\" href=\"{{ url_for('customers') }}\">💰 ديون الزبائن<\/a>\n    <a class=\"btn amber\" href=\"{{ url_for('suppliers') }}\">🚚 الموردون والمناديب<\/a>\n    <a class=\"btn ghost\" href=\"{{ url_for('cash') }}\">🧾 الصندوق<\/a>\n    <a class=\"btn ghost\" href=\"{{ url_for('products', q='') }}\">📦 الأصناف<\/a>\n    <a class=\"btn ghost\" href=\"{{ url_for('imports') }}\">⬆️ أصناف الأمين · خطة PDF كناش<\/a>\n    <a class=\"btn ghost\" href=\"{{ url_for('reports') }}\">📈 فواتير اليوم وإلغاؤها<\/a>\n    <a class=\"btn ghost\" href=\"{{ url_for('settings') }}\">⚙️ الإعدادات والعاملون<\/a>\n  <\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">«العين عن بعد» — ما تراه الآن<\/div>\n  <div class=\"muted small mt\">\n    هذه اللوحة هي نواة فكرة «تعيش كأنك وسط عامليك»: مبيعات اللحظة، من باع وبكم، دخل الدرج، والديون.\n    قوائم الصلاحية ومتابعة الديون محلية على هاتف البيع؛ لم تُفعّل بعد مرآة Supabase للمالك أو إشعارات الهاتف خارج التطبيق.\n  <\/div>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script>\n/* البطاقات التي تحمل data-go تفتح النافذة المقصودة عبر رابط داخلي يلتقطه المحرّك */\ndocument.querySelectorAll('.stat[data-go]').forEach(function(el){\n  el.style.cursor = 'pointer';\n  el.addEventListener('click', function(){\n    var a = document.createElement('a'); a.href = el.getAttribute('data-go');\n    document.body.appendChild(a); a.click(); a.remove();\n  });\n});\nconst SUP_MSG = \"مرحباً {name} 👋\\nنحن \" + {{ S.store_name|tojson }} + \" — حان موعد توريد {goods}.\\nنرجو المرور اليوم، شكراً لك 🌹\";\nfunction waRemind(btn, ev){\n  ev.preventDefault(); ev.stopPropagation();\n  const d = btn.dataset;\n  waOpen(d.phone, SUP_MSG.replace('{name}', d.name || '').replace('{goods}', (d.goods || 'البضاعة')));\n}\n<\/script>\n{% endblock %}\n", "error.html": "{% extends \"base.html\" %}\n{% block title %}{{ title }}{% endblock %}\n{% block content %}\n<div class=\"center\" style=\"padding:26px 8px 10px\">\n  <div style=\"font-size:3.4rem;line-height:1\">{{ icon }}<\/div>\n  <div class=\"h1 mt\">{{ title }}<\/div>\n  <div class=\"muted\" style=\"max-width:34em;margin:8px auto 0\">{{ msg }}<\/div>\n\n  {% if code == 403 %}\n    <div class=\"card mt\" style=\"text-align:right;max-width:34em;margin-inline:auto\">\n      <div class=\"h2\">ما معنى هذا؟<\/div>\n      <div class=\"small muted\">\n        هذه الشاشة ليست مخصّصة لصلاحيتك. إن كنت تحتاجها، اطلب من <b>صاحب المتجر<\/b>\n        فتحها لك من حسابه.\n      <\/div>\n    <\/div>\n  {% endif %}\n\n  <div class=\"mt2\" style=\"display:flex;gap:10px;justify-content:center;flex-wrap:wrap\">\n    {% if u %}\n      <a class=\"btn p\" href=\"{{ url_for('pos') }}\">🛒 رجوع للبيع<\/a>\n      <a class=\"btn ghost\" href=\"{{ url_for('logout') }}\">تغيير المستخدم<\/a>\n    {% else %}\n      <a class=\"btn p\" href=\"{{ url_for('login') }}\">الذهاب لشاشة الدخول<\/a>\n    {% endif %}\n  <\/div>\n\n  {% if code == 500 %}\n    <div class=\"card mt small muted\" style=\"text-align:right;max-width:34em;margin-inline:auto\">\n      <b>مهم:<\/b> بياناتك محفوظة ولم تتأثر. أعد المحاولة، وإن تكرر الخطأ\n      فدوّن الوقت وما كنت تفعله وأخبر من يتابع النظام.\n    <\/div>\n  {% endif %}\n<\/div>\n{% endblock %}\n", "find.html": "{% extends \"base.html\" %}\n{% block title %}أين هذا الصنف؟{% endblock %}\n{% block content %}\n<div class=\"h1\">📍 أين هذا الصنف؟<\/div>\n<div class=\"muted small\">اكتب اسم الصنف أو باركوده — أو اكتب رقم الممر.<\/div>\n\n<form method=\"get\" class=\"row mt\">\n  <input name=\"q\" value=\"{{ q }}\" class=\"big grow\" placeholder=\"اسم الصنف / الباركود / ممر 3\"\n         autocomplete=\"off\" autofocus>\n  <button class=\"btn p\">بحث<\/button>\n<\/form>\n\n<div class=\"row wrap mt\" style=\"gap:6px\">\n  <a class=\"chipb\" href=\"{{ url_for('find_item', q='ممر 1') }}\">ممر 1<\/a>\n  <a class=\"chipb\" href=\"{{ url_for('find_item', q='ممر 2') }}\">ممر 2<\/a>\n  <a class=\"chipb\" href=\"{{ url_for('find_item', q='ممر 3') }}\">ممر 3<\/a>\n  <a class=\"chipb\" href=\"{{ url_for('find_item', q='ممر 4') }}\">ممر 4<\/a>\n  <a class=\"chipb\" href=\"{{ url_for('find_item', q='ممر 5') }}\">ممر 5<\/a>\n<\/div>\n\n{% if q %}\n  {% if res %}\n    {% if mode == 'location' %}\n      <div class=\"card tight mt\"><b>{{ res|length }}<\/b> صنفاً في هذا الموضع<\/div>\n    {% else %}\n      <div class=\"card tight mt\"><b>{{ res|length }}<\/b> نتيجة لـ «{{ q }}»<\/div>\n    {% endif %}\n\n    {% for p in res %}\n      <div class=\"find-card\">\n        <div class=\"nm\">{{ p.name }}<\/div>\n        <div class=\"loc {% if not loc_text(p) %}none{% endif %}\">\n          {% if loc_text(p) %}📍 {{ loc_text(p) }}{% else %}— بلا موقع مسجّل —{% endif %}\n        <\/div>\n        <div class=\"meta\">\n          <span class=\"pill b\">{{ p.price_cents|money }} {{ S.currency }}<\/span>\n          <span class=\"pill {{ 'r' if p.stock <= p.low_stock else 'g' }}\">\n            الرصيد: {{ '%g'|format(p.stock) }} {{ p.unit }}<\/span>\n          {% if p.barcode %}<span class=\"pill gray\">{{ p.barcode }}<\/span>{% endif %}\n        <\/div>\n      <\/div>\n    {% endfor %}\n  {% else %}\n    <div class=\"flash error mt\">لا شيء يطابق «{{ q }}».<\/div>\n    <div class=\"card\">\n      <div class=\"h2\">جرّب:<\/div>\n      <ul class=\"small\">\n        <li>اكتب جزءاً من الاسم: «شاي»، «زيت»<\/li>\n        <li>أو رقم الممر: «3» أو «ممر 3»<\/li>\n      <\/ul>\n    <\/div>\n  {% endif %}\n{% else %}\n  <div class=\"card mt center muted\">\n    <div style=\"font-size:2.2rem\">📦<\/div>\n    اكتب ما تبحث عنه في الأعلى.\n  <\/div>\n{% endif %}\n{% endblock %}\n", "import_preview.html": "{% extends \"base.html\" %}\n{% block title %}مراجعة الاستيراد{% endblock %}\n{% block content %}\n<div class=\"row\">\n  <div class=\"h1 grow\">{{ 'مراجعة الأصناف' if kind=='products' else 'مراجعة الديون' }}<\/div>\n  <a class=\"btn sm ghost\" href=\"{{ url_for('imports') }}\">← رجوع<\/a>\n<\/div>\n<div class=\"muted small\">الملف: {{ filename }}<\/div>\n\n<div class=\"grid g3 mt\">\n  <div class=\"stat green\"><div class=\"lbl\">صفوف سليمة<\/div><div class=\"val\">{{ ok }}<\/div><\/div>\n  <div class=\"stat amber\"><div class=\"lbl\">تحتاج انتباهك<\/div><div class=\"val\">{{ warn }}<\/div><\/div>\n  <div class=\"stat red\"><div class=\"lbl\">أخطاء (ستُتجاوز)<\/div><div class=\"val\">{{ err }}<\/div><\/div>\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"h2\">معاينة أول {{ [records|length, 200]|min }} صف من {{ records|length }}<\/div>\n  <div class=\"hint\">هذه معاينة فقط. راجع سعر الشراء <b>وسعر البيع<\/b> والباركود مع العبوة قبل الاعتماد؛ الأصناف الموجودة بنفس الباركود أو الاسم ستتحدّث أسعارها. غياب عمود الكمية يترك رصيد الموجود كما هو ويجعل رصيد الجديد صفراً. <b>تنبيه EAN‑13 لا يمنع الاستيراد ولا يثبت ارتباط الرمز بالمنتج: افحص العبوة بنفسك.<\/b> <b>لا يوجد زر تراجع أو حذف جماعي؛ لا تختبر ملفاً غير مؤكّد على بيانات متجرك.<\/b><\/div>\n  <div class=\"scroll-x mt\">\n  <table class=\"tbl\">\n    {% if kind=='products' %}\n      <tr><th>#<\/th><th>الحالة<\/th><th>الاسم<\/th><th>الباركود<\/th><th>سعر الشراء<\/th><th>سعر البيع<\/th><th>الكمية<\/th><th>الانتهاء<\/th><\/tr>\n      {% for r in records | slice(0, 200) %}\n        <tr>\n          <td class=\"small\">{{ r.row }}<\/td>\n          <td>{% if r.status=='ok' %}<span class=\"pill g\">جاهز<\/span>\n              {% elif r.status=='warn' %}<span class=\"pill a\">تنبيه<\/span>\n              {% else %}<span class=\"pill r\">خطأ<\/span>{% endif %}\n              {% if r.error %}<div class=\"small muted\">{{ r.error }}<\/div>{% endif %}<\/td>\n          <td>{{ r.name }}<\/td><td class=\"small\">{{ r.barcode or '—' }}<\/td>\n          <td>{{ r.cost_cents|money }}<\/td><td><b>{{ r.price_cents|money }}<\/b><\/td>\n          <td>{% if r.stock_provided %}{{ '%g'|format(r.stock) }}{% else %}غير محددة (الموجود محفوظ، الجديد 0){% endif %}<\/td>\n          <td class=\"small\">{{ r.expiry or '—' }}<\/td>\n        <\/tr>\n      {% endfor %}\n    {% else %}\n      <tr><th>#<\/th><th>الحالة<\/th><th>الزبون<\/th><th>الهاتف<\/th><th>الدين<\/th><\/tr>\n      {% for r in records | slice(0, 200) %}\n        <tr>\n          <td class=\"small\">{{ r.row }}<\/td>\n          <td>{% if r.status=='ok' %}<span class=\"pill g\">جاهز<\/span>\n              {% elif r.status=='warn' %}<span class=\"pill a\">تنبيه<\/span>\n              {% else %}<span class=\"pill r\">خطأ<\/span>{% endif %}\n              {% if r.error %}<div class=\"small muted\">{{ r.error }}<\/div>{% endif %}<\/td>\n          <td>{{ r.name }}<\/td><td class=\"small\">{{ r.phone or '—' }}<\/td>\n          <td>{{ r.amount_cents|money }}<\/td>\n        <\/tr>\n      {% endfor %}\n    {% endif %}\n  <\/table>\n  <\/div>\n<\/div>\n\n<form method=\"POST\" action=\"{{ url_for('imports_commit') }}\"\n      onsubmit=\"return confirm('تأكيد حفظ الأصناف؟ ستتغيّر أسعار الأصناف الموجودة، ولا يوجد تراجع جماعي عن الاستيراد. الصفوف ذات الخطأ ستُتجاوز.')\">\n  <input type=\"hidden\" name=\"kind\" value=\"{{ kind }}\">\n  <input type=\"hidden\" name=\"token\" value=\"{{ token }}\">\n  <div class=\"btn-grid\">\n    <button class=\"btn p lg\" style=\"grid-column:span 2\">✅ تأكيد الاستيراد الآن<\/button>\n    <a class=\"btn ghost lg\" style=\"grid-column:span 2\" href=\"{{ url_for('imports') }}\">إلغاء<\/a>\n  <\/div>\n<\/form>\n<div class=\"hint\">الأصناف المطابقة (بنفس الباركود أو الاسم) تُحدَّث ولا تتكرر. استيراد ديون CSV القديم مُعطّل، ولا تؤثر هذه القائمة في ديون الزبائن حتى تُنشئ عمليات بيع حقيقية.<\/div>\n{% endblock %}\n", "imports.html": "{% extends \"base.html\" %}\n{% block title %}الاستيراد{% endblock %}\n{% block content %}\n<div class=\"h1\">استيراد البيانات<\/div>\n<div class=\"muted small mt\">راجع الملف كاملاً قبل الحفظ. أصناف الأمين متاحة تجريبياً؛ ديون كناش لا تُرحّل تلقائياً من PDF.<\/div>\n\n<div class=\"grid g2 mt\">\n  <div class=\"card\">\n    <div class=\"h2\">📦 أصناف الأمين<\/div>\n    <div class=\"muted small mt\">اختر ملف XLSX أو CSV. تُعرض معاينة فقط قبل تأكيد الحفظ؛ راجع باركود العبوة وسعر البيع والتكلفة والرصيد. الملف بلا كمية يُضيف الجديد برصيد صفر ولا يمس رصيد الموجود؛ لكنه قد يُغيّر أسعاره. <b>لا يوجد حذف جماعي أو تراجع عن الاستيراد: لا تجرّب ملفاً غير موثوق على هاتف فيه بيانات مهمة.<\/b><\/div>\n    <form method=\"POST\" action=\"{{ url_for('imports_upload') }}\" enctype=\"multipart/form-data\" class=\"mt\">\n      <input type=\"hidden\" name=\"kind\" value=\"products\">\n      <input type=\"file\" name=\"file\" accept=\".csv,.xlsx\" required>\n      <button class=\"btn p wide mt\">⬆️ رفع الأصناف ومراجعتها<\/button>\n    <\/form>\n    <a class=\"btn ghost sm mt\" href=\"{{ url_for('import_template', kind='products') }}\">⬇️ نموذج أصناف CSV<\/a>\n  <\/div>\n\n  <div class=\"card\">\n    <div class=\"h2\">💰 كناش — قراءة PDF على الهاتف<\/div>\n    <p class=\"muted small mt\">التقرير الأصلي «الوضع حسب العميل» يحتوي طبقة نص. تُقرأ الصفحات ومجاميع «أعطيت/أخذت» والرصيد محلياً بلا شبكة. إذا كان PDF صورة فقط أو اختلفت بنيته فلا نخمن أسماء أو أرقاماً.<\/p>\n    {% if u and u.role == 'owner' %}\n      <label for=\"knaashPdf\" class=\"small\"><b>اختر تصدير كناش الأصلي PDF:<\/b><\/label>\n      <input id=\"knaashPdf\" type=\"file\" accept=\"application/pdf,.pdf\" class=\"mt\">\n      <p id=\"knaashStatus\" class=\"small muted mt\" role=\"status\">لا ملف مفتوح. المعاينة لا تغيّر بيانات الزبائن.<\/p>\n    {% else %}\n      <div class=\"hint mt\">مراجعة كشف كناش مخصّصة للمالك؛ لا يُنقل أي رصيد من حساب العامل.<\/div>\n    {% endif %}\n    <div class=\"hint mt\"><b>قراءة فقط — لا يوجد زر ترحيل ديون في هذه النسخة.<\/b> يوجد في الكشوف أرصدة لصالح بعض الزبائن وأرصدة صفرية. لا تربط الأسماء تلقائياً ولا تدخل الرصيد نفسه يدوياً ثم تستورده. استيراد ديون CSV القديم مُعطّل لحماية الأرصدة.<\/div>\n  <\/div>\n<\/div>\n\n{% if u and u.role == 'owner' %}\n<div class=\"card mt\" id=\"knaashPreview\" style=\"display:none\" aria-live=\"polite\">\n  <div class=\"h2\">تدقيق التقرير — بلا ترحيل<\/div>\n  <div id=\"knaashSummary\" class=\"mt small\"><\/div>\n  <div class=\"hint mt\"><b>قبل أي اعتماد لاحق:<\/b> قارن الاسم والرقم مع PDF لكل صف، واربطه بعميل رفيق بعينه أو أنشئه بعد التأكد من عدم وجود نسخة مكررة. وحدة العملة غير مذكورة صراحة في التقرير؛ تأكد منها. لا تُنقل الحركات والرصيد الافتتاحي معاً، ولا يُرحّل هذا الكشف إلى هاتفين مستقلين بلا مزامنة.<\/div>\n  <div class=\"row mt\" style=\"flex-wrap:wrap;gap:6px\">\n    <button type=\"button\" class=\"btn ghost sm\" id=\"knaashAll\">كل الصفوف<\/button>\n    <button type=\"button\" class=\"btn ghost sm\" id=\"knaashCredits\">أرصدة لصالح الزبائن<\/button>\n    <button type=\"button\" class=\"btn ghost sm\" id=\"knaashZeros\">أرصدة صفرية<\/button>\n  <\/div>\n  <div class=\"mt\" style=\"overflow-x:auto\">\n    <table class=\"tbl\" id=\"knaashTable\">\n      <thead><tr><th>الصف / الصفحة<\/th><th>اسم كناش (تدقيق يدوي)<\/th><th>الهاتف<\/th><th>أعطيت<\/th><th>أخذت<\/th><th>الرصيد الموقّع<\/th><th>مراجعة العميل<\/th><\/tr><\/thead>\n      <tbody><\/tbody>\n    <\/table>\n  <\/div>\n  <p id=\"knaashShown\" class=\"small muted mt\"><\/p>\n  <button type=\"button\" id=\"knaashMore\" class=\"btn ghost sm\" style=\"display:none\">عرض 20 صفاً تالياً<\/button>\n\n  <div class=\"hint mt\" id=\"knaashProgress\">يمكن حفظ مراجعة الأسماء على هذا الهاتف والعودة إليها لاحقاً. لم تُنقل أي ديون.<\/div>\n  <div id=\"knaashOtherFile\" class=\"hint mt\" style=\"display:none\">\n    <span id=\"knaashOtherFileMessage\">توجد مراجعة محفوظة لكشف كناش آخر. لن نخلط الملفين.<\/span>\n    <button type=\"button\" class=\"btn ghost sm mt\" id=\"knaashClearOld\">امسح مراجعة الكشف القديم فقط<\/button>\n  <\/div>\n  <div class=\"card mt\" id=\"knaashReviewPanel\" style=\"display:none\">\n    <div class=\"h2\">راجع هذا العميل<\/div>\n    <p class=\"small\" id=\"knaashRowTitle\"><\/p>\n    <div class=\"hint small\">قارن الاسم والرصيد مع ملف كناش. لن نختار عميلاً بالاسم وحده، ولن نضيف ديناً الآن.<\/div>\n    <div class=\"row mt\" style=\"flex-wrap:wrap;gap:6px\">\n      <button type=\"button\" class=\"btn ghost sm\" id=\"knaashNew\">عميل جديد<\/button>\n      <button type=\"button\" class=\"btn ghost sm\" id=\"knaashExisting\">موجود في رفيق<\/button>\n      <button type=\"button\" class=\"btn ghost sm\" id=\"knaashZero\" style=\"display:none\">رصيده صفر؛ لا أنقل ديناً<\/button>\n    <\/div>\n    <div id=\"knaashNewFields\" class=\"mt\" style=\"display:none\">\n      <label for=\"knaashNewName\">الاسم الصحيح في رفيق<\/label>\n      <input id=\"knaashNewName\" maxlength=\"120\" autocomplete=\"off\">\n      <label for=\"knaashNewPhone\">رقم الهاتف، إن وجد<\/label>\n      <input id=\"knaashNewPhone\" maxlength=\"40\" inputmode=\"tel\" autocomplete=\"off\">\n    <\/div>\n    <div id=\"knaashExistingFields\" class=\"mt\" style=\"display:none\">\n      <label for=\"knaashSearch\">ابحث عن العميل باسمه أو رمزه أو هاتفه<\/label>\n      <div class=\"row\"><input id=\"knaashSearch\" class=\"grow\" autocomplete=\"off\"><button type=\"button\" class=\"btn sm\" id=\"knaashFind\">ابحث<\/button><\/div>\n      <div id=\"knaashMatches\" class=\"mt\"><\/div>\n      <p id=\"knaashPicked\" class=\"small mt\"><\/p>\n    <\/div>\n    <p id=\"knaashZeroText\" class=\"small mt\" style=\"display:none\">سيُحسب هذا العميل ضمن التقرير، لكن لن ننشئ له ديناً.<\/p>\n    <label class=\"mt\"><input type=\"checkbox\" id=\"knaashChecked\"> قارنت الاسم والرصيد مع كشف كناش وتأكدت من اختياري<\/label>\n    <div class=\"row mt\" style=\"gap:6px\">\n      <button type=\"button\" class=\"btn p\" id=\"knaashSave\">احفظ مراجعتي لهذا العميل<\/button>\n      <button type=\"button\" class=\"btn ghost\" id=\"knaashClose\">إغلاق<\/button>\n    <\/div>\n    <p id=\"knaashReviewMsg\" class=\"small mt\" role=\"status\"><\/p>\n  <\/div>\n<\/div>\n{% endif %}\n\n<div class=\"card mt\">\n  <div class=\"h2\">سجل عمليات الاستيراد السابقة<\/div>\n  <table class=\"tbl\">\n    <tr><th>التاريخ<\/th><th>النوع<\/th><th>الملف<\/th><th>جديد<\/th><th>محدَّث<\/th><th>أخطاء متجاوَزة<\/th><th>بواسطة<\/th><\/tr>\n    {% for l in logs %}\n      <tr>\n        <td class=\"small\">{{ l.created_at | slice(0, 16) }}<\/td>\n        <td>{{ 'أصناف' if l.kind=='products' else 'ديون سابقة' }}<\/td>\n        <td class=\"small\">{{ l.filename }}<\/td>\n        <td>{{ l.added }}<\/td><td>{{ l.updated }}<\/td><td>{{ l.errors }}<\/td>\n        <td class=\"small\">{{ l.uname }}<\/td>\n      <\/tr>\n    {% endfor %}\n    {% if not logs %}<tr><td colspan=\"7\" class=\"center muted\">لا عمليات بعد<\/td><\/tr>{% endif %}\n  <\/table>\n<\/div>\n\n{% if u and u.role == 'owner' %}\n<script src=\"../knaash/reader.js\"><\/script>\n<script src=\"../knaash/review_ui.js\"><\/script>\n<script>\n(function () {\n  'use strict';\n  var chooser = document.getElementById('knaashPdf');\n  if (!chooser) return;\n  var status = document.getElementById('knaashStatus');\n  var preview = document.getElementById('knaashPreview');\n  var summary = document.getElementById('knaashSummary');\n  var body = document.querySelector('#knaashTable tbody');\n  var shown = document.getElementById('knaashShown');\n  var more = document.getElementById('knaashMore');\n  var records = [], filter = 'all', count = 0, generation = 0, review = null;\n\n  function money(cents) {\n    var abs = Math.abs(cents), whole = Math.floor(abs / 100);\n    return (cents < 0 ? '−' : '') + String(whole).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',') +\n      ',' + String(abs % 100).padStart(2, '0');\n  }\n  function message(value, error) {\n    status.textContent = value;\n    status.style.color = error ? '#b91c1c' : '';\n  }\n  function line(label, value) {\n    var item = document.createElement('div');\n    var bold = document.createElement('b');\n    bold.textContent = label + ': ';\n    item.appendChild(bold);\n    item.appendChild(document.createTextNode(value));\n    summary.appendChild(item);\n  }\n  function matching() {\n    return filter === 'all' ? records : records.filter(function (r) { return r.kind === filter; });\n  }\n  function draw() {\n    var items = matching();\n    body.textContent = '';\n    items.slice(0, count).forEach(function (r) {\n      var tr = document.createElement('tr');\n      var signed = (r.kind === 'credit' ? 'لصالح العميل ' : r.kind === 'zero' ? 'صفر ' : 'دين ') + money(r.balanceCents);\n      [r.index + ' / ' + r.page, r.sourceName, r.phone || '—',\n       money(r.givenCents), money(r.takenCents), signed].forEach(function (v, i) {\n        var td = document.createElement('td');\n        td.textContent = v;  // بيانات PDF لا تدخل HTML خاماً\n        if (i === 2) td.dir = 'ltr';\n        if (i === 5 && r.kind === 'credit') td.style.color = '#08755a';\n        tr.appendChild(td);\n      });\n      var action = document.createElement('td');\n      var button = document.createElement('button');\n      button.type = 'button'; button.className = 'btn ghost sm';\n      button.textContent = review ? review.label(r.index) : 'المراجعة غير متاحة';\n      button.disabled = !review || !review.canReview();\n      if (review) button.addEventListener('click', function () { review.open(r); });\n      action.appendChild(button); tr.appendChild(action);\n      body.appendChild(tr);\n    });\n    shown.textContent = 'معروض ' + Math.min(count, items.length) + ' من ' + items.length + ' صفاً. جميع الصفوف مدقّقة حسابياً فقط، لا هوية العملاء.';\n    more.style.display = count < items.length ? '' : 'none';\n  }\n  function choose(which) { filter = which; count = 20; draw(); }\n  document.getElementById('knaashAll').addEventListener('click', function () { choose('all'); });\n  document.getElementById('knaashCredits').addEventListener('click', function () { choose('credit'); });\n  document.getElementById('knaashZeros').addEventListener('click', function () { choose('zero'); });\n  more.addEventListener('click', function () { count += 20; draw(); });\n\n  function read(file) {\n    return new Promise(function (resolve, reject) {\n      var reader = new FileReader();\n      reader.onload = function () { resolve(new Uint8Array(reader.result)); };\n      reader.onerror = function () { reject(new Error('تعذّرت قراءة ملف الهاتف.')); };\n      reader.readAsArrayBuffer(file);\n    });\n  }\n  function sha(bytes) {\n    if (!window.crypto || !crypto.subtle) return Promise.resolve(null);\n    return crypto.subtle.digest('SHA-256', bytes.buffer).then(function (digest) {\n      return Array.from(new Uint8Array(digest)).map(function (b) {\n        return b.toString(16).padStart(2, '0');\n      }).join('');\n    }).catch(function () { return null; });\n  }\n  chooser.addEventListener('change', async function () {\n    var file = chooser.files && chooser.files[0];\n    if (!file) return;\n    var thisRun = ++generation;\n    if (review) review.dispose();\n    records = []; review = null; preview.style.display = 'none'; summary.textContent = '';\n    document.getElementById('knaashReviewPanel').style.display = 'none';\n    document.getElementById('knaashOtherFile').style.display = 'none';\n    message('تجري قراءة الكشف على هذا الهاتف…', false);\n    try {\n      if (file.size > 10 * 1024 * 1024) throw new Error('حجم PDF أكبر من حد الأمان 10 ميغابايت.');\n      var bytes = await read(file);\n      var fingerprint = await sha(bytes); // قبل أن ينقل PDF.js ذاكرة الملف إلى عامل القراءة\n      var pdfjs = await import(new URL('../knaash/pdf.min.js', location.href).href);\n      pdfjs.GlobalWorkerOptions.workerSrc = new URL('../knaash/pdf.worker.min.js', location.href).href;\n      var result = await window.KnaashPdf.inspect(bytes, pdfjs);\n      if (!chooser.isConnected || thisRun !== generation) return;\n      records = result.rows;\n      line('تاريخ التقرير', result.reportDateIso);\n      line('الصفحات / العملاء', result.pageCount + ' / ' + result.sourceCount);\n      line('رمز هذا الملف (لمنع خلط كشوف مختلفة)', fingerprint ? fingerprint.slice(0, 16) + '…' : 'غير متاح على هذا الهاتف');\n      line('أعطيت / أخذت / الصافي الموقّع', money(result.totals.givenCents) + ' / ' +\n        money(result.totals.takenCents) + ' / ' + money(result.totals.netCents));\n      line('ديون لصالح المتجر', result.counts.debt + ' صفاً = ' + money(result.totals.grossDebtCents));\n      line('أرصدة لصالح الزبائن', result.counts.credit + ' صفوف = ' + money(result.totals.grossCreditCents));\n      line('أرصدة صفرية', result.counts.zero + ' صفوف (محسوبة في عدد العملاء، بلا دين)');\n      preview.style.display = '';\n      if (fingerprint && window.RafiqKnaashReview) {\n        var currentReview = window.RafiqKnaashReview.create({\n          root: preview, rows: records, sourceSha256: fingerprint,\n          reportDateIso: result.reportDateIso,\n          isActive: function () { return thisRun === generation && chooser.isConnected; },\n          onChange: function () { if (thisRun === generation) draw(); },\n        });\n        review = currentReview;\n        try {\n          await currentReview.load();\n        } catch (reviewError) {\n          if (thisRun === generation && review === currentReview) {\n            currentReview.dispose();\n            review = null;\n            document.getElementById('knaashProgress').textContent =\n              'فُتح الكشف، لكن تعذر حفظ مراجعة الأسماء الآن. لا تتغير الأرصدة.';\n          }\n        }\n      } else {\n        document.getElementById('knaashProgress').textContent =\n          'يعرض الهاتف الكشف، لكن لا يستطيع حفظ مراجعة الأسماء حالياً. لا تتغير الأرصدة.';\n      }\n      if (!chooser.isConnected || thisRun !== generation) return;\n      choose('all');\n      if (review && review.canReview()) {\n        message('تطابقت مبالغ الكشف. يمكنك مراجعة الأسماء وحفظ تقدمك؛ لم يُنقل أي دين.', false);\n      } else if (review) {\n        message('تطابقت مبالغ الكشف، لكن هناك مراجعة لكشف آخر محفوظة على هذا الهاتف؛ لم يُنقل أي دين.', false);\n      } else {\n        message('تطابقت مبالغ الكشف، لكن حفظ مراجعة الأسماء غير متاح حالياً؛ لم يُنقل أي دين.', true);\n      }\n    } catch (e) {\n      if (thisRun !== generation) return;\n      var reason = e && e.message || '';\n      // لا تُظهر رسائل مكتبة PDF الداخلية؛ قد تحتوي تفاصيل من المستند الخاص.\n      message(/^[\\u0600-\\u06ff]/.test(reason) ? reason : 'تعذّر استخراج هذا PDF محلياً؛ لا تُستورد بيانات غير مؤكّدة.', true);\n      preview.style.display = 'none';\n    } finally {\n      chooser.value = '';\n    }\n  });\n})();\n<\/script>\n{% endif %}\n{% endblock %}\n", "invoice.html": "{% extends \"base.html\" %}\n{% block title %}فاتورة {{ inv.number }}{% endblock %}\n{% block bodyclass %}invoice-page {{ 'has-a4' if a4 else 'receipt-only' }}{% endblock %}\n{% block wrap %}\n<div class=\"wrap\">\n  <div class=\"invoice-tools no-print\">\n    <div class=\"invoice-tools-top\">\n      <div class=\"h1\">فاتورة رقم {{ inv.number }}<\/div>\n      <a class=\"btn sm ghost\" href=\"{{ url_for('pos') }}\">← رجوع للبيع<\/a>\n    <\/div>\n    <div class=\"invoice-actions\">\n      <a class=\"btn sm ghost\" href=\"{{ url_for('invoice', iid=inv.id, a4=0 if a4 else 1) }}\">\n        {{ 'معاينة حرارية' if a4 else 'معاينة A4' }}<\/a>\n      <button type=\"button\" class=\"btn sm p\" onclick=\"printInvoice('a4')\">🖨 طباعة A4<\/button>\n      <button type=\"button\" class=\"btn sm p\" onclick=\"printInvoice('receipt')\">🧾 طباعة حرارية<\/button>\n      <button type=\"button\" class=\"btn sm p\" onclick=\"printInvoice('both')\">🖨 طباعة الاثنين<\/button>\n      {% if customer and customer.phone and inv.status == 'open' %}\n      <button type=\"button\" class=\"btn sm blue\" id=\"shareInvoicePdf\" onclick=\"shareInvoicePdf()\">📤 مشاركة PDF للزبون<\/button>\n      {% endif %}\n    <\/div>\n  <\/div>\n\n  {% if inv.status == 'cancelled' %}\n    <div class=\"flash error mt no-print\">هذه الفاتورة <b>ملغاة<\/b> — أُعيد المخزون ورُد النقد المسجّل إن وجد.<\/div>\n  {% endif %}\n\n  <div class=\"mt2\"><\/div>\n\n  <!-- ===== نسخة حرارية 80مم ===== -->\n  <div class=\"receipt\">\n    {% if S.store_logo %}<img class=\"logo-mono\" src=\"{{ S.store_logo }}\" alt=\"\">{% endif %}\n    <h3>{{ S.store_name }}<\/h3>\n    {% if S.store_phone %}<div class=\"center\" dir=\"ltr\">{{ S.store_phone }}<\/div>{% endif %}\n    <div class=\"line\"><\/div>\n    <table>\n      <tr><td>فاتورة رقم<\/td><td class=\"tl\"><b>{{ inv.number }}<\/b><\/td><\/tr>\n      <tr><td>التاريخ<\/td><td class=\"tl\"><bdi dir=\"ltr\">{{ inv.created_at }}<\/bdi><\/td><\/tr>\n      <tr><td>الموظف<\/td><td class=\"tl\">{{ worker.name if worker else '' }}<\/td><\/tr>\n      {% if customer %}<tr><td>الزبون<\/td><td class=\"tl\">{{ customer.name }}<\/td><\/tr>{% endif %}\n      <tr><td>الدفع<\/td><td class=\"tl\">{{ 'نقدي' if inv.payment_type=='cash' else 'آجل' }}<\/td><\/tr>\n      {% for p in payments %}<tr><td>{{ p.label }}<\/td><td class=\"tl\">{{ p.amount }}{% if p.ref %} — مرجع {{ p.ref }}{% endif %}<\/td><\/tr>{% endfor %}\n    <\/table>\n    <div class=\"line\"><\/div>\n    <table>\n      <tr><th>الصنف<\/th><th>كمية<\/th><th>سعر<\/th><th class=\"tl\">إجمالي<\/th><\/tr>\n      {% for it in items %}\n      <tr>\n        <td>{{ it.name }}<\/td>\n        <td>{{ '%g'|format(it.qty) }}<\/td>\n        <td>{{ it.price_cents|money }}<\/td>\n        <td class=\"tl\">{{ it.total_cents|money }}<\/td>\n      <\/tr>\n      {% endfor %}\n    <\/table>\n    <div class=\"line\"><\/div>\n    <table>\n      <tr><td>المجموع<\/td><td class=\"tl\">{{ inv.subtotal_cents|money }}<\/td><\/tr>\n      {% if inv.discount_cents %}<tr><td>الخصم<\/td><td class=\"tl\">- {{ inv.discount_cents|money }}<\/td><\/tr>{% endif %}\n      <tr class=\"grand\"><td>الإجمالي<\/td><td class=\"tl\">{{ inv.total_cents|money }} {{ S.currency }}<\/td><\/tr>\n      {% if inv.payment_type=='cash' %}\n        <tr><td>المستلم<\/td><td class=\"tl\">{{ (inv.received_cents or inv.total_cents)|money }}<\/td><\/tr>\n        <tr><td>الباقي<\/td><td class=\"tl\">{{ (inv.change_cents or 0)|money }}<\/td><\/tr>\n      {% else %}\n        <tr><td>دُفع الآن<\/td><td class=\"tl\">{{ inv.paid_cents|money }}<\/td><\/tr>\n        <tr class=\"grand\"><td>الباقي ديناً<\/td><td class=\"tl\">{{ inv.due_cents|money }} {{ S.currency }}<\/td><\/tr>\n      {% endif %}\n    <\/table>\n    <div class=\"line\"><\/div>\n    <div class=\"center\">{{ S.invoice_footer }}<\/div>\n    \n  <\/div>\n\n  <!-- ===== نسخة A4 ===== -->\n  <div class=\"a4\">\n    <div class=\"head\">\n      <div>\n        {% if S.store_logo %}<img class=\"logo-mono\" style=\"margin:0 0 4px\" src=\"{{ S.store_logo }}\" alt=\"\">{% endif %}\n        <h2 style=\"margin:0\">{{ S.store_name }}<\/h2>\n        {% if S.store_phone %}<div>هاتف: {{ S.store_phone }}<\/div>{% endif %}\n      <\/div>\n      <div style=\"text-align:left\">\n        <div><b>فاتورة رقم: {{ inv.number }}<\/b><\/div>\n        <div dir=\"ltr\">{{ inv.created_at }}<\/div>\n        <div>الموظف: {{ worker.name if worker else '' }}<\/div>\n      <\/div>\n    <\/div>\n    {% if customer %}\n      <div><b>الزبون:<\/b> {{ customer.name }} {% if customer.phone %} — {{ customer.phone }}{% endif %}<\/div>\n    {% endif %}\n    <div><b>طريقة الدفع:<\/b> {{ 'نقدي' if inv.payment_type=='cash' else 'آجل' }}\n      {% if inv.status=='cancelled' %}<span style=\"color:#b91c1c\"> — ملغاة<\/span>{% endif %}<\/div>\n    <table>\n      <thead><tr><th style=\"width:40px\">#<\/th><th>الصنف<\/th><th>الوحدة<\/th><th>الكمية<\/th><th>السعر<\/th><th>الإجمالي<\/th><\/tr><\/thead>\n      <tbody>\n      {% for it in items %}\n        <tr><td>{{ loop.index }}<\/td><td>{{ it.name }}<\/td><td>{{ it.unit }}<\/td>\n            <td>{{ '%g'|format(it.qty) }}<\/td><td>{{ it.price_cents|money }}<\/td><td>{{ it.total_cents|money }}<\/td><\/tr>\n      {% endfor %}\n      <\/tbody>\n    <\/table>\n    <table class=\"invoice-totals\">\n      <tr><td>المجموع<\/td><td>{{ inv.subtotal_cents|money }}<\/td><\/tr>\n      {% if inv.discount_cents %}<tr><td>الخصم<\/td><td>- {{ inv.discount_cents|money }}<\/td><\/tr>{% endif %}\n      <tr><td><b>الإجمالي<\/b><\/td><td><b>{{ inv.total_cents|money }} {{ S.currency }}<\/b><\/td><\/tr>\n      <tr><td>المدفوع<\/td><td>{{ inv.paid_cents|money }}<\/td><\/tr>\n      <tr><td>الباقي<\/td><td>{{ inv.due_cents|money }}<\/td><\/tr>\n    <\/table>\n    <div class=\"center\" style=\"margin-top:26px\">{{ S.invoice_footer }}<\/div>\n  <\/div>\n\n\n\n  {% if u and u.role=='owner' and inv.status=='open' %}\n  <div class=\"card no-print\">\n    <div class=\"h2\">إلغاء الفاتورة (للمالك فقط)<\/div>\n    <div class=\"muted small mt\">الفاتورة تعود للمخزون وتُخرج قيمتها النقدية من الصندوق تلقائياً.<\/div>\n    <form method=\"POST\" action=\"{{ url_for('invoice_cancel', iid=inv.id) }}\" class=\"mt\"\n          onsubmit=\"return confirm('تأكيد إلغاء الفاتورة رقم {{ inv.number }}؟')\">\n      <button class=\"btn red\">إلغاء الفاتورة<\/button>\n    <\/form>\n  <\/div>\n  {% endif %}\n<\/div>\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction printInvoice(mode){\n  document.body.classList.remove('print-a4', 'print-receipt', 'print-both');\n  document.body.classList.add('print-' + mode);\n  // ترك فرصة للمتصفح لتطبيق تنسيق الورق قبل إنشاء مستند الطباعة الأصلي.\n  requestAnimationFrame(() => window.print());\n}\nfunction shareInvoicePdf(){\n  if(!window.RafiqDevice || !window.RafiqDevice.shareInvoicePdf){\n    toast('مشاركة PDF متاحة داخل تطبيق Android فقط','err'); return;\n  }\n  {% if customer and customer.phone and inv.status == 'open' %}\n  const name = {{ customer.name|tojson }}, phone = {{ customer.phone|tojson }};\n  if(!confirm('فاتورة رقم {{ inv.number }}، الإجمالي {{ inv.total_cents|money }} {{ S.currency }}.\\n'\n    +'الزبون: '+name+'، هاتفه: '+phone+'، دينه الحالي: {{ customer.balance_cents|money }} {{ S.currency }}.\\n'\n    +'بعد المتابعة اختر تطبيق الإرسال والمستلم الصحيح بنفسك؛ فتح القائمة لا يعني أن الفاتورة أُرسلت.')) return;\n  window.RafiqDevice.shareInvoicePdf({{ inv.id }});\n  {% endif %}\n}\n{% if autoprint %}window.addEventListener('load', ()=> setTimeout(()=>window.print(), 400));{% endif %}\n<\/script>\n{% endblock %}\n", "login.html": "{% extends \"base.html\" %}\n{% block title %}الدخول{% endblock %}\n{% block wrap %}\n<div class=\"wrap\">\n<div class=\"card login-card\">\n  <div class=\"center\">\n    <img class=\"login-logo\" src=\"{{ url_for('static', filename='brand/logo_full.png') }}\" alt=\"رفيق — RAFiQ POS\">\n    <div class=\"muted small\">من يفتح الجلسة؟<\/div>\n  <\/div>\n\n  <div class=\"mt\">\n    {% for us in users %}\n      <button type=\"button\" class=\"user-btn\" data-uid=\"{{ us.id }}\" data-name=\"{{ us.name }}\">\n        <span class=\"avatar\">{{ us.name[0] }}<\/span>\n        <span class=\"grow\">{{ us.name }}\n          <span class=\"pill {{ 'b' if us.role=='owner' else 'gray' }}\" style=\"margin-inline-start:6px\">\n            {{ 'المالك' if us.role=='owner' else 'عامل' }}<\/span>\n        <\/span>\n      <\/button>\n    {% endfor %}\n  <\/div>\n\n  <div class=\"pin-dots\" id=\"dots\"><span><\/span><span><\/span><span><\/span><span><\/span><\/div>\n  <div class=\"center muted small\" id=\"selName\">اختر المستخدم ثم أدخل الرمز<\/div>\n\n  <div class=\"num-pad\">\n    {% for n in ['1','2','3','4','5','6','7','8','9','C','0','⌫'] %}\n      <button type=\"button\" class=\"btn\" data-k=\"{{ n }}\">{{ n }}<\/button>\n    {% endfor %}\n  <\/div>\n  <button class=\"btn p lg wide mt\" id=\"enterBtn\">دخول<\/button>\n\n  {% if S.demo_hint == '1' %}\n  <div class=\"hint mt\">رموز التجربة: صاحب المتجر 1111 • أحمد 2222 • سالم 3333<\/div>\n  {% endif %}\n<\/div>\n<\/div>\n{% endblock %}\n\n{% block scripts %}\n<script>\nlet uid = null, pin = '';\nconst dots = document.querySelectorAll('#dots span');\nfunction draw(){\n  dots.forEach((d,i)=> d.classList.toggle('f', i < pin.length));\n}\ndocument.querySelectorAll('.user-btn').forEach(b=>{\n  b.onclick = ()=>{\n    document.querySelectorAll('.user-btn').forEach(x=>x.classList.remove('on'));\n    b.classList.add('on');\n    uid = b.dataset.uid; pin = ''; draw();\n    document.getElementById('selName').textContent = 'تم اختيار: ' + b.dataset.name;\n  };\n});\ndocument.querySelectorAll('.num-pad .btn').forEach(b=>{\n  b.onclick = ()=>{\n    const k = b.dataset.k;\n    if(k==='C'){ pin=''; }\n    else if(k==='⌫'){ pin = pin.slice(0,-1); }\n    else if(pin.length < 4){ pin += k; }\n    draw();\n    if(pin.length===4){ setTimeout(enter, 120); }\n  };\n});\ndocument.getElementById('enterBtn').onclick = enter;\nfunction enter(){\n  if(!uid){ toast('اختر المستخدم أولاً','err'); return; }\n  if(pin.length!==4){ toast('الرمز 4 أرقام','err'); return; }\n  const f = document.createElement('form');\n  f.method = 'POST'; f.action = '/login' + location.search;\n  f.innerHTML = '<input name=\"uid\" value=\"'+uid+'\"><input name=\"pin\" value=\"'+pin+'\">';\n  document.body.appendChild(f); f.submit();\n}\n<\/script>\n{% endblock %}\n", "pos.html": "{% extends \"base.html\" %}\n{% block title %}البيع{% endblock %}\n{% block bodyclass %}{% endblock %}\n{% block wrap %}\n{% if cloud_shift_only %}\n<div class=\"wrap\">\n  <div class=\"h1\">🛒 البيع<\/div>\n  <div class=\"flash error\">توقّف البيع والآجل من الشاشة المحلية: الوردية السابقة على هذا الهاتف ليست تصريحاً من الخادم، ولم يُربط دفتر البيع والديون الأصلي بعد.<\/div>\n  <p class=\"card\">افتح <a href=\"{{ url_for('cash') }}\">شاشة الصندوق الأصلية<\/a> لطلب الوردية ومتابعة قرار المالك. لا تسجّل بيعاً نقدياً أو بالدين حتى تُستكمل المرحلة الثانية ويجتاز التطبيق اختبار الهاتفين.<\/p>\n<\/div>\n{% else %}\n<div class=\"pos-wrap\">\n  {% set msgs = get_flashed_messages(with_categories=true) %}\n    {% for cat, m in msgs %}<div class=\"flash {{ cat }}\">{{ m }}<\/div>{% endfor %}\n  \n\n  <div class=\"hint\" style=\"margin:10px 0\">هذه شاشة البيع <b>المحلية القديمة<\/b>، ولا تُزامن فواتيرها مع مشروع الاختبار. <a href=\"/cloud/pilot\">افتح تجربة البيع السحابي المنفصلة<\/a>.<\/div>\n  {% if not shift %}\n  <div class=\"flash error\">\n    الصندوق مغلق — لا يمكن البيع الآن.\n    <a href=\"{{ url_for('cash') }}\">افتح الوردية من هنا<\/a>\n  <\/div>\n  {% endif %}\n\n  <div class=\"scanbar\">\n    <div class=\"box\">\n      <input id=\"scan\" class=\"big\" placeholder=\"باركود الصنف أو اسمه…\" autocomplete=\"off\"\n             inputmode=\"text\" {% if not shift %}disabled{% endif %}>\n      <button class=\"btn p\" id=\"addFound\" style=\"min-width:74px\">إضافة<\/button>\n      <button class=\"btn ghost\" id=\"camBtn\" title=\"قراءة بالكاميرا\" style=\"min-width:58px\">📷<\/button>\n      <button class=\"btn ghost\" id=\"listBtn\" title=\"قائمة الأصناف\" style=\"min-width:58px\">📋<\/button>\n    <\/div>\n    <div id=\"suggest\" class=\"suggest hide\"><\/div>\n  <\/div>\n\n  <div class=\"card tight\">\n    <div class=\"row\">\n      <div class=\"h2 grow\">سلة البيع <span class=\"pill b\" id=\"cnt\">0<\/span><\/div>\n      <button class=\"btn sm ghost\" id=\"clearBtn\">تفريغ السلة<\/button>\n    <\/div>\n    <div id=\"cart\"><\/div>\n    <div id=\"emptyMsg\" class=\"center muted mt\">السلة فارغة — امسح باركود أو ابحث عن صنف<\/div>\n  <\/div>\n<\/div>\n\n<!-- شريط الدفع السفلي -->\n<div class=\"paybar no-print\">\n  <div class=\"paybar-in\">\n    <div class=\"totrow\">\n      <span class=\"muted\">الإجمالي<\/span>\n      <span class=\"grand grow\" id=\"totalView\">0 {{ S.currency }}<\/span>\n      <button class=\"btn sm ghost\" id=\"discBtn\">خصم<\/button>\n      <span class=\"pill a hide\" id=\"discPill\"><\/span>\n    <\/div>\n    <div class=\"actions\">\n      <button class=\"btn p lg pay-action\" data-pt=\"cash\" {% if not shift %}disabled{% endif %}>💵 بيع نقدي (F1)<\/button>\n      <button class=\"btn amber lg pay-action\" data-pt=\"credit\" {% if not shift %}disabled{% endif %}>📒 آجل (F2)<\/button>\n      <button class=\"btn ghost lg\" id=\"holdBtn\" title=\"تعليق الفاتورة\">⏸ تعليق<\/button>\n      <button class=\"btn ghost lg\" id=\"resumeBtn\" title=\"استرجاع معلَّقة\">▶ استرجاع<\/button>\n    <\/div>\n  <\/div>\n<\/div>\n\n<!-- نافذة الدفع النقدي -->\n<div class=\"modal\" id=\"cashModal\"><div class=\"sheet\">\n  <div class=\"h2\">💵 دفع نقدي<\/div>\n  <div class=\"center mt\">\n    <div class=\"muted small\">المطلوب<\/div>\n    <div class=\"amt h1\" id=\"cashDue\">0<\/div>\n  <\/div>\n  <label>المستلم من الزبون<\/label>\n  <input id=\"received\" class=\"big center\" inputmode=\"decimal\" value=\"\">\n  <div class=\"card tight mt\">\n    <div class=\"muted small\">جزء بحوالة أو محفظة أو إيداع (اختياري)، ويُخصم من المطلوب نقداً<\/div>\n    <div class=\"row\">\n      <select id=\"ncaMethod\"><option value=\"transfer\">حوالة<\/option><option value=\"wallet\">محفظة<\/option><option value=\"deposit\">إيداع<\/option><\/select>\n      <input id=\"ncaAmount\" inputmode=\"decimal\" placeholder=\"المبلغ\">\n    <\/div>\n    <input id=\"ncaRef\" placeholder=\"رقم المرجع (إلزامي عند المبلغ)\">\n  <\/div>\n\n  <div class=\"quick-amts\" id=\"quickAmts\"><\/div>\n  <div class=\"row mt\">\n    <div class=\"card tight grow center\"><div class=\"muted small\">الباقي للزبون<\/div>\n      <div class=\"h1\" id=\"changeView\">0<\/div><\/div>\n  <\/div>\n  <div class=\"num-pad\">\n    {% for n in ['1','2','3','4','5','6','7','8','9','.','0','⌫'] %}\n      <button type=\"button\" class=\"btn\" data-nk=\"{{ n }}\">{{ n }}<\/button>\n    {% endfor %}\n  <\/div>\n  <div class=\"btn-grid mt\">\n    <button class=\"btn p lg\" id=\"cashConfirm\" style=\"grid-column:span 2\">تأكيد البيع ✔<\/button>\n    <button class=\"btn ghost lg\" onclick=\"closeModal('cashModal')\" style=\"grid-column:span 2\">رجوع<\/button>\n  <\/div>\n<\/div><\/div>\n\n<!-- نافذة الآجل -->\n<div class=\"modal\" id=\"creditModal\"><div class=\"sheet\">\n  <div class=\"h2\">📒 بيع آجل<\/div>\n  <label for=\"custSearch\">الزبون — الرمز السريع أو الاسم أو الهاتف<\/label>\n  <input id=\"custSearch\" placeholder=\"مثلاً #00042 ثم إدخال؛ أو اكتب الاسم/الهاتف\" autocomplete=\"off\" enterkeyhint=\"done\">\n  <div id=\"custResults\" class=\"suggest hide\"><\/div>\n  <div class=\"card tight mt row hide\" id=\"custChosen\">\n    <div class=\"grow\"><b id=\"custName\"><\/b> <b id=\"custCode\" dir=\"ltr\"><\/b><div class=\"muted small\" id=\"custBal\"><\/div><\/div>\n    <button type=\"button\" class=\"btn sm ghost\" onclick=\"clearCreditCustomer()\">تغيير<\/button>\n  <\/div>\n  <button class=\"btn ghost wide mt\" onclick=\"showNewCust()\">➕ زبون جديد<\/button>\n  <div id=\"newCustBox\" class=\"hide\">\n    <label>اسم الزبون الجديد<\/label>\n    <input id=\"newCustName\" placeholder=\"الاسم الكامل\">\n    <label>الهاتف (اختياري — للواتساب)<\/label>\n    <input id=\"newCustPhone\" inputmode=\"tel\">\n    <button type=\"button\" class=\"btn blue wide mt\" id=\"newCustSave\" onclick=\"createCust()\">أضف الزبون<\/button>\n  <\/div>\n  <label>دفعة مقدَّمة الآن نقداً (اختياري)<\/label>\n  <input id=\"creditPaid\" inputmode=\"decimal\" placeholder=\"0\">\n  <div class=\"card tight mt\">\n    <div class=\"muted small\">جزء بحوالة أو محفظة أو إيداع (اختياري)، ويُخصم من المطلوب نقداً<\/div>\n    <div class=\"row\">\n      <select id=\"ncbMethod\"><option value=\"transfer\">حوالة<\/option><option value=\"wallet\">محفظة<\/option><option value=\"deposit\">إيداع<\/option><\/select>\n      <input id=\"ncbAmount\" inputmode=\"decimal\" placeholder=\"المبلغ\">\n    <\/div>\n    <input id=\"ncbRef\" placeholder=\"رقم المرجع (إلزامي عند المبلغ)\">\n  <\/div>\n\n  <div class=\"card tight mt center\">\n    <div class=\"muted small\">المتبقي على الزبون (دين)<\/div>\n    <div class=\"h1\" id=\"creditDueView\">0<\/div>\n  <\/div>\n  <div class=\"btn-grid mt\">\n    <button class=\"btn amber lg\" id=\"creditConfirm\" style=\"grid-column:span 2\">تأكيد الآجل ✔<\/button>\n    <button class=\"btn ghost lg\" onclick=\"closeModal('creditModal')\" style=\"grid-column:span 2\">رجوع<\/button>\n  <\/div>\n<\/div><\/div>\n\n<!-- نافذة الخصم -->\n<div class=\"modal\" id=\"discModal\"><div class=\"sheet\">\n  <div class=\"h2\">خصم على الفاتورة<\/div>\n  <label>قيمة الخصم<\/label>\n  <input id=\"discInput\" class=\"big\" inputmode=\"decimal\" placeholder=\"0\">\n  <div class=\"btn-grid mt\">\n    <button class=\"btn p\" id=\"discApply\">تطبيق<\/button>\n    <button class=\"btn ghost\" onclick=\"closeModal('discModal')\">إلغاء<\/button>\n  <\/div>\n<\/div><\/div>\n\n<!-- نافذة النجاح -->\n<div class=\"modal\" id=\"doneModal\"><div class=\"sheet\">\n  <div class=\"bigmsg\">\n    <div class=\"ok-ic\">✅<\/div>\n    <div class=\"h1\">تم حفظ الفاتورة<\/div>\n    <div class=\"muted\" id=\"doneInfo\"><\/div>\n    <div class=\"amt\" id=\"doneChange\"><\/div>\n    <div class=\"muted small mt\" id=\"doneHint\"><\/div>\n  <\/div>\n  <div class=\"btn-grid\">\n    <a class=\"btn p lg\" id=\"printLink\" target=\"_blank\" style=\"grid-column:span 2\">🖨 طباعة الفاتورة<\/a>\n    <a class=\"btn ghost lg\" id=\"invoiceViewLink\" style=\"grid-column:span 2\">📄 عرض الفاتورة<\/a>\n    <button class=\"btn blue lg\" onclick=\"closeModal('doneModal')\" style=\"grid-column:span 2\">فاتورة جديدة (Esc)<\/button>\n  <\/div>\n<\/div><\/div>\n\n<!-- عدة أوجه بيع بالباركود نفسه: لا يُضاف أي وجه قبل اختيار البائع -->\n<div class=\"modal\" id=\"variantModal\"><div class=\"sheet\">\n  <div class=\"h2\">اختر الوجه والسعر لهذا الباركود<\/div>\n  <label for=\"variantChoice\">الصنف المطلوب<\/label>\n  <select id=\"variantChoice\" class=\"big\"><\/select>\n  <div class=\"muted small mt\">الرصيد المعروض يتبع إعداد كل وجه: مستقل أو مشترك. يُحسب السعر من الوجه المختار فقط.<\/div>\n  <div class=\"btn-grid mt\">\n    <button class=\"btn p\" id=\"variantConfirm\" type=\"button\">إضافة الوجه المختار<\/button>\n    <button class=\"btn ghost\" type=\"button\" onclick=\"closeModal('variantModal')\">إلغاء<\/button>\n  <\/div>\n<\/div><\/div>\n\n<!-- نافذة قائمة الأصناف -->\n<div class=\"modal\" id=\"listModal\"><div class=\"sheet\">\n  <div class=\"h2\">📋 الأصناف<\/div>\n  <input id=\"listSearch\" placeholder=\"ابحث بالاسم أو الباركود…\" autocomplete=\"off\">\n  <div id=\"listResults\" class=\"mt\"><\/div>\n  <button class=\"btn ghost wide mt\" onclick=\"closeModal('listModal')\">إغلاق<\/button>\n<\/div><\/div>\n\n<!-- نافذة الكاميرا -->\n<div class=\"modal\" id=\"camModal\"><div class=\"sheet\">\n  <div class=\"h2\">📷 قراءة الباركود بالكاميرا<\/div>\n  <div class=\"muted small\">وجّه الكاميرا نحو الباركود…<\/div>\n  <video id=\"camVideo\" style=\"width:100%;border-radius:12px;margin-top:8px;background:#000\" playsinline muted><\/video>\n  <div class=\"muted small mt\" id=\"camNote\"><\/div>\n  <button class=\"btn ghost wide mt\" id=\"camStop\">إغلاق الكاميرا<\/button>\n<\/div><\/div>\n\n{% endif %}\n{% endblock %}\n\n{% block scripts %}\n{% if not cloud_shift_only %}\n<script>\nlet cart = [];            // {id, name, unit, price_cents, qty, stock}\nlet discount = 0;\nlet chosenCustomer = null;\nlet heldCart = null;\nlet lastInvoice = null;\nconst currency = \"{{ S.currency }}\";\n\n/* ================= السلة ================= */\nfunction renderCart(){\n  const box = document.getElementById('cart');\n  box.innerHTML = '';\n  document.getElementById('emptyMsg').classList.toggle('hide', cart.length>0);\n  let total = 0;\n  cart.forEach((l, i)=>{\n    const lineTot = Math.round(l.price_cents * l.qty);\n    total += lineTot;\n    const d = document.createElement('div');\n    d.className = 'cart-line';\n    d.innerHTML = `\n      <div class=\"nm\">${l.name}<small>${l.loc? '<span class=\"loc-chip\">📍 '+l.loc+'<\/span> ':''}${money(l.price_cents)} × ${l.unit||''} ${l.stock<=l.qty? '• <span style=\"color:#b45309\">رصيد: '+l.stock+'<\/span>':''}<\/small><\/div>\n      <div class=\"qtybtns\">\n        <button class=\"qbtn\" data-i=\"${i}\" data-d=\"-1\">−<\/button>\n        <input class=\"qtyin\" data-i=\"${i}\" value=\"${l.qty}\" inputmode=\"decimal\">\n        <button class=\"qbtn plus\" data-i=\"${i}\" data-d=\"1\">+<\/button>\n      <\/div>\n      <div class=\"line-tot\">${money(lineTot)}<\/div>\n      <button class=\"del\" data-i=\"${i}\">✕<\/button>`;\n    box.appendChild(d);\n  });\n  document.getElementById('cnt').textContent = cart.length;\n  const grand = Math.max(0, total - discount);\n  document.getElementById('totalView').textContent = money(grand);\n  const dp = document.getElementById('discPill');\n  dp.classList.toggle('hide', discount<=0);\n  dp.textContent = 'خصم ' + money(discount);\n  return grand;\n}\nfunction cartTotal(){ return cart.reduce((s,l)=>s+Math.round(l.price_cents*l.qty),0); }\n\ndocument.getElementById('cart').addEventListener('click', e=>{\n  const q = e.target.closest('.qbtn');\n  if(q){\n    const i = +q.dataset.i, d = +q.dataset.d;\n    cart[i].qty = Math.max(1, round3(cart[i].qty + d));\n    renderCart(); return;\n  }\n  const del = e.target.closest('.del');\n  if(del){ cart.splice(+del.dataset.i,1); renderCart(); }\n});\ndocument.getElementById('cart').addEventListener('change', e=>{\n  if(e.target.classList.contains('qtyin')){\n    const i = +e.target.dataset.i;\n    const v = parseFloat(e.target.value.replace(',','.'));\n    cart[i].qty = (v>0)? round3(v) : 1;\n    renderCart();\n  }\n});\nfunction round3(n){ return Math.round(n*1000)/1000; }\n\nfunction addToCart(p, count=1){\n  const ex = cart.find(l=>l.id===p.id);\n  if(ex){ ex.qty = round3(ex.qty+count); }\n  else{ cart.push({id:p.id, name:p.name, unit:p.unit, price_cents:p.price_cents, qty:count, stock:p.stock, loc:p.loc||''}); }\n  beep(); vib();\n  renderCart();\n}\nfunction clearCart(){ cart=[]; discount=0; renderCart(); }\ndocument.getElementById('clearBtn').onclick = ()=>{ if(cart.length && confirm('تفريغ السلة؟')) clearCart(); };\n\n/* ================= البحث والمسح ================= */\nconst scan = document.getElementById('scan');\nscan.addEventListener('keydown', e=>{ if(e.key==='Enter'){ e.preventDefault(); lookup(scan.value); } });\nscan.addEventListener('input', ()=>{ if(scan.value.length>=2) suggest(scan.value); else hideSuggest(); });\ndocument.getElementById('addFound').onclick = ()=>lookup(scan.value);\n\nlet barcodeChoices = [];\nfunction chooseBarcodeVariant(choices){\n  barcodeChoices = choices;\n  const s = document.getElementById('variantChoice');\n  s.innerHTML = '';\n  const prompt = document.createElement('option');\n  prompt.value = ''; prompt.textContent = 'اختر النوع قبل إضافته…';\n  s.appendChild(prompt);\n  choices.forEach(p=>{\n    const opt = document.createElement('option');\n    opt.value = String(p.id);\n    opt.textContent = p.name + ' — ' + money(p.price_cents) + ' — رصيد ' + p.stock;\n    s.appendChild(opt);\n  });\n  s.value = '';\n  scan.value = '';\n  openModal('variantModal');\n  s.focus();\n}\ndocument.getElementById('variantConfirm').onclick = ()=>{\n  const id = Number(document.getElementById('variantChoice').value);\n  const choice = barcodeChoices.find(p=>p.id === id);\n  if (!choice){ beep(false); toast('اختر وجه البيع أولاً', 'err'); return; }\n  addToCart(choice);\n  barcodeChoices = [];\n  closeModal('variantModal');\n  scan.focus();\n};\nasync function lookup(code){\n  code = (code||'').trim(); if(!code) return;\n  const j = await api('/api/find', {code});\n  hideSuggest();\n  if(j.ok && j.choices && j.choices.length > 1){ chooseBarcodeVariant(j.choices); }\n  else if(j.ok && j.product){ addToCart(j.product); scan.value=''; scan.focus(); }\n  else if(j.suggestions && j.suggestions.length){ showSuggest(j.suggestions); }\n  else { beep(false); toast(j.error||'لم يُعثر على الصنف','err'); }\n}\nlet sugTimer;\nfunction suggest(q){\n  clearTimeout(sugTimer);\n  sugTimer = setTimeout(async ()=>{\n    const j = await api('/api/search?q='+encodeURIComponent(q));\n    if(j.ok && j.products.length) showSuggest(j.products); else hideSuggest();\n  }, 220);\n}\nfunction showSuggest(list){\n  const s = document.getElementById('suggest');\n  s.innerHTML = '';\n  list.forEach(p=>{\n    const b = document.createElement('button');\n    b.innerHTML = `<b>${p.name}<\/b> <span class=\"pr\">— ${money(p.price_cents)} • رصيد ${p.stock} ${p.barcode? '• '+p.barcode : ''}<\/span>`;\n    b.onclick = ()=>{ addToCart(p); scan.value=''; hideSuggest(); scan.focus(); };\n    s.appendChild(b);\n  });\n  s.classList.remove('hide');\n}\nfunction hideSuggest(){ document.getElementById('suggest').classList.add('hide'); }\n\n/* قارئ الباركود يعمل في أي مكان بالشاشة */\nwatchScanner(code=>{ if(!document.querySelector('.modal.open')) lookup(code); });\n\n/* ================= الدفع ================= */\ndocument.querySelectorAll('.pay-action').forEach(b=>{\n  b.onclick = ()=>{\n    if(!cart.length){ beep(false); toast('السلة فارغة','err'); return; }\n    if(b.dataset.pt==='cash') openCash(); else openCredit();\n  };\n});\n\nfunction openCash(){\n  const total = Math.max(0, cartTotal()-discount);\n  document.getElementById('cashDue').textContent = money(total);\n  document.getElementById('received').value = '';\n  updChange();\n  const quick = document.getElementById('quickAmts');\n  quick.innerHTML = '';\n  // أزرار سريعة: المبلغ بالضبط + أقرب فئات\n  const vals = [total, Math.ceil(total/1000)*1000, Math.ceil(total/5000)*5000, Math.ceil(total/10000)*10000];\n  [...new Set(vals)].slice(0,4).forEach(v=>{\n    const b = document.createElement('button');\n    b.className = 'btn'; b.textContent = money(v);\n    b.onclick = ()=>{ document.getElementById('received').value = String(Math.round(v/100)); updChange(); };\n    quick.appendChild(b);\n  });\n  openModal('cashModal');\n}\n/* الأجزاء غير النقدية (حوالة/محفظة/إيداع) لنافذة معيّنة: البادئة nca للنقد، ncb للآجل */\nfunction nonCashParts(p){\n  const amt = cents(document.getElementById(p+'Amount').value);\n  if(!amt) return [];\n  return [{method: document.getElementById(p+'Method').value, amount_cents: amt,\n           reference: document.getElementById(p+'Ref').value.trim()}];\n}\nfunction nonCashSum(p){ return nonCashParts(p).reduce((a,x)=>a+x.amount_cents, 0); }\nfunction updChange(){\n  const total = Math.max(0, cartTotal()-discount-nonCashSum('nca'));\n  document.getElementById('cashDue').textContent = money(total);\n  const rec = cents(document.getElementById('received').value);\n  const ch = rec-total;\n  const el = document.getElementById('changeView');\n  el.textContent = money(Math.max(0,ch));\n  el.style.color = (rec>0 && ch<0)? '#b91c1c' : '';\n}\ndocument.getElementById('received').addEventListener('input', updChange);\n['ncaAmount','ncaMethod','ncaRef'].forEach(id=>document.getElementById(id).addEventListener('input', updChange));\ndocument.querySelector('#cashModal .num-pad').addEventListener('click', e=>{\n  const b = e.target.closest('[data-nk]'); if(!b) return;\n  const inp = document.getElementById('received');\n  const k = b.dataset.nk;\n  if(k==='⌫') inp.value = inp.value.slice(0,-1);\n  else if(k==='.' && inp.value.includes('.')) {}\n  else inp.value += k;\n  updChange();\n});\ndocument.getElementById('cashConfirm').onclick = async ()=>{\n  const total = Math.max(0, cartTotal()-discount);\n  const nc = nonCashParts('nca');\n  const cashDue = Math.max(0, total - nonCashSum('nca'));\n  const rec = cents(document.getElementById('received').value) || cashDue;\n  if(nonCashSum('nca') > total){ beep(false); toast('مجموع الحوالة والمحفظة أكبر من الإجمالي','err'); return; }\n  if(rec < cashDue){ beep(false); toast('المستلم نقداً أقل من المطلوب','err'); return; }\n  await submitSale({payment_type:'cash', received_cents: rec, discount_cents: discount, non_cash: nc});\n};\n\nfunction openCredit(){\n  clearTimeout(custTimer);\n  custQuerySeq++;\n  chosenCustomer = null;\n  document.getElementById('custChosen').classList.add('hide');\n  document.getElementById('custResults').classList.add('hide');\n  document.getElementById('custSearch').value = '';\n  document.getElementById('creditPaid').value = '';\n  document.getElementById('newCustBox').classList.add('hide');\n  updCreditDue();\n  openModal('creditModal');\n  document.getElementById('custSearch').focus();\n}\nfunction updCreditDue(){\n  const total = Math.max(0, cartTotal()-discount);\n  const paid = Math.min(cents(document.getElementById('creditPaid').value) + nonCashSum('ncb'), total);\n  document.getElementById('creditDueView').textContent = money(total-paid);\n}\ndocument.getElementById('creditPaid').addEventListener('input', updCreditDue);\n['ncbAmount','ncbMethod','ncbRef'].forEach(id=>document.getElementById(id).addEventListener('input', updCreditDue));\n\nlet custTimer, custQuerySeq = 0;\nfunction selectCreditCustomer(c){\n  chosenCustomer = c;\n  document.getElementById('custChosen').classList.remove('hide');\n  document.getElementById('custName').textContent = c.name;\n  document.getElementById('custCode').textContent = c.code;\n  document.getElementById('custBal').textContent = 'الرصيد الحالي: ' + money(c.balance_cents);\n  document.getElementById('custSearch').value = c.code;\n  document.getElementById('custResults').classList.add('hide');\n}\nfunction clearCreditCustomer(){\n  clearTimeout(custTimer); custQuerySeq++;\n  chosenCustomer = null;\n  document.getElementById('custChosen').classList.add('hide');\n  document.getElementById('custResults').classList.add('hide');\n  const input = document.getElementById('custSearch');\n  input.value = ''; input.focus();\n}\nasync function searchCreditCustomer(q, seq, selectExact){\n  if(!q){ document.getElementById('custResults').classList.add('hide'); return; }\n  const j = await api('/api/customers?q='+encodeURIComponent(q));\n  if(seq !== custQuerySeq || document.getElementById('custSearch').value.trim() !== q) return;\n  const box = document.getElementById('custResults');\n  box.innerHTML = '';\n  if(!j.ok || !j.customers.length){\n    box.classList.add('hide');\n    if(selectExact) toast('رمز الزبون غير موجود؛ تحقّق منه', 'err');\n    return;\n  }\n  if(selectExact && q.startsWith('#') && j.customers.length===1){ selectCreditCustomer(j.customers[0]); return; }\n  j.customers.forEach(c=>{\n    const b = document.createElement('button');\n    b.type = 'button';\n    const label = document.createElement('b'); label.textContent = c.name + ' · ';\n    const code = document.createElement('bdi'); code.dir='ltr'; code.textContent = c.code;\n    label.appendChild(code);\n    const detail = document.createElement('span'); detail.className = 'pr';\n    detail.textContent = ' — الرصيد الحالي ' + money(c.balance_cents) + (c.phone? ' • '+c.phone : '');\n    b.append(label, detail);\n    b.onclick = ()=>selectCreditCustomer(c);\n    box.appendChild(b);\n  });\n  box.classList.remove('hide');\n}\ndocument.getElementById('custSearch').addEventListener('input', e=>{\n  clearTimeout(custTimer);\n  // لا تسمح ببقاء الزبون القديم محدداً بعد تعديل رمز البحث.\n  chosenCustomer = null;\n  document.getElementById('custChosen').classList.add('hide');\n  const q = e.target.value.trim();\n  const seq = ++custQuerySeq;\n  custTimer = setTimeout(()=>searchCreditCustomer(q, seq, false), q.startsWith('#')? 0 : 200);\n});\ndocument.getElementById('custSearch').addEventListener('keydown', e=>{\n  if(e.key !== 'Enter') return;\n  e.preventDefault();\n  clearTimeout(custTimer);\n  const q = e.target.value.trim();\n  if(q.startsWith('#')) searchCreditCustomer(q, ++custQuerySeq, true);\n  else searchCreditCustomer(q, ++custQuerySeq, false);\n});\nfunction showNewCust(){ document.getElementById('newCustBox').classList.toggle('hide'); }\nasync function createCust(){\n  const name = document.getElementById('newCustName').value.trim();\n  if(!name){ toast('اكتب اسم الزبون','err'); return; }\n  const phone = document.getElementById('newCustPhone').value.trim();\n  const btn = document.getElementById('newCustSave');\n  if(btn.disabled) return;\n  btn.disabled = true;\n  try {\n    const j = await api('/api/customers', {name, phone});\n    if(!j.ok || !j.customer){ toast(j.error||'تعذّرت إضافة الزبون','err'); return; }\n    clearTimeout(custTimer); custQuerySeq++;\n    selectCreditCustomer(j.customer); // الهوية الدقيقة للزبون المُنشأ، لا أول نتيجة تحمل اسمه.\n    document.getElementById('newCustBox').classList.add('hide');\n    toast('تمت إضافة الزبون واختياره: '+j.customer.code, 'ok');\n  } catch(e) { toast('تعذّر الاتصال؛ أعد المحاولة بعد التحقق', 'err'); }\n  finally { btn.disabled = false; }\n}\ndocument.getElementById('creditConfirm').onclick = async ()=>{\n  if(!chosenCustomer){ beep(false); toast('اختر الزبون أولاً','err'); return; }\n  const total = Math.max(0, cartTotal()-discount);\n  const nc = nonCashParts('ncb');\n  const paid = Math.min(cents(document.getElementById('creditPaid').value), Math.max(0, total - nonCashSum('ncb')));\n  await submitSale({payment_type:'credit', customer_id: chosenCustomer.id,\n                    paid_cents: paid, discount_cents: discount, non_cash: nc});\n};\n\n/* ================= إغلاق نافذة النجاح (قرار المستشار) =================\n   العامل في الزحمة لا يجب أن يُلزم بضغطة إضافية بعد كل فاتورة — لكنه أيضاً\n   يحتاج ثوانيَ للطباعة أو عرض الفاتورة. الحل: عدّ تنازلي 6 ثوانٍ تُغلق النافذة\n   تلقائياً وتعيد المؤشر لحقل الباركود (البيعة التالية بلا أي لمسة)،\n   وأي لمسة داخل النافذة تُلغي العدّ فتبقى مفتوحةً حتى يفرغ العامل. */\nlet doneTimer = null, doneLeft = 0;\nfunction startDoneCountdown(){\n  stopDoneCountdown();\n  doneLeft = 6;\n  paintDoneHint();\n  doneTimer = setInterval(()=>{\n    doneLeft--;\n    if(doneLeft <= 0){\n      stopDoneCountdown();\n      closeModal('doneModal');\n      const s = document.getElementById('scan'); if(s) s.focus();\n    } else { paintDoneHint(); }\n  }, 1000);\n}\nfunction paintDoneHint(){\n  const h = document.getElementById('doneHint');\n  if(h) h.textContent = 'تُغلق تلقائياً بعد ' + doneLeft + ' ثوانٍ — أو المس أي زر لتبقى';\n}\nfunction stopDoneCountdown(){\n  if(doneTimer){ clearInterval(doneTimer); doneTimer = null; }\n  const h = document.getElementById('doneHint');\n  if(h) h.textContent = '';\n}\ndocument.getElementById('doneModal').addEventListener('pointerdown', stopDoneCountdown);\n\n/* ================= إرسال البيع ================= */\nlet saleSubmitting = false;\nasync function submitSale(extra){\n  if(saleSubmitting) return; // نقرتان أو أمر صوتي أثناء الرد لا ينشئان فاتورتين.\n  if(!cart.length){ toast('السلة فارغة؛ لا توجد فاتورة للحفظ','err'); return; }\n  saleSubmitting = true;\n  const confirmButtons = ['cashConfirm','creditConfirm'].map(id=>document.getElementById(id));\n  confirmButtons.forEach(b=>{ if(b) b.disabled=true; });\n  try {\n    const body = Object.assign({items:cart.map(l=>({product_id:l.id,qty:l.qty}))}, extra);\n    const j = await api('/api/sale', body);\n    if(!j.ok){ beep(false); toast(j.error||'تعذّر حفظ الفاتورة','err'); return; }\n    beep(); vib(80);\n    lastInvoice = j;\n    closeModal('cashModal');\n    closeModal('creditModal');\n    document.getElementById('doneInfo').textContent = 'فاتورة رقم ' + j.number + ' — الإجمالي ' + j.total + ' ' + currency;\n    const ch = document.getElementById('doneChange');\n    if(j.change && cents(j.change)>0){ ch.textContent = 'الباقي للزبون: ' + j.change; ch.style.display=''; }\n    else { ch.textContent=''; }\n    document.getElementById('printLink').href = '/invoice/'+j.invoice_id+'?print=1';\n    document.getElementById('invoiceViewLink').href = '/invoice/'+j.invoice_id;\n    openModal('doneModal');\n    startDoneCountdown();\n    clearCart();\n    scan.focus();\n  } catch(e) {\n    beep(false); toast('تعذّر حفظ الفاتورة؛ لا تضغط تأكيداً ثانياً قبل مراجعة النتيجة','err');\n  } finally {\n    saleSubmitting = false;\n    confirmButtons.forEach(b=>{ if(b) b.disabled=false; });\n  }\n}\n\n/* ================= تعليق واسترجاع ================= */\ndocument.getElementById('holdBtn').onclick = ()=>{\n  if(!cart.length){ toast('السلة فارغة','err'); return; }\n  heldCart = {lines: JSON.parse(JSON.stringify(cart)), discount};\n  clearCart();\n  toast('تم تعليق الفاتورة — استرجعها بزر ▶','ok');\n};\ndocument.getElementById('resumeBtn').onclick = ()=>{\n  if(!heldCart){ toast('لا توجد فاتورة معلَّقة','err'); return; }\n  cart = heldCart.lines; discount = heldCart.discount; heldCart = null;\n  renderCart(); toast('تم استرجاع الفاتورة','ok');\n};\n\n/* ================= الخصم ================= */\ndocument.getElementById('discBtn').onclick = ()=>{\n  document.getElementById('discInput').value = String(Math.round(discount/100));\n  openModal('discModal');\n};\ndocument.getElementById('discApply').onclick = ()=>{\n  let v = cents(document.getElementById('discInput').value);\n  if(v > cartTotal()) v = cartTotal();\n  discount = Math.max(0, v);\n  renderCart(); closeModal('discModal');\n};\n\n/* ================= قائمة الأصناف ================= */\ndocument.getElementById('listBtn').onclick = ()=>{\n  openModal('listModal');\n  document.getElementById('listSearch').value='';\n  document.getElementById('listSearch').focus();\n  searchList('');\n};\ndocument.getElementById('listSearch').addEventListener('input', e=>{ searchList(e.target.value); });\nasync function searchList(q){\n  const j = await api('/api/search?q='+encodeURIComponent(q||''));\n  const box = document.getElementById('listResults');\n  if(!j.ok || !j.products.length){ box.innerHTML = '<div class=\"muted center mt\">لا نتائج — اكتب حرفين على الأقل<\/div>'; return; }\n  box.innerHTML = '';\n  j.products.forEach(p=>{\n    const b = document.createElement('button');\n    b.className='user-btn';\n    const loc = p.loc ? `<span class=\"loc-chip\">📍 ${p.loc}<\/span> ` : '';\n    b.innerHTML = `<span class=\"grow\"><b>${p.name}<\/b><div class=\"muted small\">${loc}${money(p.price_cents)} • رصيد ${p.stock} ${p.barcode?'• '+p.barcode:''}<\/div><\/span>`;\n    b.onclick = ()=>{ addToCart(p); closeModal('listModal'); };\n    box.appendChild(b);\n  });\n}\n\n/* ================= الكاميرا ================= */\ndocument.getElementById('camBtn').onclick = ()=> openCameraScanner(code=>{ lookup(code); });\n\n/* ================= اختصارات لوحة المفاتيح ================= */\ndocument.addEventListener('keydown', e=>{\n  if(e.key==='F1'){ e.preventDefault(); if(cart.length) openCash(); }\n  if(e.key==='F2'){ e.preventDefault(); if(cart.length) openCredit(); }\n  if(e.key==='Escape'){\n    document.querySelectorAll('.modal.open').forEach(m=>m.classList.remove('open'));\n    scan.focus();\n  }\n});\n\n/* جسر الأوامر الصوتية إلى مسودة البيع فقط؛ حفظ الفاتورة يبقى في أزرار تأكيد الدفع أعلاه. */\nwindow.rafiqVoicePos = {\n  async findProducts(q){\n    if(scan.disabled) throw new Error('الصندوق مغلق؛ افتح الوردية يدوياً قبل البيع.');\n    const j = await api('/api/search?q='+encodeURIComponent(q));\n    if(!j.ok) throw new Error(j.error||'تعذّر البحث عن الصنف');\n    return j.products||[];\n  },\n  quote(){\n    if(scan.disabled) throw new Error('الصندوق مغلق؛ افتح الوردية أولاً.');\n    if(!cart.length) throw new Error('السلة فارغة؛ أضف صنفاً قبل البيع.');\n    return {lines: cart.map(l=>l.name+' × '+l.qty), totalCents: Math.max(0,cartTotal()-discount),\n            discountCents: discount};\n  },\n  async addProduct(p, count){\n    if(scan.disabled || !p || !Number.isInteger(count) || count<1 || count>100){\n      toast('تحقّق من الوردية والصنف والعدد', 'err'); return false;\n    }\n    // نعيد فحص الهوية والسعر والمخزون قبل تعديل المسودة؛ لا نعتمد نتيجة تعرّف قديمة.\n    let current;\n    try {\n      const options = await this.findProducts(p.barcode||p.name);\n      current = options.find(row=>row.id===p.id && row.name===p.name && row.price_cents===p.price_cents);\n    } catch(e) { toast('تعذّر فحص الصنف من جديد', 'err'); return false; }\n    if(!current){ toast('تغيّر الصنف أو سعره؛ أعد الأمر بعد المراجعة', 'err'); return false; }\n    const already = cart.find(l=>l.id===p.id);\n    if(!Number.isFinite(Number(current.stock)) || Number(current.stock) < count+(already?already.qty:0)){\n      toast('الكمية المطلوبة تتجاوز الرصيد الحالي؛ لا تُضف إلى السلة', 'err'); return false;\n    }\n    addToCart(current, count); scan.focus(); return true;\n  },\n  checkout(kind, customerQuery){\n    try { this.quote(); } catch(e) { toast(e.message, 'err'); return false; }\n    if(kind==='cash') { openCash(); return true; }\n    if(kind!=='credit') return false;\n    openCredit();\n    if(customerQuery){\n      const input = document.getElementById('custSearch');\n      input.value = customerQuery;\n      const seq = ++custQuerySeq;\n      searchCreditCustomer(customerQuery, seq, customerQuery.startsWith('#'))\n        .catch(()=>toast('تعذّر البحث عن الزبون؛ اختره يدوياً', 'err'));\n    }\n    return true; // اختيار الزبون وتأكيد البيع الآجل لا يتمّان إلا بلمس المستخدم.\n  },\n  lastInvoiceId(){ return lastInvoice ? Number(lastInvoice.invoice_id) : null; }\n};\n\nrenderCart();\nsetTimeout(()=>scan.focus(), 300);\n<\/script>\n{% endif %}\n{% endblock %}\n", "product_form.html": "{% extends \"base.html\" %}\n{% block title %}{{ 'تعديل صنف' if p else 'صنف جديد' }}{% endblock %}\n{% block content %}\n<div class=\"row product-head\">\n  <div class=\"h1 grow\">{{ 'تعديل صنف' if p else 'صنف جديد' }}<\/div>\n  <a class=\"btn sm ghost\" href=\"{{ url_for('products') }}\">← القائمة<\/a>\n<\/div>\n\n<div class=\"card mt product-card\">\n  <form method=\"post\" class=\"product-form\">\n    <div class=\"product-fields\">\n      <div class=\"field wide\">\n        <label for=\"productName\">اسم الصنف *<\/label>\n        <input id=\"productName\" name=\"name\" required value=\"{{ p.name if p else '' }}\">\n      <\/div>\n      <div class=\"field wide\">\n        <label for=\"bc\">الباركود (بالكاميرا أو القارئ أو الكتابة)<\/label>\n        <div class=\"scan-field\">\n          <input name=\"barcode\" id=\"bc\" value=\"{{ p.barcode if p and p.barcode else '' }}\" autocomplete=\"off\" inputmode=\"numeric\">\n          <button type=\"button\" class=\"btn blue\" id=\"bcCam\">📷 تصوير<\/button>\n        <\/div>\n      <\/div>\n      <div class=\"field wide\">\n        <label for=\"sharedRoot\">رصيد هذا الوجه عند تكرار الباركود<\/label>\n        <select id=\"sharedRoot\" name=\"shared_stock_with\" data-current=\"{{ p.shared_stock_with if p and p.shared_stock_with else '' }}\">\n          <option value=\"\">رصيد مستقل لهذا الوجه (مثل أنواع البن المختلفة)<\/option>\n          {% for r in share_choices %}\n            <option value=\"{{ r.id }}\" {% if p and p.shared_stock_with == r.id %}selected{% endif %}>رصيد مشترك مع «{{ r.name }}» (المتاح {{ r.stock }})<\/option>\n          {% endfor %}\n        <\/select>\n        <div class=\"hint\">إذا كانت الأوجه تسحب من نفس الكمية الفعلية (مثل أسعار الماء من عبوة واحدة)، أدخل الباركود نفسه واختر الصنف الأساسي. أنشئ الصنف الأساسي أولاً. تُخصم الكمية من رصيده فقط، أما اسم هذا الوجه وسعره فمستقلان. تعديل باركود الصنف الأساسي يحدّث باركود أوجهه المشتركة معه معاً.<\/div>\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productUnit\">الوحدة<\/label>\n        <input id=\"productUnit\" name=\"unit\" value=\"{{ p.unit if p else 'حبة' }}\">\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productCategory\">التصنيف<\/label>\n        <input id=\"productCategory\" name=\"category\" value=\"{{ p.category if p else '' }}\">\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productCost\">سعر الشراء<\/label>\n        <input id=\"productCost\" name=\"cost\" inputmode=\"decimal\" value=\"{{ (p.cost_cents/100) if p else '' }}\">\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productPrice\">سعر البيع *<\/label>\n        <input id=\"productPrice\" name=\"price\" inputmode=\"decimal\" required value=\"{{ (p.price_cents/100) if p else '' }}\">\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productStock\">الرصيد الحالي<\/label>\n        <input id=\"productStock\" name=\"stock\" inputmode=\"decimal\" value=\"{{ ('%g'|format(p.stock)) if p else '0' }}\">\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productLow\">حد التنبيه (النواقص)<\/label>\n        <input id=\"productLow\" name=\"low_stock\" inputmode=\"decimal\" value=\"{{ ('%g'|format(p.low_stock)) if p else S.low_stock_default }}\">\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productAisle\">الممر (اختياري)<\/label>\n        <input id=\"productAisle\" name=\"aisle\" placeholder=\"مثال: 3\" value=\"{{ p.aisle if p else '' }}\">\n      <\/div>\n      <div class=\"field\">\n        <label for=\"productShelf\">الرف (اختياري)<\/label>\n        <input id=\"productShelf\" name=\"shelf\" placeholder=\"مثال: ب\" value=\"{{ p.shelf if p else '' }}\">\n      <\/div>\n      <div class=\"product-note muted\">اترك الممر والرف فارغين إن لم تحدد موقعاً — لا يعطّلان الحفظ.<\/div>\n      <div class=\"field wide\">\n        <label for=\"productExpiry\">تاريخ الانتهاء (اختياري — التنبيه على الصنف ذي الرصيد الفعلي)<\/label>\n        <input id=\"productExpiry\" name=\"expiry\" type=\"date\" value=\"{{ p.expiry if p and p.expiry else '' }}\">\n      <\/div>\n    <\/div>\n    <div class=\"btn-grid product-actions\">\n      <button type=\"submit\" class=\"btn p\">💾 حفظ<\/button>\n      <a class=\"btn ghost\" href=\"{{ url_for('products') }}\">إلغاء<\/a>\n    <\/div>\n  <\/form>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script>\nconst sharedSelect = document.getElementById('sharedRoot');\nconst savedShared = sharedSelect.dataset.current || '';\nlet pendingShared = savedShared;\nconst currentProductId = {{ p.id if p else 0 }};\nlet rootLookupSeq = 0;\nfunction stockInputs(){\n  const linked = !!sharedSelect.value;\n  ['productStock', 'productLow', 'productExpiry'].forEach(id => {\n    document.getElementById(id).disabled = linked;\n  });\n}\nsharedSelect.onchange = function(){\n  if (!this.value && this.dataset.wasLinked === 'yes') {\n    // لا تنسخ الرصيد المشترك بأكمله إلى الوجه عند فصله؛ اطلب من المالك إدخاله.\n    document.getElementById('productStock').value = '0';\n    document.getElementById('productExpiry').value = '';\n  }\n  this.dataset.wasLinked = this.value ? 'yes' : 'no';\n  stockInputs();\n};\nsharedSelect.dataset.wasLinked = savedShared ? 'yes' : 'no';\nstockInputs();\nasync function fillStockRoots(){\n  const code = document.getElementById('bc').value.trim();\n  const seq = ++rootLookupSeq;\n  const selected = sharedSelect.value || pendingShared;\n  pendingShared = '';\n  sharedSelect.innerHTML = '<option value=\"\">رصيد مستقل لهذا الوجه (مثل أنواع البن المختلفة)<\/option>';\n  if (!code) { stockInputs(); return; }\n  const j = await api('/api/find', {code});\n  if (seq !== rootLookupSeq || document.getElementById('bc').value.trim() !== code) return;\n  const options = (j.choices || (j.product ? [j.product] : []));\n  options.filter(p => p.barcode === code && p.id !== currentProductId && !p.shared_stock_with).forEach(p => {\n    const opt = document.createElement('option');\n    opt.value = String(p.id);\n    opt.textContent = 'رصيد مشترك مع «' + p.name + '» (المتاح ' + p.stock + ')';\n    sharedSelect.appendChild(opt);\n  });\n  sharedSelect.value = selected;\n  if (sharedSelect.value !== selected) sharedSelect.value = '';\n  stockInputs();\n}\ndocument.getElementById('bc').addEventListener('change', fillStockRoots);\ndocument.getElementById('bc').addEventListener('blur', fillStockRoots);\nfunction putBarcode(code){ const b=document.getElementById('bc'); b.value=code; fillStockRoots(); beep(); vib(); }\nwatchScanner(putBarcode);\ndocument.getElementById('bcCam').onclick = ()=> openCameraScanner(putBarcode);\nfillStockRoots();\n<\/script>\n{% endblock %}\n", "products.html": "{% extends \"base.html\" %}\n{% block title %}الأصناف{% endblock %}\n{% block content %}\n<div class=\"row\">\n  <div class=\"h1 grow\">الأصناف <span class=\"pill b\">{{ count }}<\/span><\/div>\n  {% if low %}<div class=\"pill a\">{{ low }} قارب على النفاد<\/div>{% endif %}\n<\/div>\n<div class=\"row wrap mt\" style=\"gap:8px\">\n  <a class=\"btn sm {{ 'amber' if expiry_alert else 'ghost' }}\" href=\"/products?expiry_alert=1\">⏳ صلاحية منتهية أو خلال {{ expiry_days }} يوماً: {{ expiry_total }}<\/a>\n  {% if expiry_alert %}<a class=\"btn sm ghost\" href=\"{{ url_for('products') }}\">عرض كل الأصناف<\/a>{% endif %}\n<\/div>\n<div class=\"hint mt\">لكل صنف تاريخ انتهاء واحد فقط. القائمة تعرض الأصناف ذات الرصيد المسجل الموجب، ولا تمثل الدفعات متعددة الصلاحية أو إشعارات نظام الهاتف.<\/div>\n\n<div class=\"card mt\">\n  <form method=\"get\" class=\"row\">\n    <input name=\"q\" value=\"{{ q }}\" placeholder=\"ابحث بالاسم أو الباركود…\" class=\"grow\">\n    <button class=\"btn p\">بحث<\/button>\n  <\/form>\n  <div class=\"btn-grid mt\">\n    <a class=\"btn p\" href=\"{{ url_for('product_new') }}\">➕ صنف جديد<\/a>\n    <a class=\"btn ghost\" href=\"{{ url_for('imports') }}\">⬆️ استيراد من ملف<\/a>\n  <\/div>\n<\/div>\n\n<!-- إضافة يدوية سريعة: صنف بلا مغادرة القائمة (يرجع إليها عند الخطأ أو النجاح) -->\n<div class=\"card mt\">\n  <div class=\"h2\">➕ إضافة صنف يدوياً<\/div>\n  <form method=\"post\" action=\"{{ url_for('product_new') }}\">\n    <input type=\"hidden\" name=\"back\" value=\"products\">\n    <label>اسم الصنف *<\/label>\n    <input name=\"name\" required placeholder=\"مثال: زيت عافية 1 لتر\">\n    <div class=\"row\">\n      <div class=\"grow\"><label>الباركود (اختياري)<\/label><input name=\"barcode\" autocomplete=\"off\"><\/div>\n      <div class=\"grow\"><label>سعر البيع *<\/label><input name=\"price\" inputmode=\"decimal\" required><\/div>\n    <\/div>\n    <div class=\"row\">\n      <div class=\"grow\"><label>الرصيد<\/label><input name=\"stock\" inputmode=\"decimal\" placeholder=\"0\"><\/div>\n      <div class=\"grow\"><label>الممر<\/label><input name=\"aisle\" placeholder=\"3\"><\/div>\n      <div class=\"grow\"><label>الرف<\/label><input name=\"shelf\" placeholder=\"ب\"><\/div>\n    <\/div>\n    <button class=\"btn p wide mt\">💾 إضافة الصنف<\/button>\n  <\/form>\n<\/div>\n\n<div class=\"card tight\">\n  <div class=\"scroll-x\">\n  <table class=\"tbl\">\n    <tr><th>الصنف<\/th><th>الباركود<\/th><th>السعر<\/th><th>الرصيد<\/th><th>الموقع<\/th><th>الانتهاء<\/th><th><\/th><\/tr>\n    {% for p in rows %}\n      <tr>\n        <td><b>{{ p.name }}<\/b><div class=\"muted small\">{{ p.unit }}{% if p.category %} • {{ p.category }}{% endif %}<\/div><\/td>\n        <td class=\"small\">{{ p.barcode or '—' }}<\/td>\n        <td>{{ p.price_cents|money }}<\/td>\n        <td>\n          {% if p.stock <= p.low_stock %}<span class=\"pill a\">{{ '%g'|format(p.stock) }} ⚠<\/span>\n          {% else %}{{ '%g'|format(p.stock) }}{% endif %}\n          {% if p.shared_stock_with %}<div class=\"muted small\">↔ رصيد مشترك<\/div>{% endif %}\n        <\/td>\n        <td class=\"small\">{% if loc_text(p) %}<span class=\"loc-chip\">📍 {{ loc_text(p) }}<\/span>{% else %}—{% endif %}<\/td>\n        <td class=\"small\">{{ p.expiry or '—' }}<\/td>\n        <td><a class=\"btn sm ghost\" href=\"{{ url_for('product_edit', pid=p.id) }}\">تعديل<\/a><\/td>\n      <\/tr>\n    {% endfor %}\n    {% if not rows %}<tr><td colspan=\"7\" class=\"center muted mt\">{{ 'لا توجد أصناف بهذه الصلاحية' if expiry_alert else 'لا أصناف — أضف يدوياً أو استورد من ملف «الأمين»' }}<\/td><\/tr>{% endif %}\n  <\/table>\n  <\/div>\n  {% if rows|length == 500 %}<div class=\"hint\">عُرضت أول 500 نتيجة — استخدم البحث للتضييق.<\/div>{% endif %}\n<\/div>\n{% endblock %}\n", "reports.html": "{% extends \"base.html\" %}\n{% block title %}تقارير اليوم{% endblock %}\n{% block content %}\n<div class=\"card no-print mt report-print\">\n  <div class=\"h2\">طباعة<\/div>\n  <form method=\"post\" action=\"/invoice/by-number\">\n    <label>فاتورة قديمة برقمها<\/label>\n    <div class=\"report-pick\"><input name=\"n\" inputmode=\"numeric\" placeholder=\"رقم الفاتورة\"><button class=\"btn p\" type=\"submit\">فتح للطباعة<\/button><\/div>\n  <\/form>\n  <form method=\"post\" action=\"/customers/print-pick\" class=\"mt\">\n    <label>كشف حساب زبون<\/label>\n    <div class=\"report-pick\"><select name=\"cid\">{% for c in accounts_customers %}<option value=\"{{ c.id }}\">{{ c.name }}<\/option>{% endfor %}<\/select><button class=\"btn p\" type=\"submit\">طباعة الكشف<\/button><\/div>\n  <\/form>\n  <form method=\"post\" action=\"/suppliers/print-pick\" class=\"mt\">\n    <label>كشف حساب مورد<\/label>\n    <div class=\"report-pick\"><select name=\"sid\">{% for x in accounts_suppliers %}<option value=\"{{ x.id }}\">{{ x.name }}<\/option>{% endfor %}<\/select><button class=\"btn p\" type=\"submit\">طباعة الكشف<\/button><\/div>\n  <\/form>\n<\/div>\n<div class=\"print-head\">\n  {% if S.store_logo %}<img src=\"{{ S.store_logo }}\" alt=\"\">{% endif %}\n  <div><div class=\"t\">{{ S.store_name or \"المتجر\" }}<\/div><div class=\"s\">{{ S.store_name }} • تقرير {{ d }}<\/div><\/div>\n<\/div>\n<div class=\"row\">\n  <div class=\"h1 grow\">تقارير اليوم<\/div>\n<\/div>\n\n<div class=\"card mt\">\n  <form method=\"get\" class=\"report-date-form\">\n    <input type=\"date\" name=\"date\" value=\"{{ d }}\" class=\"grow\">\n    <button class=\"btn p\">عرض<\/button>\n    <a class=\"btn ghost\" href=\"{{ url_for('reports') }}\">اليوم<\/a>\n  <\/form>\n  <a class=\"btn gold wide mt\" href=\"{{ url_for('cash_report', date=d) }}\">💵 تقرير درج النقود لهذا اليوم<\/a>\n<\/div>\n\n<div class=\"grid g4 mt\">\n  <div class=\"stat green\"><div class=\"lbl\">مبيعات {{ d }}<\/div><div class=\"val\">{{ summary.total|money }}<\/div>\n    <div class=\"sub\">{{ summary.count }} فاتورة ({{ summary.cancelled }} ملغاة)<\/div><\/div>\n  <div class=\"stat blue\"><div class=\"lbl\">صافي نقد البيع والتحصيل<\/div><div class=\"val\">{{ summary.paid|money }}<\/div>\n    <div class=\"sub\">يشمل تحصيل ديون {{ collections|money }} وخصم إلغاءات اليوم<\/div><\/div>\n  <div class=\"stat amber\"><div class=\"lbl\">آجل جديد اليوم<\/div><div class=\"val\">{{ summary.due|money }}<\/div>\n    <div class=\"sub\">إجمالي ديون الزبائن: {{ debts_total|money }}<\/div><\/div>\n  <div class=\"stat red\"><div class=\"lbl\">مصروفات + سحب<\/div>\n    <div class=\"val\">{{ (expenses + withdraws)|money }}<\/div>\n    <div class=\"sub\">مصروف {{ expenses|money }} • سحب {{ withdraws|money }}<\/div><\/div>\n  <div class=\"stat amber\"><div class=\"lbl\">سداد الموردين والمناديب اليوم<\/div>\n    <div class=\"val\">{{ sup_pays_today|money }}<\/div>\n    <div class=\"sub\">علينا لهم إجمالاً: {{ sup_debt_total|money }}<\/div><\/div>\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"h2\">أداء العاملين اليوم<\/div>\n  <div class=\"scroll-x\">\n  <table class=\"tbl\">\n    <tr><th>العامل<\/th><th>عدد الفواتير<\/th><th>إجمالي البيع<\/th><th>المدفوع (كل الوسائل)<\/th><th>الآجل<\/th><\/tr>\n    {% for w in by_worker %}\n      <tr><td><b>{{ w.name }}<\/b><\/td><td>{{ w.c }}<\/td><td>{{ w.t|money }}<\/td>\n          <td>{{ w.p|money }}<\/td><td>{{ (w.t - w.p)|money }}<\/td><\/tr>\n    {% endfor %}\n    {% if by_worker|length == 0 %}<tr><td colspan=\"5\" class=\"center muted\">لا مبيعات في هذا اليوم<\/td><\/tr>{% endif %}\n  <\/table>\n  <\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">الأكثر بيعاً اليوم<\/div>\n  <table class=\"tbl\">\n    <tr><th>الصنف<\/th><th>الكمية<\/th><th>القيمة<\/th><\/tr>\n    {% for t in top %}\n      <tr><td>{{ t.name }}<\/td><td>{{ '%g'|format(t.q) }}<\/td><td>{{ t.t|money }}<\/td><\/tr>\n    {% endfor %}\n    {% if top|length == 0 %}<tr><td colspan=\"3\" class=\"center muted\">لا بيانات<\/td><\/tr>{% endif %}\n  <\/table>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">فواتير اليوم<\/div>\n  <p class=\"small muted\">الإلغاء متاح فقط أثناء وردية الفاتورة نفسها، وللفواتير التي لا تحتوي دفعة حوالة أو محفظة أو إيداع؛ ما عدا ذلك يلزم تسوية مرتجع منفصلة.<\/p>\n  <div class=\"scroll-x\">\n  <table class=\"tbl\">\n    <tr><th>رقم<\/th><th>الوقت<\/th><th>العامل<\/th><th>الزبون<\/th><th>الإجمالي<\/th><th>الدفع<\/th><th><\/th><\/tr>\n    {% for i in invoices %}\n      <tr>\n        <td>{{ i.number }}<\/td>\n        <td class=\"small\">{{ i.created_at | slice(11, 16) }}<\/td>\n        <td class=\"small\">{{ i.uname }}<\/td>\n        <td class=\"small\">{{ i.cname or '—' }}<\/td>\n        <td><b>{{ i.total_cents|money }}<\/b><\/td>\n        <td>\n          {% if i.status=='cancelled' %}<span class=\"pill r\">ملغاة<\/span>\n          {% elif i.payment_type=='cash' %}<span class=\"pill g\">نقدي<\/span>\n          {% else %}<span class=\"pill a\">آجل {{ i.due_cents|money }}<\/span>{% endif %}\n        <\/td>\n        <td class=\"row\" style=\"gap:4px\">\n          <a class=\"btn sm ghost\" href=\"{{ url_for('invoice', iid=i.id) }}\">عرض<\/a>\n          {% if i.status=='open' and u.role=='owner' %}\n          <form method=\"POST\" action=\"{{ url_for('invoice_cancel', iid=i.id) }}\"\n                onsubmit=\"return confirm('إلغاء الفاتورة {{ i.number }}؟ إذا توفرت شروط الإلغاء سيُعاد المخزون ويُرد النقد المسجّل فقط')\">\n            <button class=\"btn sm red\">إلغاء<\/button>\n          <\/form>\n          {% endif %}\n        <\/td>\n      <\/tr>\n    {% endfor %}\n    {% if invoices|length == 0 %}<tr><td colspan=\"7\" class=\"center muted\">لا فواتير<\/td><\/tr>{% endif %}\n  <\/table>\n  <\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">🚚 ما علينا للموردين والمناديب<\/div>\n  <div class=\"scroll-x\">\n  <table class=\"tbl\">\n    <tr><th>المورد/المندوب<\/th><th>النوع<\/th><th>علينا له<\/th><th>آخر زيارة<\/th><th>الهاتف<\/th><\/tr>\n    {% for s in sup_debts %}\n      <tr><td><a href=\"{{ url_for('supplier_detail', sid=s.id) }}\">{{ s.name }}<\/a><\/td>\n          <td class=\"small\">{{ 'مندوب' if s.kind=='delegate' else 'ثابت' }}{% if s.returnable %} • مرتجع{% endif %}<\/td>\n          <td><b style=\"color:#b45309\">{{ s.balance_cents|money }}<\/b><\/td>\n          <td class=\"small\">{{ s.last_visit_at | slice(0, 10)|ago if s.last_visit_at else 'لم يمر بعد' }}<\/td>\n          <td class=\"small\">{{ s.phone or '—' }}<\/td><\/tr>\n    {% endfor %}\n    {% if sup_debts|length == 0 %}<tr><td colspan=\"5\" class=\"center muted\">لا مبالغ علينا — الحسابات مصفّاة ✔<\/td><\/tr>{% endif %}\n  <\/table>\n  <\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">أكبر الديون (تنبيه: تابع المتأخرين)<\/div>\n  <div class=\"scroll-x\">\n  <table class=\"tbl\">\n    <tr><th>الزبون<\/th><th>الرصيد<\/th><th>آخر فاتورة<\/th><th>الهاتف<\/th><\/tr>\n    {% for c in debts %}\n      <tr><td><a href=\"{{ url_for('customer_detail', cid=c.id) }}\">{{ c.name }}<\/a><\/td>\n          <td><b style=\"color:#b91c1c\">{{ c.balance_cents|money }}<\/b><\/td>\n          <td class=\"small\">{{ c.last_invoice_at | slice(0, 10) if c.last_invoice_at else '—' }}<\/td>\n          <td class=\"small\">{{ c.phone or '—' }}<\/td><\/tr>\n    {% endfor %}\n    {% if debts|length == 0 %}<tr><td colspan=\"4\" class=\"center muted\">لا ديون<\/td><\/tr>{% endif %}\n  <\/table>\n  <\/div>\n  <div class=\"hint\">تنبيه «دين متأخر مدة طويلة» التلقائي يصل في المرحلة 2 (حساب عمر الدين تلقائياً).<\/div>\n<\/div>\n{% endblock %}\n", "settings.html": "{% extends \"base.html\" %}\n{% block title %}الإعدادات{% endblock %}\n{% block content %}\n<div class=\"h1\">الإعدادات<\/div>\n\n<form method=\"post\">\n<div class=\"card mt\">\n  <div class=\"h2\">بيانات المتجر (تظهر في الفاتورة)<\/div>\n  <label>اسم المتجر<\/label><input name=\"store_name\" value=\"{{ S.store_name }}\">\n  <label>شعار المتجر (يظهر على الفواتير والتقارير)<\/label>\n  <input type=\"file\" accept=\"image/*\" id=\"logoFile\">\n  <input type=\"hidden\" name=\"store_logo\" id=\"storeLogo\" value=\"{{ S.store_logo or '' }}\">\n  <div class=\"hint\">يُصغَّر تلقائياً. اختيار صورة جديدة يستبدل الشعار الحالي.<\/div>\n  <div id=\"logoPrev\" class=\"mt\">{% if S.store_logo %}<img src=\"{{ S.store_logo }}\" alt=\"\" style=\"max-height:80px\">{% endif %}<\/div>\n  <button type=\"button\" class=\"btn sm ghost\" id=\"logoClear\">إزالة الشعار<\/button>\n  <label>هاتف المتجر<\/label><input name=\"store_phone\" value=\"{{ S.store_phone }}\">\n  <label>مفتاح الدولة لأرقام الواتساب<\/label><input name=\"country_code\" value=\"{{ S.country_code or '967' }}\" inputmode=\"numeric\" dir=\"ltr\" placeholder=\"967\">\n  <div class=\"hint\">يُضاف تلقائياً للأرقام المحلية التي تبدأ بـ 0 (مثال: 0501110003 ← 967501110003).<\/div>\n  <label>العملة المكتوبة على الفواتير<\/label><input name=\"currency\" value=\"{{ S.currency }}\">\n  <label>تذييل الفاتورة<\/label><input name=\"invoice_footer\" value=\"{{ S.invoice_footer }}\">\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">واتساب: إرسال الفاتورة PDF تلقائياً عند البيع الآجل<\/div>\n  <div class=\"hint\">يُرسل تلقائياً عند بيع آجل بقي فيه دين، بملف الفاتورة وإجمالي الدين. يحتاج حساب Meta Cloud API. التوكن يُحفظ في جهازك فقط ولا يظهر بعد الحفظ.<\/div>\n  <label>معرّف رقم الواتساب (Phone number ID)<\/label><input name=\"wa_phone_id\" value=\"{{ S.wa_phone_id }}\" dir=\"ltr\" inputmode=\"numeric\">\n  <label>التوكن الدائم {% if S.wa_token_set %}<span class=\"muted\">(محفوظ — اكتب توكناً جديداً لاستبداله)<\/span>{% endif %}<\/label>\n  <input name=\"wa_token\" type=\"password\" value=\"\" dir=\"ltr\" autocomplete=\"off\" placeholder=\"{{ 'محفوظ' if S.wa_token_set else 'EAAG…' }}\">\n  <label>اسم قالب الرسالة المعتمد<\/label><input name=\"wa_template\" value=\"{{ S.wa_template }}\" dir=\"ltr\">\n  <div class=\"hint\">يجب أن يحتوي القالب على ترويسة مستند (PDF)، وفي النص متغيران: {{'{{1}}'}} إجمالي الفاتورة، {{'{{2}}'}} إجمالي الدين.<\/div>\n  <label>لغة القالب<\/label><input name=\"wa_lang\" value=\"{{ S.wa_lang or 'ar' }}\" dir=\"ltr\">\n  <div class=\"hint\">آخر حالة إرسال: {{ S.wa_last or 'لا يوجد إرسال بعد' }}<\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">صلاحيات العمال<\/div>\n  <div class=\"hint\">حدّد النوافذ التي يفتحها كل عامل. الإعدادات وإدارة المستخدمين وإلغاء الفواتير للمالك وحده.<\/div>\n  {% set has_workers = false %}\n  {% for w in users_list %}\n    {% if w.role == 'worker' %}\n      {% set has_workers = true %}\n      <input type=\"hidden\" name=\"perm_present_{{ w.id }}\" value=\"1\">\n      <div class=\"h2 mt\" style=\"font-size:15px\">{{ w.name }}<\/div>\n      {% for sc in screens %}\n        <div class=\"check\">\n          <input type=\"checkbox\" name=\"perm_{{ w.id }}_{{ sc.k }}\" value=\"1\" id=\"p{{ w.id }}_{{ sc.k }}\" {% if w['p_' + sc.k] %}checked{% endif %}>\n          <label for=\"p{{ w.id }}_{{ sc.k }}\" style=\"margin:0\">{{ sc.l }}<\/label>\n        <\/div>\n      {% endfor %}\n    {% endif %}\n  {% endfor %}\n  {% if not has_workers %}<div class=\"muted small\">لا يوجد عمال بعد.<\/div>{% endif %}\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">قواعد البيع<\/div>\n  <label>حد التنبيه الافتراضي للنواقص (لكل صنف جديد)<\/label>\n  <input name=\"low_stock_default\" value=\"{{ S.low_stock_default }}\" inputmode=\"decimal\">\n  <label for=\"expiryDays\">التنبيه بقرب انتهاء الصلاحية قبل كم يوم؟<\/label>\n  <input id=\"expiryDays\" name=\"expiry_alert_days\" type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"365\" required value=\"{{ S.expiry_alert_days or '30' }}\">\n  <div class=\"hint\">يظهر للمالك على اللوحة وفي قائمة الأصناف عند فتح التطبيق؛ لا يرسل إشعار هاتف مغلقاً. التاريخ المسجل للصنف واحد، وليس تاريخ كل دفعة واردة.<\/div>\n  <label for=\"followupDays\">متابعة الدين بعد كم يوم من أقدم مبلغ غير مسدد؟<\/label>\n  <input id=\"followupDays\" name=\"debt_followup_days\" type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"365\" required value=\"{{ S.debt_followup_days or '30' }}\">\n  <div class=\"hint\">تُعتبر الدفعات تسديداً للأقدم أولاً. هذه قائمة متابعة داخل التطبيق، لا تُنشئ تاريخ استحقاق تعاقدياً ولا تُرسل رسائل تلقائياً؛ الدين المرحّل يؤرَّخ بتاريخ إنشاء حساب الزبون.<\/div>\n  <div class=\"check\">\n    <input type=\"checkbox\" name=\"allow_negative_stock\" value=\"1\" id=\"neg\" {% if S.allow_negative_stock=='1' %}checked{% endif %}>\n    <label for=\"neg\" style=\"margin:0\">السماح بالبيع ولو نفد الرصيد (يسجّل الرصيد بالسالب مع تنبيه)<\/label>\n  <\/div>\n  <div class=\"check\">\n    <input type=\"checkbox\" name=\"allow_price_edit\" value=\"1\" id=\"pedit\" {% if S.allow_price_edit=='1' %}checked{% endif %}>\n    <label for=\"pedit\" style=\"margin:0\">السماح للمالك بتعديل السعر داخل الفاتورة (للمرحلة 2 تفصيلاً)<\/label>\n  <\/div>\n  <div class=\"check\">\n    <input type=\"checkbox\" name=\"demo_hint\" value=\"1\" id=\"demo\" {% if S.demo_hint=='1' %}checked{% endif %}>\n    <label for=\"demo\" style=\"margin:0\">إظهار رموز الدخول التجريبية في شاشة الدخول<\/label>\n  <\/div>\n<\/div>\n\n<button class=\"btn p lg wide\">💾 حفظ الإعدادات<\/button>\n<\/form>\n\n<div class=\"card mt\" id=\"cloudBootstrapLinkCard\">\n  <div class=\"h2\">☁️ تهيئة مشروع المتجر السحابي<\/div>\n  <div class=\"muted small\">يدخل المالك رابط مشروع Supabase ومفتاحه العام من هاتفه. يُحفظان محلياً بتشفير Android Keystore، ولا تُفعّل المزامنة أو مشاركة بيانات الزبائن بمجرد الحفظ.<\/div>\n  <a class=\"btn ghost wide mt\" href=\"/cloud/setup\">فتح التهيئة السحابية<\/a>\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"h2\">اسم حساب المالك الظاهر في التطبيق<\/div>\n  <div class=\"muted small\">يمكنك كتابة اسمك أو «مدير» أو «أدمن». هذا يغيّر الاسم المعروض في الدخول وخانة «الموظف» حتى عند إعادة طباعة فاتورة قديمة؛ لا يغيّر الصلاحية أو اسم المتجر أو مبالغ الفواتير.<\/div>\n  {% for account in users_list %}\n    {% if account.role == 'owner' %}\n      <form method=\"POST\" action=\"{{ url_for('users_page') }}\" class=\"row wrap mt\" style=\"gap:8px\">\n        <input type=\"hidden\" name=\"uid\" value=\"{{ account.id }}\">\n        <input name=\"name\" class=\"grow\" maxlength=\"60\" value=\"{{ account.name }}\" aria-label=\"اسم حساب المالك\" required>\n        <button class=\"btn sm p\">حفظ الاسم<\/button>\n      <\/form>\n    {% endif %}\n  {% endfor %}\n<\/div>\n\n<div class=\"card mt\">\n  <div class=\"h2\">العاملون والصلاحيات<\/div>\n  <div class=\"muted small\">رموز الدخول 4 أرقام. في إصدار النشر تُوقَف الحسابات التي ما زالت تستعمل الرموز التجريبية؛ غيّر رمز العامل الموقوف لتفعيله من جديد. العامل يرى النوافذ التي تحددها له؛ المالك يرى كل شيء.<\/div>\n  <table class=\"tbl mt\">\n    <tr><th>الاسم<\/th><th>الصلاحية<\/th><th>تغيير الرمز<\/th><\/tr>\n    {% for us in users_list %}\n      <tr>\n        <td><b>{{ us.name }}<\/b>{% if us.active == 0 %}<div class=\"muted small\">موقوف حتى تغيير الرمز<\/div>{% endif %}<\/td>\n        <td>{% if us.role=='owner' %}<span class=\"pill b\">مالك<\/span>{% else %}<span class=\"pill gray\">عامل<\/span>{% endif %}<\/td>\n        <td>\n          <form method=\"POST\" action=\"{{ url_for('users_page') }}\" class=\"row\" style=\"gap:6px\">\n            <input type=\"hidden\" name=\"uid\" value=\"{{ us.id }}\">\n            <input name=\"pin\" placeholder=\"رمز جديد\" style=\"width:110px\" inputmode=\"numeric\" maxlength=\"4\">\n            <button class=\"btn sm ghost\">تغيير<\/button>\n          <\/form>\n        <\/td>\n      <\/tr>\n    {% endfor %}\n  <\/table>\n  <form method=\"POST\" action=\"{{ url_for('users_page') }}\" class=\"row mt\" style=\"gap:6px\">\n    <input name=\"name\" placeholder=\"اسم عامل جديد\" class=\"grow\">\n    <input name=\"pin\" placeholder=\"رمز 4 أرقام\" style=\"width:112px\" inputmode=\"numeric\" pattern=\"[0-9]{4}\" maxlength=\"4\" required>\n    <button class=\"btn sm p\">إضافة<\/button>\n  <\/form>\n<\/div>\n\n<div class=\"card mt\" id=\"backupTools\">\n  <div class=\"h2\">نسخة احتياطية مشفّرة — تصدير وفحص تجريبيان<\/div>\n  <div class=\"muted small\">قاعدة البيع الأصلية تبقى على الهاتف. تحفظ ملفاً مشفّراً في المكان الذي تختاره (وقد يكون مزوّد تخزين سحابياً)، ثم تفحصه بعبارته. لا يرفع التطبيق شيئاً تلقائياً. <b>الاستعادة غير متاحة بعد<\/b>؛ لا تحذف التطبيق أو تمسح بياناته أو تثبّت تحديثاً يتطلب إزالته.<\/div>\n  <div class=\"hint mt\">اختر عبارة قوية لا تقل عن 12 حرفاً، واحتفظ بها أنت في مكان آمن. نسيانها يعني عدم القدرة على فتح الملف. لا ترسلها لأحد ولا تُحفظ في إعدادات التطبيق.<\/div>\n  <label for=\"backupPhrase\">عبارة مرور النسخة الجديدة<\/label>\n  <input type=\"password\" id=\"backupPhrase\" minlength=\"12\" maxlength=\"256\" autocomplete=\"off\" spellcheck=\"false\" dir=\"auto\" placeholder=\"12 حرفاً على الأقل\">\n  <label for=\"backupConfirm\">تأكيد عبارة المرور<\/label>\n  <input type=\"password\" id=\"backupConfirm\" minlength=\"12\" maxlength=\"256\" autocomplete=\"off\" spellcheck=\"false\" dir=\"auto\" placeholder=\"أعد كتابة العبارة\">\n  <button type=\"button\" class=\"btn p mt\" id=\"backupExport\">حفظ نسخة مشفّرة في ملف<\/button>\n  <div class=\"hint mt\">لفحص ملف سبق حفظه: أدخل عبارته ثم اختره من ملفات الهاتف. لا يغيّر الفحص بيانات البيع.<\/div>\n  <label for=\"backupInspectPhrase\">عبارة مرور الملف المراد فحصه<\/label>\n  <input type=\"password\" id=\"backupInspectPhrase\" minlength=\"12\" maxlength=\"256\" autocomplete=\"off\" spellcheck=\"false\" dir=\"auto\" placeholder=\"عبارة الملف المختار\">\n  <button type=\"button\" class=\"btn ghost mt\" id=\"backupInspect\">اختر ملفاً وافحصه (دون استعادة)<\/button>\n  <div class=\"hint mt\" id=\"backupStatus\" role=\"status\" aria-live=\"polite\"><\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">الأوامر الصوتية بالعربية — تجربة<\/div>\n  <div class=\"hint\">اضغط 🎤 ثم «ابدأ الاستماع». قد تحتاج خدمة الهاتف إلى الإنترنت وقد ترسل الصوت لمزوّدها؛ لا يحفظ رفيق التسجيل. أمثلة: «أضف حليب عدد 2» في شاشة البيع لإضافته إلى السلة، «أضف صنف جديد قهوة بسعر 30» لتعبئة نموذج يراجعه المالك ويحفظه بيده، «بيع نقدي» أو «بيع آجل» لفتح مراجعة الدفع، «اطبع الفاتورة» لفاتورة محفوظة، «شارك الفاتورة» لفتح مشاركة PDF مع زبون مرتبط برقم. راجع الصنف والكمية والإجمالي والزبون؛ لا يُحفظ بيع/دين إلا بضغط زر التأكيد في شاشة الدفع. اختر مستلم PDF بنفسك داخل تطبيق الإرسال؛ لا يوجد إرسال تلقائي عام أو تنفيذ لأوامر مجهولة.<\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">فحص سرعة ماسح الباركود<\/div>\n  <div class=\"muted small\">امسح باركوداً حقيقياً من شاشة البيع ثم عد إلى هنا. زمن «بدء الكاميرا» حتى ظهور المعاينة، وزمن «التركيز/القراءة والعودة» بعدها؛ الأخير لا يفصل التركيز عن فكّ الكود أو إغلاق نشاط الكاميرا. لا تُرسل هذه الأرقام ولا يُحفظ الباركود.<\/div>\n  <div class=\"hint mt\" id=\"scanTiming\">لم يُقَس مسح ناجح في هذه الجلسة بعد.<\/div>\n<\/div>\n\n<div class=\"card\">\n  <div class=\"h2\">عن النسخة<\/div>\n  <div class=\"muted small\">البيع والبيانات محفوظان محلياً على هذا الهاتف. التصدير والفحص تجريبيان وليسا بديلاً عن استعادة اختُبرت على الهاتف؛ لا توجد مزامنة مع Supabase. لا تحذف التطبيق ولا تمسح بياناته ولا تُثبّت نسخة تتطلب حذفه.<\/div>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script>\n(function(){\n  var el=document.getElementById('scanTiming');\n  if(!el || !window.RafiqDevice || !window.RafiqDevice.scanDiagnostics) return;\n  try {\n    var d=JSON.parse(window.RafiqDevice.scanDiagnostics());\n    if(d.total_ms != null) el.textContent='آخر مسح: بدء الكاميرا '+(d.ready_ms == null ? 'غير مقاس' : d.ready_ms+' مللي ثانية')+\n      ' • التركيز/القراءة/العودة '+(d.reading_ms == null ? 'غير مقاس' : d.reading_ms+' مللي ثانية')+\n      ' • الإجمالي '+d.total_ms+' مللي ثانية.';\n  } catch(e){}\n})();\n(function(){\n  var f=document.getElementById('logoFile'), h=document.getElementById('storeLogo'), p=document.getElementById('logoPrev');\n  if(!f) return;\n  f.onchange=function(){\n    var file=f.files&&f.files[0]; if(!file) return;\n    var r=new FileReader();\n    r.onload=function(){\n      var im=new Image();\n      im.onload=function(){\n        var max=240, k=Math.min(1, max/Math.max(im.width, im.height));\n        var c=document.createElement('canvas'); c.width=Math.round(im.width*k); c.height=Math.round(im.height*k);\n        c.getContext('2d').drawImage(im,0,0,c.width,c.height);\n        var url=c.toDataURL('image/png');\n        h.value=url; p.innerHTML='<img src=\"'+url+'\" alt=\"\" style=\"max-height:80px\">';\n      };\n      im.src=r.result;\n    };\n    r.readAsDataURL(file);\n  };\n  document.getElementById('logoClear').onclick=function(){ h.value=''; p.innerHTML=''; f.value=''; };\n})();\n(function(){\n  var status=document.getElementById('backupStatus');\n  if(!status) return;\n  function update(message, ok){\n    // تحديث عنصر الشاشة الحالية فقط؛ قد يكون المستخدم تنقّل قبل اكتمال اختيار الملف.\n    var current=document.getElementById('backupStatus');\n    if(!current) return;\n    current.textContent=message;\n    current.style.color=ok === false ? '#a52222' : '#17513c';\n    var x=document.getElementById('backupExport'), y=document.getElementById('backupInspect');\n    if(x) x.disabled=false;\n    if(y) y.disabled=false;\n  }\n  window.__rafiqBackupResult=update;\n  function start(kind){\n    var device=window.RafiqDevice;\n    if(!device || !device.backupExport || !device.backupInspect){\n      update('هذه الوظيفة متاحة في تطبيق أندرويد الجديد فقط، وليست نسخة الويب.', false); return;\n    }\n    var a=document.getElementById(kind === 'export' ? 'backupPhrase' : 'backupInspectPhrase');\n    var c=document.getElementById('backupConfirm');\n    var phrase=a.value;\n    if(phrase.length < 12 || phrase.length > 256){ update('اكتب عبارة مرور بين 12 و256 حرفاً.', false); return; }\n    if(kind === 'export' && phrase !== c.value){ update('تأكيد عبارة المرور لا يطابقها.', false); return; }\n    a.value='';\n    if(kind === 'export') c.value='';\n    var x=document.getElementById('backupExport'), y=document.getElementById('backupInspect');\n    x.disabled=true; y.disabled=true;\n    status.textContent=kind === 'export' ? 'جارٍ تجهيز النسخة المشفّرة؛ انتظر اختيار مكان حفظها…' : 'اختر ملف النسخة من ملفات هاتفك للفحص…';\n    status.style.color='#17513c';\n    try {\n      var accepted=kind === 'export' ? device.backupExport(phrase) : device.backupInspect(phrase);\n      if(!accepted) update('تعذّر بدء العملية: تأكّد من دخول المالك، وعبارة المرور، وعدم وجود عملية نسخ أخرى.', false);\n    } catch(e){ update('تعذّر بدء العملية. أعد المحاولة.', false); }\n  }\n  document.getElementById('backupExport').onclick=function(){ start('export'); };\n  document.getElementById('backupInspect').onclick=function(){ start('inspect'); };\n})();\n<\/script>\n{% endblock %}\n", "supplier_detail.html": "{% extends \"base.html\" %}\n{% block title %}كشف حساب {{ s.name }}{% endblock %}\n{% block bodyclass %}pad-b{% endblock %}\n{% block content %}\n\n<div class=\"row mt\">\n  <a class=\"btn sm ghost\" href=\"{{ url_for('suppliers') }}\">‹ رجوع<\/a>\n  <div class=\"grow center\">\n    <div class=\"h2\" style=\"margin:0\">{{ s.name }}<\/div>\n    <div class=\"muted small\">\n      {% if s.kind == 'delegate' %}مندوب متجول • {{ PL.get(s.periodicity, s.periodicity) }}{% else %}مورد ثابت{% endif %}\n      {% if s.phone %} • <span style=\"direction:ltr\">{{ s.phone }}<\/span>{% endif %}\n    <\/div>\n  <\/div>\n  <form method=\"POST\" action=\"{{ url_for('supplier_visit', sid=s.id) }}\">\n    <button class=\"btn sm\" style=\"background:#d9f2e4;color:#0f5c46\" title=\"تسجيل زيارة اليوم\">✔<\/button>\n  <\/form>\n<\/div>\n\n<div class=\"card center mt\" style=\"padding:16px\">\n  <div class=\"muted small\">علينا له (الرصيد)<\/div>\n  <div style=\"font-size:2.1rem; font-weight:800; color:{{ '#b45309' if s.balance_cents>0 else '#17795e' }}\">\n    {{ s.balance_cents|money }} {{ S.currency }}\n  <\/div>\n  <div class=\"small\">\n    {% if s.balance_cents > 0 %}<span class=\"chipb r\">علينا له<\/span>\n    {% elif s.balance_cents < 0 %}<span class=\"chipb g\">له عندنا (دفعنا زيادة)<\/span>\n    {% else %}<span class=\"chipb g\">الحساب مصفّى ✔<\/span>{% endif %}\n    {% if s.returnable %}<span class=\"chipb g\">يُرتجع الفائض<\/span>{% else %}<span class=\"chipb\">لا رجعة فيه<\/span>{% endif %}\n    {% if s.overdue %}<span class=\"chipb r\">متأخر عن موعده<\/span>{% endif %}\n    {% if s.due_today %}<span class=\"chipb\">متوقع اليوم<\/span>{% endif %}\n  <\/div>\n  {% if s.goods %}<div class=\"muted small mt\">البضاعة: {{ s.goods }}<\/div>{% endif %}\n<\/div>\n\n<div class=\"opts mt\">\n  <a class=\"btn ghost\" href=\"#ledger\">📄 كشف المعاملات<\/a>\n    <a class=\"btn ghost\" href=\"/suppliers/{{ s.id }}/print\">🖨 طباعة كشف الحساب<\/a>\n  <a class=\"btn ghost\" href=\"#visits\">🗓 زياراته ({{ visits|length }})<\/a>\n  <a class=\"btn ghost\" href=\"#waBox\">📲 تذكير واتساب<\/a>\n  {% if u.role == 'owner' %}<button class=\"btn ghost\" onclick=\"openModal('editModal')\">✏️ تعديل البيانات<\/button>{% endif %}\n<\/div>\n\n<div class=\"row mt\" id=\"ledger\" style=\"margin-top:16px\">\n  <div class=\"h2 grow\">المعاملات <span class=\"chipb\">{{ ev|length }}<\/span><\/div>\n<\/div>\n<div class=\"ledger mt\">\n  {% for e in ev %}\n    <div class=\"rowline\">\n      {% if e.kind == 'receive' %}\n        <span class=\"circ up\">↑<\/span>\n      {% elif e.kind == 'pay' %}\n        <span class=\"circ dn\">↓<\/span>\n      {% else %}\n        <span class=\"circ\" style=\"background:#dbeafe;color:#1d4ed8\">↩<\/span>\n      {% endif %}\n      <span class=\"who\">\n        <span class=\"nm\">\n          {% if e.kind == 'receive' %}استلمت بضاعة{% elif e.kind == 'pay' %}سدّدت له{% else %}رجّعت فائضاً{% endif %}\n          {% if e.ref %} — فاتورة {{ e.ref }}{% endif %}\n        <\/span>\n        <span class=\"sub\">{{ e.ts | slice(0, 16) }}\n          {% if e.user %} • {{ e.user }}{% endif %}\n          {% if e.note %} • {{ e.note }}{% endif %}\n          • <span class=\"chipb {{ 'g' if e.balance_after<=0 else 'r' }}\">الرصيد {{ e.balance_after|money }}<\/span>\n        <\/span>\n      <\/span>\n      <span class=\"amt\">\n        <div class=\"a {{ 'g' if e.kind != 'receive' else 'r' }}\">{{ e.amount|money }}<\/div>\n        <div class=\"t\">{{ 'علينا له' if e.kind == 'receive' else ('سدّدنا' if e.kind == 'pay' else 'مرتجع') }}<\/div>\n      <\/span>\n    <\/div>\n  {% endfor %}\n  {% if not ev %}<div class=\"center muted\" style=\"padding:22px\">لا معاملات بعد — «استلمت» يسجّل أول بضاعة<\/div>{% endif %}\n<\/div>\n\n<div class=\"row mt\" id=\"visits\">\n  <div class=\"h2 grow\">زياراته المسجّلة<\/div>\n<\/div>\n<div class=\"ledger mt\">\n  {% for v in visits %}\n    <div class=\"rowline\">\n      <span class=\"circ\" style=\"background:#e2e8f0;color:#475569\">🗓<\/span>\n      <span class=\"who\"><span class=\"nm\">مرّ المتجر<\/span>\n        <span class=\"sub\">{{ v.created_at | slice(0, 16) }}{% if v.uname %} • {{ v.uname }}{% endif %}<\/span><\/span>\n      <span class=\"amt\"><div class=\"a\" style=\"color:#94a3b8\">{{ v.created_at | slice(0, 10)|ago }}<\/div><\/span>\n    <\/div>\n  {% endfor %}\n  {% if not visits %}<div class=\"center muted\" style=\"padding:22px\">لا زيارات مسجّلة — زر «✔ مرّ اليوم» يسجّلها<\/div>{% endif %}\n<\/div>\n\n<!-- واتساب: تذكير المندوب -->\n<div class=\"card\" id=\"waBox\">\n  <div class=\"h2\">📲 تذكير واتساب للمندوب<\/div>\n  <div class=\"muted small\">راجع الرقم والرسالة ثم اضغط الإرسال — الإرسال يبقى بيدك دائماً.<\/div>\n  <label>رقم الواتساب<\/label>\n  <input id=\"waPhone\" value=\"{{ s.phone }}\" inputmode=\"tel\">\n  <label>نص الرسالة<\/label>\n  <textarea id=\"waText\" rows=\"4\">مرحباً {{ s.name }} 👋\nنحن {{ S.store_name }} — {% if s.due_today %}اليوم موعد توريد {{ s.goods or 'البضاعة' }}{% elif s.overdue %}حان موعد توريد {{ s.goods or 'البضاعة' }} وننتظره منك{% else %}نحتاج توريد {{ s.goods or 'البضاعة' }}{% endif %}.\n{% if s.balance_cents>0 %}ومتبقٍ علينا لك {{ s.balance_cents|money }} {{ S.currency }} — جاهزون للسداد عند مرورك.{% endif %}\nشكراً لك 🌹<\/textarea>\n  <button class=\"btn wa-btn wide mt\" id=\"waSend\">فتح واتساب بالرسالة<\/button>\n<\/div>\n\n<!-- شريط كناش السفلي: سدّدت / استلمت / (رجّعت) -->\n<div class=\"bottombar no-print\">\n  <div class=\"in\" style=\"grid-template-columns:{{ '1fr 1fr 1fr' if s.returnable else '1fr 1fr' }}\">\n    <button class=\"bbtn take\" onclick=\"openModal('recvModal')\">✔ استلمت<\/button>\n    {% if u.role == 'owner' %}\n      <button class=\"bbtn give\" onclick=\"openModal('payModal')\">✔ سدّدت<\/button>\n    {% else %}\n      <button class=\"bbtn give\" style=\"opacity:.45\" onclick=\"toast('السداد للمالك فقط','err')\">✔ سدّدت<\/button>\n    {% endif %}\n    {% if s.returnable %}\n      <button class=\"bbtn\" style=\"background:#dbeafe;color:#1d4ed8\" onclick=\"openModal('retModal')\">✔ رجّعت<\/button>\n    {% endif %}\n  <\/div>\n<\/div>\n\n<!-- نافذة استلمت -->\n<div class=\"modal\" id=\"recvModal\"><div class=\"sheet\">\n  <div class=\"h2\">✔ استلمت بضاعة من {{ s.name }}<\/div>\n  <div class=\"muted small\">تُضاف إلى ما علينا له — نقدياً كانت أم آجلة، المبلغ هنا قيمة البضاعة المستلمة.<\/div>\n  <form method=\"POST\" action=\"{{ url_for('supplier_receive', sid=s.id) }}\">\n    <label>قيمة البضاعة<\/label>\n    <input name=\"amount\" class=\"big center\" inputmode=\"decimal\" required autofocus placeholder=\"0\">\n    <label>رقم فاتورة المندوب (اختياري)<\/label>\n    <input name=\"ref\" placeholder=\"مثال: 4521\">\n    <label>ملاحظة (اختياري)<\/label>\n    <input name=\"note\" placeholder=\"مثال: روتي 50 ربطة\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p lg\" style=\"grid-column:span 2\">تسجيل الاستلام<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('recvModal')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n\n<!-- نافذة سدّدت -->\n<div class=\"modal\" id=\"payModal\"><div class=\"sheet\">\n  <div class=\"h2\">✔ سدّدت لـ {{ s.name }}<\/div>\n  <div class=\"muted small\">يخرج من درج الصندوق المفتوح الآن.<\/div>\n  <form method=\"POST\" action=\"{{ url_for('supplier_pay', sid=s.id) }}\">\n    <label>المبلغ المسدَّد<\/label>\n    <input name=\"amount\" class=\"big center\" inputmode=\"decimal\" required placeholder=\"0\">\n    {% if s.balance_cents > 0 %}\n    <div class=\"quick-amts mt\">\n      <button type=\"button\" class=\"btn\" data-v=\"{{ (s.balance_cents/100) }}\">كامل المبلغ {{ s.balance_cents|money }}<\/button>\n    <\/div>\n    {% endif %}\n    <label>ملاحظة (اختياري)<\/label><input name=\"note\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p lg\" style=\"grid-column:span 2\">تسجيل السداد<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('payModal')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n\n<!-- نافذة رجّعت -->\n<div class=\"modal\" id=\"retModal\"><div class=\"sheet\">\n  <div class=\"h2\">✔ رجّعت فائضاً إلى {{ s.name }}<\/div>\n  <div class=\"muted small\">مثل فائض الروتي والآيسكريم — يُخصم من ما علينا له.<\/div>\n  <form method=\"POST\" action=\"{{ url_for('supplier_return', sid=s.id) }}\">\n    <label>قيمة المرتجع<\/label>\n    <input name=\"amount\" class=\"big center\" inputmode=\"decimal\" required placeholder=\"0\">\n    <label>ملاحظة (اختياري)<\/label>\n    <input name=\"note\" placeholder=\"مثال: فائض 12 ربطة\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn amber lg\" style=\"grid-column:span 2\">تسجيل المرتجع<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('retModal')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n\n{% if u.role == 'owner' %}\n<!-- نافذة تعديل البيانات (للمالك) -->\n<div class=\"modal\" id=\"editModal\"><div class=\"sheet\">\n  <div class=\"h2\">✏️ تعديل بيانات {{ s.name }}<\/div>\n  <div class=\"muted small\">تصحيح الاسم أو الدورية أو نوع البضاعة، أو إيقاف التعامل إن انتهى.<\/div>\n  <form method=\"POST\" action=\"{{ url_for('supplier_edit', sid=s.id) }}\">\n    <label>الاسم<\/label><input name=\"name\" value=\"{{ s.name }}\" required>\n    <label>الهاتف (اختياري)<\/label><input name=\"phone\" value=\"{{ s.phone }}\" inputmode=\"tel\">\n    <div class=\"row\">\n      <div class=\"grow\"><label>النوع<\/label>\n        <select name=\"kind\">\n          <option value=\"delegate\" {{ 'selected' if s.kind=='delegate' }}>مندوب متجول<\/option>\n          <option value=\"fixed\" {{ 'selected' if s.kind=='fixed' }}>مورد ثابت<\/option>\n        <\/select><\/div>\n      <div class=\"grow\"><label>الدورية (للمندوب)<\/label>\n        <select name=\"periodicity\">\n          {% for k, v in PL.items() %}<option value=\"{{ k }}\" {{ 'selected' if s.periodicity==k }}>{{ v }}<\/option>{% endfor %}\n        <\/select><\/div>\n    <\/div>\n    <label>نوع البضاعة<\/label><input name=\"goods\" value=\"{{ s.goods }}\" placeholder=\"مثال: روتي • ثلج • آيسكريم\">\n    <div class=\"check\">\n      <input type=\"checkbox\" name=\"returnable\" value=\"1\" id=\"ret2\" {{ 'checked' if s.returnable }}>\n      <label for=\"ret2\" style=\"margin:0\">يُرتجع الفائض (روتي، آيسكريم…) — أتركه فارغاً لمن لا رجعة فيه (الثلج)<\/label>\n    <\/div>\n    <label>ملاحظة (اختياري)<\/label><input name=\"note\" value=\"{{ s.note }}\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p lg\" style=\"grid-column:span 2\">حفظ التعديل<\/button>\n      <button type=\"button\" class=\"btn ghost\" style=\"grid-column:span 2\" onclick=\"closeModal('editModal')\">رجوع<\/button>\n    <\/div>\n  <\/form>\n  <form method=\"POST\" action=\"{{ url_for('supplier_toggle', sid=s.id) }}\" class=\"mt\">\n    {% if s.active %}\n      <button class=\"btn ghost\" style=\"width:100%; color:#b91c1c; border-color:#fecaca\">⏸ إيقاف التعامل (لا يُحذف — يبقى كشفه محفوظاً)<\/button>\n    {% else %}\n      <button class=\"btn ghost\" style=\"width:100%\">▶ إعادة تفعيل التعامل<\/button>\n    {% endif %}\n  <\/form>\n<\/div><\/div>\n{% endif %}\n{% endblock %}\n\n{% block scripts %}\n<script>\ndocument.querySelectorAll('#payModal .quick-amts .btn').forEach(b=>{\n  b.onclick = ()=>{ document.querySelector('#payModal input[name=amount]').value = b.dataset.v; };\n});\ndocument.getElementById('waSend').onclick = ()=>{\n  waOpen(document.getElementById('waPhone').value, document.getElementById('waText').value);\n};\n<\/script>\n{% endblock %}\n", "suppliers.html": "{% extends \"base.html\" %}\n{% block title %}الموردون والمناديب{% endblock %}\n{% block content %}\n<div class=\"print-head\">\n  {% if S.store_logo %}<img src=\"{{ S.store_logo }}\" alt=\"\">{% endif %}\n  <div><div class=\"t\">{{ S.store_name or \"المتجر\" }}<\/div><div class=\"s\">{{ S.store_name }} • الموردون والمناديب<\/div><\/div>\n<\/div>\n<div class=\"row\">\n  <div class=\"h1 grow\">🚚 الموردون والمناديب<\/div>\n<\/div>\n\n<div class=\"tabs2 mt\">\n  <a href=\"{{ url_for('customers') }}\">العملاء<\/a>\n  <a href=\"{{ url_for('suppliers') }}\" class=\"on\">الموردون<\/a>\n<\/div>\n\n<div class=\"sum2\">\n  <div class=\"cell\"><div class=\"lbl\">استلمنا منهم (بضاعة)<\/div><div class=\"val g\">{{ received_all|money }}<\/div><\/div>\n  <div class=\"cell\"><div class=\"lbl\">سدّدنا ورجّعنا<\/div><div class=\"val r\">{{ (paid_all + returned_all)|money }}<\/div><\/div>\n<\/div>\n<div class=\"sum1 mt\">\n  <span class=\"lbl\">المتبقي علينا لهم:<\/span>\n  <b class=\"h2\" style=\"color:{{ '#b45309' if total>0 else '#17795e' }}\"> {{ total|money }} {{ S.currency }}<\/b>\n  <div class=\"small muted\">{{ delegates }} مندوباً متجولاً • {{ fixed }} مورداً ثابتاً<\/div>\n<\/div>\n\n<!-- المتوقعون اليوم: القلب الزمني للمندوبين الـ35 -->\n<div class=\"card mt\" style=\"border:1.5px solid #cfe8e0\">\n  <div class=\"row\">\n    <div class=\"h2 grow\">📅 المتوقعون اليوم<\/div>\n    <span class=\"chipb {{ 'r' if today_list else 'g' }}\">{{ today_list|length }}<\/span>\n  <\/div>\n  <div class=\"muted small\">من دوريته (شبه يومي/أسبوعي/شهري) حان موعده حسب آخر زيارة — علّم «مرّ اليوم» عند مجيئه ولو ما اشترى.<\/div>\n\n  {% for s in today_list %}\n    <div class=\"rowline\" style=\"border:1px solid var(--line); border-radius:12px; margin-top:10px; padding:10px\">\n      <span class=\"avc {{ 'r' if s.overdue else '' }}\">{{ s.name[0] }}<\/span>\n      <span class=\"who\">\n        <span class=\"nm\">{{ s.name }}\n          {% if s.overdue %}<span class=\"chipb r\">متأخر<\/span>{% endif %}<\/span>\n        <span class=\"sub\">\n          <span class=\"chipb\">{{ PL.get(s.periodicity, s.periodicity) }}<\/span>\n          {% if s.goods %} • {{ s.goods }}{% endif %}\n          • {% if s.days == null %}لم يمر بعد{% else %}<span style=\"white-space:nowrap\">{{ s.days }} يوم<\/span>{% endif %}\n        <\/span>\n      <\/span>\n      <span class=\"amt\" style=\"display:flex; gap:6px; flex-direction:column\">\n        <a class=\"btn sm p nowrap\" style=\"min-width:96px\" href=\"{{ url_for('supplier_detail', sid=s.id) }}\">✔ استلام<\/a>\n        <form method=\"POST\" action=\"{{ url_for('supplier_visit', sid=s.id) }}\">\n          <input type=\"hidden\" name=\"back\" value=\"suppliers\">\n          <button class=\"btn sm ghost nowrap\" style=\"min-width:96px\">مرّ اليوم<\/button>\n        <\/form>\n        {% if s.phone %}<button type=\"button\" class=\"btn sm ghost nowrap\" style=\"min-width:96px; color:#128c7e\"\n          data-phone=\"{{ s.phone }}\" data-name=\"{{ s.name }}\" data-goods=\"{{ s.goods }}\"\n          onclick=\"waRemind(this, event)\">📲 تذكير<\/button>{% endif %}\n      <\/span>\n    <\/div>\n  {% endfor %}\n  {% if not today_list %}\n    <div class=\"center muted\" style=\"padding:14px\">لا أحد متوقع اليوم وفق الدوريات ✔ — ومن مرّ خارج الموعد سيظهر في القائمة أدناه.<\/div>\n  {% endif %}\n<\/div>\n\n<div class=\"card\">\n  <form method=\"get\" class=\"row\">\n    <input name=\"q\" value=\"{{ q }}\" placeholder=\"🔍 ابحث بالاسم أو نوع البضاعة…\" class=\"grow\">\n    <button class=\"btn p\">بحث<\/button>\n  <\/form>\n<\/div>\n\n{% if u.role == 'owner' %}\n<button class=\"btn blue wide mb\" onclick=\"openModal('addSupModal')\">➕ إضافة مورد / مندوب<\/button>\n{% else %}\n<div class=\"card mb center muted small\">إضافة الموردين والمندوبين من صلاحية المالك — أبلغه بالاسم ليضيفه.<\/div>\n{% endif %}\n\n<div class=\"ledger\">\n  {% for r in rows %}\n    <a href=\"{{ url_for('supplier_detail', sid=r.id) }}\" class=\"rowline\" style=\"color:inherit\">\n      <span class=\"avc {{ 'r' if r.balance_cents>0 else ('g' if r.balance_cents<0 else '') }}\">{{ r.name[0] }}<\/span>\n      <span class=\"who\">\n        <span class=\"nm\">{{ r.name }}\n          {% if r.overdue %}<span class=\"chipb r\">متأخر<\/span>{% endif %}\n          {% if r.returnable %}<span class=\"chipb g\">مرتجع<\/span>{% endif %}<\/span>\n        <span class=\"sub\">\n          {% if r.kind == 'delegate' %}<span class=\"chipb\">{{ PL.get(r.periodicity, r.periodicity) }}<\/span>{% else %}<span class=\"chipb\">ثابت<\/span>{% endif %}\n          {% if r.goods %} • {{ r.goods }}{% endif %}\n          • {% if r.last_visit_at %}{{ r.last_visit_at | slice(0, 10)|ago }}{% else %}لم يمر بعد{% endif %}\n        <\/span>\n      <\/span>\n      <span class=\"amt\">\n        {% if r.phone and r.overdue %}<button type=\"button\" class=\"chipb\" style=\"background:#e7f8f1; color:#128c7e; border:0; margin-bottom:4px; padding:6px 10px; font-size:.95rem\"\n          data-phone=\"{{ r.phone }}\" data-name=\"{{ r.name }}\" data-goods=\"{{ r.goods }}\"\n          onclick=\"waRemind(this, event)\" title=\"تذكير واتساب\">📲<\/button>{% endif %}\n        {% if r.balance_cents > 0 %}\n          <div class=\"a r\">{{ r.balance_cents|money }}<\/div><div class=\"t\">علينا له<\/div>\n        {% elif r.balance_cents < 0 %}\n          <div class=\"a g\">{{ (-r.balance_cents)|money }}<\/div><div class=\"t\">له عندنا<\/div>\n        {% else %}\n          <div class=\"a\" style=\"color:#94a3b8\">0<\/div><div class=\"t\">مسدَّد ✔<\/div>\n        {% endif %}\n      <\/span>\n    <\/a>\n  {% endfor %}\n  {% if not rows %}<div class=\"center muted\" style=\"padding:22px\">لا موردين بعد — أضف أول مندوب<\/div>{% endif %}\n<\/div>\n\n{% if u.role == 'owner' %}\n<div class=\"modal\" id=\"addSupModal\"><div class=\"sheet\">\n  <div class=\"h2\">➕ إضافة مورد / مندوب<\/div>\n  <form method=\"POST\" action=\"{{ url_for('supplier_add') }}\">\n    <label>الاسم<\/label><input name=\"name\" required autofocus placeholder=\"مثال: مندوب الروتي — أبو خالد\">\n    <label>الهاتف (اختياري)<\/label><input name=\"phone\" inputmode=\"tel\">\n    <div class=\"row\">\n      <div class=\"grow\"><label>النوع<\/label>\n        <select name=\"kind\">\n          <option value=\"delegate\">مندوب متجول<\/option>\n          <option value=\"fixed\">مورد ثابت<\/option>\n        <\/select><\/div>\n      <div class=\"grow\"><label>الدورية (للمندوب)<\/label>\n        <select name=\"periodicity\">\n          <option value=\"semi_daily\">شبه يومي<\/option>\n          <option value=\"weekly\" selected>أسبوعي<\/option>\n          <option value=\"monthly\">شهري<\/option>\n          <option value=\"daily\">يومي<\/option>\n          <option value=\"irregular\">عند الحاجة<\/option>\n        <\/select><\/div>\n    <\/div>\n    <label>نوع البضاعة<\/label><input name=\"goods\" placeholder=\"مثال: روتي • ثلج • آيسكريم • مشروبات\">\n    <div class=\"check\">\n      <input type=\"checkbox\" name=\"returnable\" value=\"1\" id=\"ret\">\n      <label for=\"ret\" style=\"margin:0\">يُرتجع الفائض (روتي، آيسكريم…) — أتركه فارغاً لمن لا رجعة فيه (الثلج)<\/label>\n    <\/div>\n    <label>ملاحظة (اختياري)<\/label><input name=\"note\">\n    <div class=\"btn-grid mt\">\n      <button class=\"btn p\">حفظ<\/button>\n      <button type=\"button\" class=\"btn ghost\" onclick=\"closeModal('addSupModal')\">إلغاء<\/button>\n    <\/div>\n  <\/form>\n<\/div><\/div>\n{% endif %}\n{% endblock %}\n\n{% block scripts %}\n<script>\nconst SUP_MSG = \"مرحباً {name} 👋\\nنحن \" + {{ S.store_name|tojson }} + \" — حان موعد توريد {goods}.\\nنرجو المرور اليوم، شكراً لك 🌹\";\nfunction waRemind(btn, ev){\n  ev.preventDefault(); ev.stopPropagation();\n  const d = btn.dataset;\n  const txt = SUP_MSG.replace('{name}', d.name || '').replace('{goods}', (d.goods || 'البضاعة'));\n  waOpen(d.phone, txt);\n}\n<\/script>\n{% endblock %}", "cloud_customers.html": "{% extends \"base.html\" %}\n{% block title %}زبائن المتجر المتصل{% endblock %}\n{% block content %}\n<div id=\"cloudCustomers\" data-local-uid=\"{{ u.id }}\" data-local-role=\"{{ u.role }}\">\n  <div class=\"h1\">📒 الزبائن وكشف الدين — من الخادم فقط<\/div>\n  <p class=\"hint\">الزبائن الجدد وأرصدة المتجر هنا منفصلون عن أرصدة Room على الهاتفين. لا نقل آلي، ولا توزيع افتراضي للدفعات على فواتير أو سلف بعينها.<\/p>\n  <div id=\"cloudLedgerMessage\" class=\"flash error\" role=\"status\" aria-live=\"polite\">سجّل دخول المتجر من الصندوق أولاً.<\/div>\n  <div id=\"cloudCustomersLocked\" class=\"card mt\"><a href=\"{{ url_for('cash') }}\">افتح الصندوق وسجّل دخول حساب المتجر<\/a>.<\/div>\n  <div id=\"cloudCustomersActive\" hidden>\n    <div class=\"sum1 mt\">الرصيد الإجمالي لزبائن المتجر الخادمي: <b id=\"cloudAllDebts\">—<\/b><\/div>\n    <p id=\"cloudCustomersCount\" class=\"small muted\"><\/p>\n    <form id=\"cloudCustomerForm\" class=\"card mt\">\n      <div class=\"h2\">زبون جديد في الخادم (دون نقل دين الهاتف)<\/div>\n      <label for=\"cloudCustomerName\">اسم الزبون<\/label><input id=\"cloudCustomerName\" maxlength=\"120\" required>\n      <label for=\"cloudCustomerPhone\">الهاتف اختياري؛ لا يعني موافقة SMS<\/label><input id=\"cloudCustomerPhone\" inputmode=\"tel\" maxlength=\"30\">\n      <button id=\"cloudCustomerSubmit\" type=\"submit\" class=\"btn blue wide mt\">إضافة الزبون للخادم<\/button>\n    <\/form>\n    <div class=\"card mt\">\n      <div class=\"h2\">كشف زبون من الخادم<\/div>\n      <label for=\"cloudSelectedCustomer\">اختر الزبون<\/label>\n      <select id=\"cloudSelectedCustomer\"><option value=\"\">— اختر زبوناً —<\/option><\/select>\n      <p id=\"cloudCustomerBalance\" class=\"h2\">الرصيد: —<\/p>\n      <div id=\"cloudCustomerEntries\" class=\"ledger\"><\/div>\n      <p class=\"small muted\">مبلغ التحصيل يخفض الرصيد العام فقط؛ لم نتفق على توزيعه على دين فاتورة أو سلفة معيّنة.<\/p>\n    <\/div>\n    <form id=\"cloudCollectionForm\" class=\"card mt\">\n      <div class=\"h2\">✔ تحصيل نقدي من الزبون<\/div>\n      <p class=\"small muted\">العامل: يحتاج ورديته الخادمية المفتوحة. لا تحصيل من هاتف المالك دون وردية صرف/قبض محددة.<\/p>\n      <label for=\"cloudCollectionAmount\">المبلغ المقبوض فعلياً<\/label><input id=\"cloudCollectionAmount\" inputmode=\"decimal\" required>\n      <button id=\"cloudCollectionSubmit\" type=\"submit\" class=\"btn p wide\">تأكيد التحصيل وزيادة الصندوق<\/button>\n    <\/form>\n    <form id=\"cloudOwnerDebtForm\" class=\"card mt\" hidden>\n      <div class=\"h2\">أدخل ديناً يدوياً — المالك فقط<\/div>\n      <p class=\"small muted\">لا فاتورة، لا بضاعة، ولا نقد من الصندوق. دوّن السبب للتحقق؛ السلفة النقدية في الصندوق إجراء مختلف أدناه.<\/p>\n      <label for=\"cloudOwnerDebtAmount\">مبلغ الدين<\/label><input id=\"cloudOwnerDebtAmount\" inputmode=\"decimal\" required>\n      <label for=\"cloudOwnerDebtReason\">السبب (3 أحرف على الأقل)<\/label><input id=\"cloudOwnerDebtReason\" maxlength=\"200\" required>\n      <button id=\"cloudOwnerDebtSubmit\" type=\"submit\" class=\"btn amber wide\">تأكيد دين يدوي بلا صرف نقدي<\/button>\n    <\/form>\n    <form id=\"cloudAdvanceForm\" class=\"card mt\" hidden>\n      <div class=\"h2\">− سلفة نقدية للزبون — المالك فقط<\/div>\n      <p class=\"flash error\">تجربة آمنة: تصرف نقداً من وردية عامل مفتوحة مع اعتماد المالك على الخادم؛ ينقص الصندوق ويزيد دين الزبون بالقيمة نفسها. العامل لا يستطيع صرفها وحده؛ سياسة تفويضه وحدوده لم تُحسم.<\/p>\n      <label for=\"cloudAdvanceShift\">اختر الوردية التي سيخرج النقد من درجها<\/label><select id=\"cloudAdvanceShift\"><option value=\"\">— لا وردية —<\/option><\/select>\n      <label for=\"cloudAdvanceAmount\">النقد المصروف فعلياً (ريال يمني)<\/label><input id=\"cloudAdvanceAmount\" inputmode=\"decimal\" required>\n      <label for=\"cloudAdvanceReason\">سبب السلفة (3 أحرف على الأقل)<\/label><input id=\"cloudAdvanceReason\" maxlength=\"200\" required>\n      <button id=\"cloudAdvanceSubmit\" type=\"submit\" class=\"btn amber wide\">راجع ثم أكّد صرف سلفة نقدية<\/button>\n    <\/form>\n    <div class=\"card mt\"><div class=\"h2\">زبائن المتجر الجديد<\/div><div id=\"cloudCustomerList\" class=\"ledger\"><\/div><\/div>\n  <\/div>\n  <div class=\"card mt\">\n    <div class=\"h2\">أرشيف ديون هذا الهاتف فقط<\/div>\n    <p class=\"small muted\">للقراءة دون نسخ تلقائي. أرشيف هاتف المالك لا يُضاف إلى عهدة العامل أو كشف المتجر المتصل.<\/p>\n    <a href=\"/archive/customers\" class=\"btn ghost\">فتح دفتر الهاتف القديم للقراءة فقط<\/a>\n  <\/div>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script src=\"cloud-shift.js\"><\/script>\n<script src=\"cloud-ledger.js\"><\/script>\n<script>window.RafiqCloudLedger.mount('customers');<\/script>\n{% endblock %}\n", "cloud_dashboard.html": "{% extends \"base.html\" %}\n{% block title %}لوحة المالك المتصلة{% endblock %}\n{% block content %}\n<div id=\"cloudDashboard\" data-local-uid=\"{{ u.id }}\" data-local-role=\"{{ u.role }}\">\n  <div class=\"h1\">لوحة صاحب المتجر — الخادم<\/div>\n  <p class=\"hint\">أرقام المتجر الجديدة من قاعدة الاختبار فقط؛ لا تجمع عهدة أو ديون الهاتفين المحليين. أحدثها بالضغط أو أثناء فتح الشاشة.<\/p>\n  <div id=\"cloudLedgerMessage\" class=\"flash error\" role=\"status\" aria-live=\"polite\">ادخل حساب المتجر من الصندوق أولاً.<\/div>\n  <div id=\"cloudDashboardLocked\" class=\"card mt\"><a href=\"{{ url_for('cash') }}\">افتح الصندوق للدخول بحساب المالك السحابي<\/a>.<\/div>\n  <div id=\"cloudDashboardActive\" hidden>\n    <button id=\"cloudDashboardRefresh\" type=\"button\" class=\"btn sm ghost\">تحديث أرقام الخادم<\/button>\n    <button id=\"cloudOwnerSound\" type=\"button\" class=\"btn sm ghost\">تفعيل نغمة المالك أثناء فتح التطبيق فقط<\/button>\n    <p id=\"cloudOwnerEventNotice\" class=\"small\" role=\"status\" hidden><\/p>\n    <p class=\"small muted\">نغمة مقدمة التطبيق فقط بعد اللمس، لا Push خلفية.<\/p>\n    <div class=\"grid g4 mt\" id=\"cloudDashboardStats\"><\/div>\n    <div class=\"card mt\"><div class=\"h2\">الورديات المفتوحة وصندوقها الخادمي<\/div><div id=\"cloudDashboardTills\"><\/div><\/div>\n    <div class=\"card mt\"><div class=\"h2\">أحدث فواتير المتجر الجديد<\/div><div id=\"cloudDashboardInvoices\" class=\"ledger\"><\/div><\/div>\n    <div class=\"btn-grid mt\">\n      <a class=\"btn p\" href=\"/remote-eye\">👁️ العين عن بُعد — صفحة مستقلة<\/a>\n      <a class=\"btn amber\" href=\"/customers\">📒 الزبائن والديون<\/a>\n      <a class=\"btn ghost\" href=\"/cash\">💵 الصندوق والقرارات<\/a>\n    <\/div>\n    <form id=\"cloudProductForm\" class=\"card mt\">\n      <div class=\"h2\">إنشاء صنف في المتجر الخادمي (للمالك)<\/div>\n      <p class=\"small muted\">إنشاء الصنف لا يضيف مخزوناً تلقائياً؛ أدخل رصيده بحركة مستقلة موثقة أدناه. المنتجات المحلية القديمة أرشيف، لا تُنقل هنا.<\/p>\n      <label for=\"cloudProductName\">الاسم<\/label><input id=\"cloudProductName\" maxlength=\"120\" required>\n      <label for=\"cloudProductBarcode\">الباركود (اختياري)<\/label><input id=\"cloudProductBarcode\" maxlength=\"80\">\n      <label for=\"cloudProductPrice\">سعر البيع بالريال اليمني<\/label><input id=\"cloudProductPrice\" inputmode=\"decimal\" required>\n      <label for=\"cloudProductCost\">التكلفة التقريبية بالريال اليمني<\/label><input id=\"cloudProductCost\" inputmode=\"decimal\" required>\n      <button id=\"cloudProductSubmit\" type=\"submit\" class=\"btn blue wide mt\">تأكيد إنشاء الصنف في الخادم<\/button>\n    <\/form>\n    <form id=\"cloudStockForm\" class=\"card mt\">\n      <div class=\"h2\">حركة رصيد صنف خادمي — بإشراف المالك<\/div>\n      <label for=\"cloudStockProduct\">الصنف<\/label><select id=\"cloudStockProduct\"><option value=\"\">— اختر صنفاً —<\/option><\/select>\n      <label for=\"cloudStockQty\">كمية داخلة (حتى ثلاث منازل عشرية)<\/label><input id=\"cloudStockQty\" inputmode=\"decimal\" required>\n      <label for=\"cloudStockReason\">سبب الحركة<\/label><input id=\"cloudStockReason\" maxlength=\"200\" placeholder=\"رصيد اختبار جديد\" required>\n      <button id=\"cloudStockSubmit\" type=\"submit\" class=\"btn p wide mt\">تأكيد إضافة الرصيد على الخادم<\/button>\n    <\/form>\n    <p class=\"small muted\">الهامش المعروض تقديري قبل المصاريف والمشتريات والمرتجعات والضرائب؛ ليس ربحاً صافياً. صلاحية الأصناف والصور والموردون القديمون ما زالوا محليين، لا تنبيهات عالمية لهم هنا.<\/p>\n  <\/div>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script src=\"cloud-shift.js\"><\/script>\n<script src=\"cloud-ledger.js\"><\/script>\n<script>window.RafiqCloudLedger.mount('dashboard');<\/script>\n{% endblock %}\n", "cloud_pilot.html": "{% extends \"base.html\" %}\n{% block title %}اختبار المتجر السحابي{% endblock %}\n{% block content %}\n<div class=\"h1\">☁️ المتجر السحابي التجريبي<\/div>\n<div class=\"flash error mt\" role=\"status\">هذه واجهة اختبار منفصلة على هذا الهاتف. لا تنقل فواتير أو ديون أو أصناف النسخة المحلية القديمة إلى المشروع، ولا تستخدم بيانات زبائن حقيقيين الآن. لا مزامنة فورية ولا SMS، ولم يُختبر الاتصال بهاتفين.<\/div>\n<div class=\"card mt\">\n  <div class=\"h2\">البدء<\/div>\n  <div class=\"muted small mt\">بعد تجهيز مشروع الاختبار وعضويتَي المالك والعامل، يدخل كل شخص بحسابه من واجهة Supabase المنفصلة. يحتاج هذا الهاتف تهيئة عامة محمية، وموافقة المالك على جهاز العامل ثم ورديته.<\/div>\n  <button class=\"btn p lg wide mt\" type=\"button\" onclick=\"if(window.RafiqDevice&&window.RafiqDevice.openPilot)window.RafiqDevice.openPilot()\">فتح واجهة الاختبار السحابي<\/button>\n<\/div>\n<a class=\"btn ghost wide mt\" href=\"/\">← العودة إلى التطبيق المحلي<\/a>\n{% endblock %}\n", "cloud_pos.html": "{% extends \"base.html\" %}\n{% block title %}البيع المتصل{% endblock %}\n{% block content %}\n<div id=\"cloudPos\" data-local-uid=\"{{ u.id }}\" data-local-role=\"{{ u.role }}\">\n  <div class=\"h1\">🛒 شاشة البيع الأصلية — دفتر المتجر الخادمي<\/div>\n  <p class=\"hint\">توقّف البيع والآجل من الشاشة المحلية. لا تُسجَّل فواتير هنا في Room؛ يجب تثبيت ترقية SQL الاختبارية ثم اعتماد جهاز العامل وورديته. أرشيف الهاتفين مستقل.<\/p>\n  <div id=\"cloudLedgerMessage\" class=\"flash error\" role=\"status\" aria-live=\"polite\">افتح الصندوق للدخول إلى حساب المتجر.<\/div>\n  <p id=\"cloudPosSession\" class=\"small muted\"><\/p>\n  <div id=\"cloudPosLocked\" class=\"card mt\">لا توجد جلسة بيع موثوقة. <a href=\"{{ url_for('cash') }}\">افتح الصندوق وسجّل دخول المتجر، ثم اطلب اعتماد الوردية<\/a>.<\/div>\n  <div id=\"cloudPosWorker\" hidden>\n    <div class=\"card tight mt\">\n      <div class=\"h2\">الصنف من مخزون الخادم<\/div>\n      <p class=\"small muted\">باركود/اسم أو كاميرا الهاتف؛ السعر والمخزون يُفحصان ثانية على الخادم وقت الحفظ. إذا تغيّرا لا تُحفظ الفاتورة: حدّث الأصناف وراجع السلة من جديد.<\/p>\n      <button id=\"cloudSaleReload\" type=\"button\" class=\"btn sm ghost\">تحديث الأصناف والأسعار من الخادم<\/button>\n      <div class=\"row wrap\">\n        <input id=\"cloudSaleSearch\" class=\"grow\" placeholder=\"ابحث عن صنف أو امسح باركوداً\" autocomplete=\"off\">\n        <button id=\"cloudSaleCamera\" type=\"button\" class=\"btn sm ghost\">📷 مسح<\/button>\n      <\/div>\n      <label for=\"cloudSaleProduct\">اختر الوجه الصحيح والسعر<\/label>\n      <select id=\"cloudSaleProduct\"><option value=\"\">لا أصناف محمّلة بعد<\/option><\/select>\n      <label for=\"cloudSaleQty\">الكمية بالحبة (حتى 3 منازل عشرية)<\/label>\n      <input id=\"cloudSaleQty\" inputmode=\"decimal\" value=\"1\">\n      <button id=\"cloudSaleAdd\" type=\"button\" class=\"btn blue wide mt\">أضف إلى السلة للمراجعة<\/button>\n    <\/div>\n    <div class=\"card mt\">\n      <div class=\"h2\">السلة — مسودة لا تحفظ مالاً<\/div>\n      <div id=\"cloudSaleCart\" class=\"ledger\"><\/div>\n      <p id=\"cloudSaleTotal\" class=\"h2\">الإجمالي: —<\/p>\n    <\/div>\n    <form id=\"cloudSaleForm\" class=\"card mt\">\n      <div class=\"h2\">مراجعة الدفع ثم تأكيد بيدك<\/div>\n      <label for=\"cloudSalePaid\">النقد المقبوض الآن بالريال اليمني (اكتب 0 للآجل الكامل)<\/label>\n      <input id=\"cloudSalePaid\" inputmode=\"decimal\" placeholder=\"المبلغ الفعلي؛ لا يُفترض 0\" required>\n      <label for=\"cloudSaleCustomer\">الزبون — مطلوب فقط إذا بقي دين<\/label>\n      <select id=\"cloudSaleCustomer\"><option value=\"\">بلا زبون عند السداد النقدي الكامل<\/option><\/select>\n      <p id=\"cloudSaleDue\" class=\"hint\">الباقي بالدين: —<\/p>\n      <p class=\"small muted\">بيع البضاعة بالدين ينشئ فاتورة ويخصم المخزون ولا يصرف أي نقد. السلفة النقدية منفصلة في شاشة الزبائن وللمالك فقط في هذه التجربة.<\/p>\n      <p class=\"small muted\">لا يرسل هذا الإصدار SMS تلقائياً؛ موافقة الزبون على SMS وإذن الشريحة والإرسال مسار مستقل لم يُختبر على هاتف.<\/p>\n      <button id=\"cloudSaleSubmit\" class=\"btn p wide\" type=\"submit\" disabled>تأكيد الفاتورة الخادمية<\/button>\n    <\/form>\n    <div id=\"cloudSaleReceipt\" class=\"card mt\" hidden><\/div>\n  <\/div>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script src=\"cloud-shift.js\"><\/script>\n<script src=\"cloud-ledger.js\"><\/script>\n<script>window.RafiqCloudLedger.mount('pos');<\/script>\n{% endblock %}\n", "cloud_remote_eye.html": "{% extends \"base.html\" %}\n{% block title %}العين عن بُعد{% endblock %}\n{% block content %}\n<div id=\"cloudEye\" data-local-uid=\"{{ u.id }}\" data-local-role=\"{{ u.role }}\">\n  <div class=\"h1\">👁️ العين عن بُعد — سجل المالك<\/div>\n  <p class=\"hint\">صفحة مستقلة للمالك تسحب أحدث حركات المتجر من الخادم. تُظهر الحدث الموثّق، لكنها ليست Push خلفية ولا إثباتاً لوصول إشعار الهاتف بنغمة.<\/p>\n  <div id=\"cloudLedgerMessage\" class=\"flash error\" role=\"status\" aria-live=\"polite\">ادخل حساب المالك الخادمي من الصندوق أولاً.<\/div>\n  <div id=\"cloudEyeLocked\" class=\"card mt\"><a href=\"/cash\">دخول حساب المتجر من الصندوق<\/a>.<\/div>\n  <div id=\"cloudEyeActive\" hidden>\n    <div class=\"row wrap\">\n      <button id=\"cloudEyeRefresh\" class=\"btn sm ghost\" type=\"button\">تحديث أحداث الخادم<\/button>\n      <button id=\"cloudEyeSound\" class=\"btn sm ghost\" type=\"button\">تفعيل نغمة المالك أثناء فتح التطبيق فقط<\/button>\n    <\/div>\n    <p class=\"small muted\">النغمة بعد لمس الزر وأثناء ظهور الصندوق أو اللوحة أو العين (وبعد تفعيلها أيضاً عند فتح الزبائن). لا تعتمد عليها كتنبيه للمالك إذا أغلق الهاتف أو خرج من التطبيق؛ Push يحتاج خدمة موثوقة وإذناً واختباراً منفصلاً.<\/p>\n    <div id=\"cloudEyeStats\" class=\"grid g4 mt\"><\/div>\n    <div id=\"cloudEyeEvents\" class=\"ledger mt\"><\/div>\n  <\/div>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script src=\"cloud-shift.js\"><\/script>\n<script src=\"cloud-ledger.js\"><\/script>\n<script>window.RafiqCloudLedger.mount('eye');<\/script>\n{% endblock %}\n", "cloud_setup.html": "{% extends \"base.html\" %}\n{% block title %}تهيئة سحابة المتجر{% endblock %}\n{% block content %}\n<div class=\"h1\">☁️ تهيئة سحابة المتجر<\/div>\n<div class=\"flash error mt\" role=\"status\">الإعداد المحلي لا يفعّل المزامنة أو واتساب أو روابط الفواتير. لن تُرفع بيانات زبائنك حتى يكتمل دخول صاحب المتجر وصلاحيات RLS وتُختبر المزامنة على هاتفين.<\/div>\n<div class=\"card mt\" id=\"cloudBootstrapStatus\" data-verified=\"false\">\n  <div class=\"h2\">حالة الربط<\/div>\n  <div class=\"muted small\">{{ 'بيانات المشروع محفوظة على هذا الهاتف فقط؛ الاتصال غير مُتحقَّق منه' if configured else 'لم تُدخل بيانات مشروع هذا المتجر بعد' }}<\/div>\n  {% if configured %}<div class=\"hint mt\">العنوان الحالي: <span dir=\"ltr\">{{ project_url }}<\/span><br>المفتاح العام: محفوظ مشفّراً ولا يظهر مجدداً.<\/div>{% endif %}\n<\/div>\n<div class=\"card mt\">\n  <div class=\"h2\">عنوان مشروع Supabase والمفتاح العام<\/div>\n  <div class=\"hint\">استخدم رابط <b>مشروعك<\/b> من لوحة Supabase، وليس موقع Supabase الرئيسي. لا تُدخل `service_role` أو `sb_secret_` أو كلمة المرور أو مفتاح رخصة المالك.<\/div>\n  <form method=\"post\" action=\"/cloud/setup\" autocomplete=\"off\" id=\"cloudSetupForm\">\n    <label for=\"cloudProjectUrl\">Project URL<\/label>\n    <input id=\"cloudProjectUrl\" name=\"project_url\" type=\"url\" inputmode=\"url\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\" dir=\"ltr\" maxlength=\"160\" required placeholder=\"https://[project-ref].supabase.co\" value=\"{{ project_url or '' }}\">\n    <label for=\"cloudPublishableKey\">Anon / Publishable Key<\/label>\n    <input id=\"cloudPublishableKey\" name=\"publishable_key\" type=\"password\" autocomplete=\"new-password\" autocapitalize=\"off\" spellcheck=\"false\" dir=\"ltr\" maxlength=\"4096\" required value=\"\" placeholder=\"المفتاح العام فقط، ليس المفتاح السري\">\n    {% if configured %}<div class=\"check mt\"><input id=\"cloudReplace\" name=\"confirm_replace\" type=\"checkbox\" value=\"1\"><label for=\"cloudReplace\" style=\"margin:0\">أفهم أن تغيير مشروع المتجر قد يوجّه البيانات إلى خادم آخر، وأريد استبدال الإعداد المحلي.<\/label><\/div>{% endif %}\n    <button class=\"btn p lg wide mt\" type=\"submit\">حفظ التهيئة على هذا الهاتف فقط<\/button>\n  <\/form>\n<\/div>\n{% if first_run and not configured %}\n<form method=\"post\" action=\"/cloud/setup/skip\" class=\"mt\">\n  <button class=\"btn ghost wide\" type=\"submit\">العمل محلياً الآن — تخطي التهيئة السحابية مؤقتاً<\/button>\n<\/form>\n{% endif %}\n<div class=\"hint mt\">حفظ الإعداد محمي بمفتاح Android Keystore على هذا الجهاز، وخارج النسخ الاحتياطية. يحتاج هاتف العامل إعداد انضمام موثوقاً لاحقاً؛ لا تنقل المفتاح الخاص أو بيانات الزبائن بين الهواتف يدوياً.<\/div>\n<a class=\"btn ghost wide mt\" href=\"/settings\">← العودة للإعدادات<\/a>\n{% endblock %}\n", "license.html": "{% extends \"base.html\" %}\n{% block title %}الرخصة{% endblock %}\n{% block wrap %}\n<div class=\"wrap\">\n<div class=\"card login-card\">\n  <div class=\"center\">\n    <div style=\"font-size:42px\">{{ '✅' if ok else '🔒' }}<\/div>\n    <h2 style=\"margin:6px 0\">{{ 'الرخصة مُفعّلة' if ok else 'تفعيل رفيق' }}<\/h2>\n    <div class=\"muted small\">{{ reason }}<\/div>\n  <\/div>\n\n  {% if name %}\n  <div class=\"mt\"><b>المرخّص له:<\/b> {{ name }}<\/div>\n  {% endif %}\n  {% if expires %}\n  <div class=\"mt\"><b>تنتهي في:<\/b> {{ expires }}<\/div>\n  {% endif %}\n\n  <div class=\"mt\">\n    <div class=\"muted small\">معرّف جهازك (أرسله إلى المالك لإصدار الرخصة):<\/div>\n    <div class=\"mt\" style=\"user-select:all;direction:ltr;font-family:monospace;word-break:break-all;padding:10px;border:1px dashed #999;border-radius:8px\">{{ device }}<\/div>\n  <\/div>\n\n  <form method=\"post\" action=\"/license\" class=\"mt\">\n    <label class=\"muted small\" for=\"tok\">الصق مفتاح الرخصة:<\/label>\n    <textarea id=\"tok\" name=\"token\" rows=\"4\" style=\"width:100%;direction:ltr;font-family:monospace\" placeholder=\"RFQ1....\" required><\/textarea>\n    <button class=\"btn p lg wide mt\" type=\"submit\">تفعيل<\/button>\n  <\/form>\n  <div class=\"hint mt\">حتى عند انتهاء الرخصة، يستطيع صاحب المتجر حفظ نسخة مشفّرة من بياناته؛ لا يفتح ذلك البيع.<\/div>\n  <a class=\"btn ghost wide mt\" href=\"{{ '/rescue' if u and u.role == 'owner' else '/login' }}\">🔐 دخول المالك / إنقاذ نسخة البيانات<\/a>\n<\/div>\n<\/div>\n{% endblock %}\n", "rescue.html": "{% extends \"base.html\" %}\n{% block title %}نسخة نجاة للمالك{% endblock %}\n{% block wrap %}\n<div class=\"wrap\">\n  <div class=\"card mt\">\n    <div class=\"h1\">🔐 نسخ بياناتك بأمان<\/div>\n    <div class=\"flash {{ 'ok' if license_ok else 'error' }} mt\">{% if license_ok %}الرخصة سارية؛ هذه صفحة نسخ نجاة اختيارية.{% else %}الرخصة غير سارية أو تحتاج تجديداً. البيع وتعديل البيانات معطلان؛ يستطيع المالك فقط تصدير نسخة مشفّرة وفحصها.{% endif %}<\/div>\n    <div class=\"hint mt\">الاستعادة غير متاحة في هذه النسخة. لا تحذف التطبيق أو بياناته، ولا تعتبر التصدير ناجحاً حتى يؤكد حفظ الملف وفحص مطابقته.<\/div>\n    <label for=\"backupPhrase\">عبارة مرور جديدة للنسخة (12–256 حرفاً)<\/label>\n    <input id=\"backupPhrase\" type=\"password\" minlength=\"12\" maxlength=\"256\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"اكتب عبارة لا تعرفها إلا أنت\">\n    <label for=\"backupConfirm\">تأكيد العبارة<\/label>\n    <input id=\"backupConfirm\" type=\"password\" minlength=\"12\" maxlength=\"256\" autocomplete=\"off\" spellcheck=\"false\">\n    <button id=\"backupExport\" class=\"btn p wide mt\" type=\"button\">حفظ نسخة مشفّرة في ملف<\/button>\n    <label for=\"backupInspectPhrase\">لفحص ملف محفوظ: عبارة مروره<\/label>\n    <input id=\"backupInspectPhrase\" type=\"password\" minlength=\"12\" maxlength=\"256\" autocomplete=\"off\" spellcheck=\"false\">\n    <button id=\"backupInspect\" class=\"btn ghost wide mt\" type=\"button\">اختيار ملف وفحصه (دون استعادة)<\/button>\n    <div id=\"backupStatus\" class=\"hint mt\" role=\"status\" aria-live=\"polite\"><\/div>\n    <a class=\"btn ghost wide mt\" href=\"/license\">← العودة لتفعيل الرخصة<\/a>\n    <a class=\"btn ghost wide mt\" href=\"/logout\">خروج<\/a>\n  <\/div>\n<\/div>\n{% endblock %}\n{% block scripts %}\n<script>\n(function(){\n  var status=document.getElementById('backupStatus');\n  if(!status) return;\n  function update(message, ok){\n    var current=document.getElementById('backupStatus');\n    if(!current) return;\n    current.textContent=message;\n    current.style.color=ok === false ? '#a52222' : '#17513c';\n    var x=document.getElementById('backupExport'), y=document.getElementById('backupInspect');\n    if(x) x.disabled=false;\n    if(y) y.disabled=false;\n  }\n  window.__rafiqBackupResult=update;\n  function start(kind){\n    var device=window.RafiqDevice;\n    if(!device || !device.backupExport || !device.backupInspect){\n      update('هذه الوظيفة متاحة في تطبيق أندرويد فقط.', false); return;\n    }\n    var a=document.getElementById(kind === 'export' ? 'backupPhrase' : 'backupInspectPhrase');\n    var c=document.getElementById('backupConfirm');\n    var phrase=a.value;\n    if(phrase.length < 12 || phrase.length > 256){ update('اكتب عبارة مرور بين 12 و256 حرفاً.', false); return; }\n    if(kind === 'export' && phrase !== c.value){ update('تأكيد عبارة المرور لا يطابقها.', false); return; }\n    a.value='';\n    if(kind === 'export') c.value='';\n    var x=document.getElementById('backupExport'), y=document.getElementById('backupInspect');\n    x.disabled=true; y.disabled=true;\n    status.textContent=kind === 'export' ? 'جارٍ تجهيز النسخة؛ انتظر اختيار مكان حفظها…' : 'اختر ملف النسخة لفحصه…';\n    status.style.color='#17513c';\n    try {\n      var accepted=kind === 'export' ? device.backupExport(phrase) : device.backupInspect(phrase);\n      if(!accepted) update('تعذّر بدء العملية: تأكّد من دخول المالك والعبارة وعدم وجود عملية أخرى.', false);\n    } catch(e){ update('تعذّر بدء العملية. أعد المحاولة.', false); }\n  }\n  document.getElementById('backupExport').onclick=function(){ start('export'); };\n  document.getElementById('backupInspect').onclick=function(){ start('inspect'); };\n})();\n<\/script>\n{% endblock %}\n", "setup.html": "{% extends \"base.html\" %}\n{% block title %}تأمين الحسابات{% endblock %}\n{% block wrap %}\n<div class=\"wrap\">\n  {% set msgs = get_flashed_messages(with_categories=true) %}\n  {% for cat, m in msgs %}<div class=\"flash {{ cat }}\">{{ m }}<\/div>{% endfor %}\n  <div class=\"card login-card mt\">\n    <div class=\"h1\">🔐 تأمين المتجر قبل أول بيع<\/div>\n    <p>رموز النسخة التجريبية معروفة. اختر الآن رمزاً جديداً لحساب المالك؛ لا يبدأ البيع في إصدار النشر قبل هذه الخطوة.<\/p>\n    <form method=\"post\" action=\"/setup\">\n      <label for=\"setupPin\">رمز المالك الجديد — أربعة أرقام غير تجريبية<\/label>\n      <input id=\"setupPin\" name=\"new_pin\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{4}\" minlength=\"4\" maxlength=\"4\" autocomplete=\"new-password\" required>\n      <label for=\"setupConfirm\">تأكيد الرمز الجديد<\/label>\n      <input id=\"setupConfirm\" name=\"confirm_pin\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{4}\" minlength=\"4\" maxlength=\"4\" autocomplete=\"new-password\" required>\n      <div class=\"hint mt\">ستُوقَف الحسابات التي لا تزال تستعمل الرموز الافتراضية. بعد الدخول، غيّر رمز أي عامل موقوف من الإعدادات لتفعيله، أو أضف عمالاً جدداً. لا تشارك رمزك مع أحد.<\/div>\n      <button class=\"btn p lg wide mt\" type=\"submit\">حفظ الرمز وتأمين الحسابات<\/button>\n    <\/form>\n    <a class=\"btn ghost wide mt\" href=\"/logout\">خروج<\/a>\n  <\/div>\n<\/div>\n{% endblock %}\n", "statement_print.html": "{% extends \"base.html\" %}\n{% block title %}كشف حساب {{ c.name }}{% endblock %}\n{% block wrap %}\n<div class=\"wrap\">\n  <div class=\"row no-print\">\n    <div class=\"h1 grow\">كشف حساب {{ c.name }}<\/div>\n    <button class=\"btn sm p\" onclick=\"window.print()\">🖨 طباعة<\/button>\n  <\/div>\n  <div class=\"a4 mt\">\n    {% if S.store_logo %}<img src=\"{{ S.store_logo }}\" alt=\"\" style=\"max-height:70px;display:block;margin:0 auto 6px\">{% endif %}\n    <h2>{{ S.store_name or 'المتجر' }}<\/h2>\n    <div class=\"center\">كشف حساب زبون<\/div>\n    {% if not audit_ok %}<div class=\"center\" style=\"color:#b91c1c;font-weight:bold\">⚠ لا تعتمد هذا الكشف: مجموع الحركات لا يطابق الرصيد. راجع البيانات أولاً.<\/div>{% endif %}\n    <table>\n      <tr><td>الاسم<\/td><td>{{ c.name }}<\/td><\/tr>\n      <tr><td>رمز الزبون<\/td><td dir=\"ltr\">{{ c.code }}<\/td><\/tr>\n      <tr><td>الهاتف<\/td><td dir=\"ltr\">{{ c.phone }}<\/td><\/tr>\n      <tr><td>تاريخ الطباعة<\/td><td>{{ today }}<\/td><\/tr>\n    <\/table>\n    <table>\n      <tr><th>التاريخ<\/th><th>البيان<\/th><th>المدخل<\/th><th>أعطيت (دين)<\/th><th>أخذت / افتتاحي دائن<\/th><th>الرصيد بعده<\/th><\/tr>\n      {% for e in ev %}\n      <tr>\n        <td>{% if e.kind == 'credit_opening' %}قبل بدء النظام{% else %}{{ e.ts }}{% endif %}<\/td>\n        <td>{{ e.note }}<\/td>\n        <td>{{ e.user }}<\/td>\n        <td>{% if e.kind == 'given' %}{{ e.amount_fmt }}{% endif %}<\/td>\n        <td>{% if e.kind == 'taken' or e.kind == 'credit_opening' %}{{ e.amount_fmt }}{% endif %}<\/td>\n        <td>{{ e.balance_fmt }}<\/td>\n      <\/tr>\n      {% else %}\n      <tr><td colspan=\"6\">لا توجد حركات<\/td><\/tr>\n      {% endfor %}\n    <\/table>\n    <div class=\"grand mt\">{% if c.balance_cents > 0 %}الدين المتبقي: {{ c.balance_fmt }}{% elif c.balance_cents < 0 %}رصيد لصالح الزبون: {{ c.balance_fmt }}{% else %}الرصيد مسدّد: {{ c.balance_fmt }}{% endif %}<\/div>\n  <\/div>\n<\/div>\n{% endblock %}\n", "supplier_print.html": "{% extends \"base.html\" %}\n{% block title %}كشف حساب {{ s.name }}{% endblock %}\n{% block wrap %}\n<div class=\"wrap\">\n  <div class=\"row no-print\">\n    <div class=\"h1 grow\">كشف حساب مورد: {{ s.name }}<\/div>\n    <button class=\"btn sm p\" onclick=\"window.print()\">🖨 طباعة<\/button>\n  <\/div>\n  <div class=\"a4 mt\">\n    {% if S.store_logo %}<img src=\"{{ S.store_logo }}\" alt=\"\" style=\"max-height:70px;display:block;margin:0 auto 6px\">{% endif %}\n    <h2>{{ S.store_name or 'المتجر' }}<\/h2>\n    <div class=\"center\">كشف حساب مورد<\/div>\n    <table>\n      <tr><td>المورد<\/td><td>{{ s.name }}<\/td><\/tr>\n      <tr><td>الهاتف<\/td><td dir=\"ltr\">{{ s.phone }}<\/td><\/tr>\n      <tr><td>تاريخ الطباعة<\/td><td>{{ today }}<\/td><\/tr>\n    <\/table>\n    <table>\n      <tr><th>التاريخ<\/th><th>النوع<\/th><th>البيان<\/th><th>المبلغ<\/th><th>الرصيد الجاري<\/th><\/tr>\n      {% for e in ev %}\n      <tr><td>{{ e.ts }}<\/td><td>{{ e.label }}<\/td><td>{{ e.note }}<\/td><td>{{ e.amount_fmt }}<\/td><td>{{ e.balance_fmt }}<\/td><\/tr>\n      {% else %}\n      <tr><td colspan=\"5\">لا توجد حركات<\/td><\/tr>\n      {% endfor %}\n    <\/table>\n    <div class=\"grand mt\">الرصيد الحالي: {{ s.balance_fmt }}<\/div>\n  <\/div>\n<\/div>\n{% endblock %}\n"};
